window.E_DASHBOARD_UNITS = [{"unit":1,"theme":"People 人物（第01區）","cards":[{"w":"man","p":"n.","d":"","c":"男人","s":"Q: Who is that? — A: That man is Tom's father. He is a doctor.","t":"那是誰？ — 那個男人是湯姆的爸爸，他是醫生。"},{"w":"men","p":"n.","d":"","c":"男人們（複數）","s":"Q: Who are those? — A: Those men are Ben and Ken's uncles.","t":"那些是誰？ — 那些男人是班和肯的叔叔。"},{"w":"woman","p":"n.","d":"","c":"女人","s":"Q: Who is this? — A: This woman is my mom's friend, Ms. Lin.","t":"這是誰？ — 這位女士是我媽媽的朋友，林女士。"},{"w":"women","p":"n.","d":"","c":"女人們（複數）","s":"Q: Who are these? — A: These women are Amy and Lisa's aunts.","t":"這些是誰？ — 這些女士是艾美和麗莎的阿姨。"},{"w":"person","p":"n.","d":"","c":"人","s":"Q: Who is that? — A: That person is my English teacher. She is very kind.","t":"那是誰？ — 那個人是我的英文老師，她很親切。"},{"w":"people","p":"n.","d":"","c":"人們","s":"Q: Who are those? — A: Those people are my dad's friends from work.","t":"那些是誰？ — 那些人是我爸爸的同事朋友。"},{"w":"guy","p":"n.","d":"","c":"傢伙","s":"Q: Who is that? — A: That guy is Ken's cousin. He is very funny.","t":"那是誰？ — 那個傢伙是肯的表哥，他很好笑。"},{"w":"children","p":"n.","d":"","c":"小孩們（複數）","s":"Q: Who are these? — A: These children are my aunt's. They are my cousins.","t":"這些是誰？ — 這些小孩是我阿姨的，他們是我的表兄弟姊妹。"},{"w":"neighbor","p":"n.","d":"","c":"鄰居","s":"Q: Who is this? — A: This is my neighbor, Mr. Chen. He lives next door.","t":"這是誰？ — 這是我的鄰居陳先生，他住在隔壁。"},{"w":"neighborhood","p":"n.","d":"","c":"社區；鄰近地區","s":"Q: Who are those kids? — A: They are kids from my neighborhood. We often play together.","t":"那些小孩是誰？ — 他們是我們社區的小孩，我們常常一起玩。"},{"w":"visitor","p":"n.","d":"","c":"訪客","s":"Q: Who is that? — A: That is our visitor from Japan. She is Amy's friend.","t":"那是誰？ — 那是我們來自日本的訪客，她是艾美的朋友。"},{"w":"stranger","p":"n.","d":"","c":"陌生人","s":"Q: Who is that man at the door? — A: I don't know. He is a stranger. Don't open the door.","t":"門口那個男人是誰？ — 我不知道，他是陌生人，不要開門。"},{"w":"king","p":"n.","d":"","c":"國王","s":"Q: Who is this in the picture? — A: This is the king of the country. He lives in a big castle.","t":"照片裡這是誰？ — 這是這個國家的國王，他住在一座大城堡裡。"},{"w":"queen","p":"n.","d":"","c":"皇后","s":"Q: Who is that? — A: That is the queen. She is the king's wife.","t":"那是誰？ — 那是皇后，她是國王的太太。"},{"w":"prince","p":"n.","d":"","c":"王子","s":"Q: Who is this? — A: This is the prince. He is the king and queen's son.","t":"這是誰？ — 這是王子，他是國王和皇后的兒子。"},{"w":"princess","p":"n.","d":"","c":"公主","s":"Q: Who is that? — A: That is the princess. She is the king and queen's daughter.","t":"那是誰？ — 那是公主，她是國王和皇后的女兒。"},{"w":"giant","p":"n.","d":"","c":"巨人","s":"Q: Who is that in the story? — A: That is a giant. He is very, very tall.","t":"故事裡那是誰？ — 那是一個巨人，他非常非常高。"},{"w":"fool","p":"n.","d":"","c":"傻子","s":"Q: Who is this in the story? — A: This is a fool. He often does stupid things.","t":"故事裡這是誰？ — 這是一個傻子，他常常做蠢事。"},{"w":"baby","p":"n.","d":"","c":"嬰兒","s":"Q: How old is Lisa's little sister? — A: She is a baby. She is one year old.","t":"麗莎的小妹妹幾歲？ — 她是個嬰兒，她一歲。"},{"w":"child","p":"n.","d":"","c":"小孩","s":"Q: How old is Ms. Lin's son? — A: He is a small child. He is six years old.","t":"林女士的兒子幾歲？ — 他是個小孩子，他六歲。"},{"w":"kid","p":"n.","d":"","c":"小孩","s":"Q: How old are your cousin's kids? — A: His kids are five and seven years old.","t":"你表哥的小孩幾歲？ — 他的小孩們五歲和七歲。"},{"w":"boy","p":"n.","d":"","c":"男孩","s":"Q: How old is Amy's brother? — A: The boy is ten years old.","t":"艾美的弟弟幾歲？ — 那個男孩十歲。"},{"w":"girl","p":"n.","d":"","c":"女孩","s":"Q: How old is Ben's sister? — A: The little girl is eight years old.","t":"班的妹妹幾歲？ — 那個小女孩八歲。"},{"w":"teenager","p":"n.","d":"","c":"青少年","s":"Q: How old is your brother? — A: He is fifteen years old. He is a teenager.","t":"你哥哥幾歲？ — 他十五歲，他是個青少年。"}]},{"unit":2,"theme":"Personal characteristics 個人特質（第02區）","cards":[{"w":"happy","p":"adj.","d":"","c":"快樂的","s":"Q: How are you today? — A: I am happy. I got 100 on the test.","t":"你今天好嗎？ — 我很快樂，我考試考了一百分。"},{"w":"unhappy","p":"adj.","d":"","c":"不快樂的","s":"Q: How is Ben? — A: He is unhappy. He lost his new bike.","t":"班還好嗎？ — 他不開心，他弄丟了新腳踏車。"},{"w":"sad","p":"adj.","d":"","c":"悲傷的","s":"Q: How is Tom? — A: He is sad. His dog is sick.","t":"湯姆還好嗎？ — 他很難過，他的狗生病了。"},{"w":"lonely","p":"adj.","d":"","c":"寂寞的","s":"Q: How is your grandma? — A: She is lonely. She lives alone.","t":"你奶奶還好嗎？ — 她很寂寞，她一個人住。"},{"w":"angry","p":"adj.","d":"","c":"生氣的","s":"Q: How is your dad today? — A: He is angry. I broke his cup.","t":"你爸爸今天還好嗎？ — 他很生氣，我打破了他的杯子。"},{"w":"mad","p":"adj.","d":"","c":"生氣的；瘋狂的","s":"Q: How is Mom? — A: She is mad at me. My room is very dirty.","t":"媽媽還好嗎？ — 她在生我的氣，我的房間很髒。"},{"w":"scared","p":"adj.","d":"","c":"害怕的","s":"Q: How are the kids? — A: They are scared. There is a big snake!","t":"孩子們還好嗎？ — 他們很害怕，有一條大蛇！"},{"w":"bored","p":"adj.","d":"","c":"感到厭煩的","s":"Q: How are the students? — A: They are bored. The movie is too long.","t":"學生們還好嗎？ — 他們覺得很無聊，電影太長了。"},{"w":"excited","p":"adj.","d":"","c":"感到興奮的","s":"Q: How is Amy? — A: She is excited. Tomorrow is her birthday.","t":"艾美還好嗎？ — 她很興奮，明天是她的生日。"},{"w":"proud","p":"adj.","d":"","c":"驕傲的","s":"Q: How are your parents? — A: They are proud of me. I won the race.","t":"你爸媽還好嗎？ — 他們以我為榮，我贏了賽跑。"},{"w":"busy","p":"adj.","d":"","c":"忙碌的","s":"Q: How is your mom? — A: She is very busy. She has a lot of work.","t":"你媽媽還好嗎？ — 她很忙，她有很多工作。"},{"w":"cute","p":"adj.","d":"","c":"可愛的","s":"Q: What does your baby sister look like? — A: She is small and cute. She has big eyes.","t":"你的小妹妹長什麼樣子？ — 她小小的很可愛，她有大眼睛。"},{"w":"lovely","p":"adj.","d":"","c":"可愛的","s":"Q: What do the twins look like? — A: They are lovely. They always smile.","t":"那對雙胞胎長什麼樣子？ — 他們很可愛，總是笑咪咪的。"},{"w":"pretty","p":"adj.","d":"","c":"漂亮的","s":"Q: What does Amy look like? — A: She is pretty. She has long hair.","t":"艾美長什麼樣子？ — 她很漂亮，她有一頭長髮。"},{"w":"handsome","p":"adj.","d":"","c":"英俊的","s":"Q: What does your brother look like? — A: He is tall and handsome.","t":"你哥哥長什麼樣子？ — 他又高又帥。"},{"w":"slim","p":"adj.","d":"","c":"苗條的","s":"Q: What does the model look like? — A: She is tall and slim.","t":"那位模特兒長什麼樣子？ — 她又高又苗條。"},{"w":"ugly","p":"adj.","d":"","c":"醜的","s":"Q: What does the monster in the story look like? — A: It is big and ugly.","t":"故事裡的怪物長什麼樣子？ — 牠又大又醜。"},{"w":"kind","p":"adj.","d":"","c":"親切的","s":"Q: What do you think of your grandma? — A: She is kind because she often gives food to poor people.","t":"你覺得你奶奶怎麼樣？ — 她很親切，因為她常常送食物給窮人。"},{"w":"nice","p":"adj.","d":"","c":"好的","s":"Q: What do you think of your teacher? — A: She is nice because she often helps us with our homework.","t":"你覺得你的老師怎麼樣？ — 她人很好，因為她常常幫我們做功課。"},{"w":"friendly","p":"adj.","d":"","c":"友善的","s":"Q: What do you think of your new neighbor? — A: She is friendly because she often says hello to us.","t":"你覺得你的新鄰居怎麼樣？ — 她很友善，因為她常常跟我們打招呼。"},{"w":"polite","p":"adj.","d":"","c":"有禮貌的","s":"Q: What do you think of Lisa? — A: She is polite because she often says \"please\" and \"thank you.\"","t":"你覺得麗莎怎麼樣？ — 她很有禮貌，因為她常說「請」和「謝謝」。"},{"w":"honest","p":"adj.","d":"","c":"誠實的","s":"Q: What do you think of Tom? — A: He is honest because he often tells the truth.","t":"你覺得湯姆怎麼樣？ — 他很誠實，因為他常常說實話。"},{"w":"brave","p":"adj.","d":"","c":"勇敢的","s":"Q: What do you think of Ben? — A: He is brave because he often helps people in trouble.","t":"你覺得班怎麼樣？ — 他很勇敢，因為他常常幫助有麻煩的人。"},{"w":"careful","p":"adj.","d":"","c":"仔細的","s":"Q: What do you think of your mom? — A: She is careful because she often checks the door before bed.","t":"你覺得你媽媽怎麼樣？ — 她很仔細，因為她睡前常常檢查門。"},{"w":"hard-working","p":"adj.","d":"","c":"努力工作的","s":"Q: What do you think of Amy? — A: She is hard-working because she often studies until ten at night.","t":"你覺得艾美怎麼樣？ — 她很努力，因為她常常讀書到晚上十點。"},{"w":"lazy","p":"adj.","d":"","c":"懶惰的","s":"Q: What do you think of Ken? — A: He is lazy because he often sleeps in class.","t":"你覺得肯怎麼樣？ — 他很懶惰，因為他常常在課堂上睡覺。"},{"w":"funny","p":"adj.","d":"","c":"好笑的","s":"Q: What do you think of Mr. Lee? — A: He is funny because he often tells jokes.","t":"你覺得李老師怎麼樣？ — 他很好笑，因為他常常講笑話。"},{"w":"shy","p":"adj.","d":"","c":"害羞的","s":"Q: What do you think of the new student? — A: He is shy because he often stays quiet in class.","t":"你覺得那位新同學怎麼樣？ — 他很害羞，因為他上課常常很安靜。"},{"w":"wise","p":"adj.","d":"","c":"明智的","s":"Q: What do you think of your grandpa? — A: He is wise because he often gives me good ideas.","t":"你覺得你爺爺怎麼樣？ — 他很有智慧，因為他常常給我好主意。"},{"w":"stupid","p":"adj.","d":"","c":"笨的","s":"Q: What do you think of the fox in the story? — A: It is stupid because it often makes the same mistake.","t":"你覺得故事裡的狐狸怎麼樣？ — 牠很笨，因為牠常常犯同樣的錯。"},{"w":"successful","p":"adj.","d":"","c":"成功的","s":"Q: What do you think of your uncle? — A: He is successful because he often sells a lot of cars.","t":"你覺得你叔叔怎麼樣？ — 他很成功，因為他常常賣出很多車。"},{"w":"good","p":"adj.","d":"","c":"好的","s":"Q: Is Amy good at English? — A: Yes, she is. She can speak English well.","t":"艾美的英文很好嗎？ — 是的，她是。她英文說得很好。"},{"w":"bad","p":"adj.","d":"","c":"壞的","s":"Q: Is the weather bad today? — A: Yes, it is. There is a typhoon.","t":"今天天氣很糟嗎？ — 是的，很糟。有颱風。"},{"w":"cool","p":"adj.","d":"","c":"涼爽的","s":"Q: Is it cool today? — A: Yes, it is. Wear a jacket.","t":"今天很涼嗎？ — 是的，很涼。穿件夾克吧。"},{"w":"boring","p":"adj.","d":"","c":"無聊的","s":"Q: Is the movie boring? — A: Yes, it is. I want to sleep.","t":"這部電影很無聊嗎？ — 是的，很無聊。我想睡覺。"},{"w":"exciting","p":"adj.","d":"","c":"令人興奮的","s":"Q: Is the baseball game exciting? — A: Yes, it is. Everyone is shouting.","t":"這場棒球賽很刺激嗎？ — 是的，很刺激。每個人都在大叫。"},{"w":"interested","p":"adj.","d":"","c":"感興趣的","s":"Q: Are you interested in music? — A: Yes, I am. I play the piano every day.","t":"你對音樂有興趣嗎？ — 是的，我有。我每天彈鋼琴。"},{"w":"crazy","p":"adj.","d":"","c":"瘋狂的","s":"Q: Is Tom crazy about basketball? — A: Yes, he is. He plays it every day.","t":"湯姆很迷籃球嗎？ — 是的，他是。他每天都打籃球。"},{"w":"poor","p":"adj.","d":"","c":"貧困的；可憐的","s":"Q: Is the family poor? — A: Yes, they are. They don't have money for food.","t":"那一家人很窮嗎？ — 是的，他們很窮。他們沒有錢買食物。"},{"w":"blind","p":"adj.","d":"","c":"瞎的","s":"Q: Is the old man blind? — A: Yes, he is. He can't see.","t":"那位老先生眼睛看不見嗎？ — 是的，他是。他看不見。"},{"w":"tall","p":"adj.","d":"","c":"高的","s":"Tom is 160 cm, and Ben is 150 cm. — Tom is taller than Ben.","t":"湯姆 160 公分，班 150 公分。— 湯姆比班高。"},{"w":"short","p":"adj.","d":"","c":"矮的；短的","s":"Amy is 145 cm, and Lisa is 140 cm. — Lisa is shorter than Amy.","t":"艾美 145 公分，麗莎 140 公分。— 麗莎比艾美矮。"},{"w":"heavy","p":"adj.","d":"","c":"重的","s":"The box is 10 kg, and the bag is 2 kg. — The box is heavier than the bag.","t":"箱子 10 公斤，袋子 2 公斤。— 箱子比袋子重。"},{"w":"thin","p":"adj.","d":"","c":"瘦的","s":"Dad is 80 kg, and Uncle Sam is 60 kg. — Uncle Sam is thinner than Dad.","t":"爸爸 80 公斤，山姆叔叔 60 公斤。— 山姆叔叔比爸爸瘦。"},{"w":"rich","p":"adj.","d":"","c":"有錢的","s":"Q: Who has more money, the king or the farmer? — A: The king. He is richer than the farmer.","t":"誰的錢比較多，國王還是農夫？— 國王，他比農夫有錢。"},{"w":"famous","p":"adj.","d":"","c":"有名的","s":"Q: Who do more people know, the movie star or your neighbor? — A: The movie star. She is more famous than my neighbor.","t":"比較多人認識誰，電影明星還是你的鄰居？— 電影明星，她比我的鄰居有名。"},{"w":"old","p":"adj.","d":"","c":"老的","s":"Q: Who is the oldest in your family? — A: My grandpa. He is ninety years old.","t":"你家裡誰年紀最大？— 我爺爺，他九十歲。"},{"w":"young","p":"adj.","d":"","c":"年輕的","s":"Q: Who is the youngest in your family? — A: My baby sister. She is one year old.","t":"你家裡誰最年輕？— 我的小妹妹，她一歲。"},{"w":"smart","p":"adj.","d":"","c":"聰明的","s":"Q: Who is the smartest student in your class? — A: Amy. She gets 100 on every test.","t":"你們班上最聰明的學生是誰？— 艾美，她每次考試都考一百分。"},{"w":"fat","p":"adj.","d":"","c":"胖的","s":"Q: Which cat is the fattest of all? — A: Kitty. She eats a lot.","t":"哪一隻貓是全部裡面最胖的？— 凱蒂，她吃很多。"},{"w":"beautiful","p":"adj.","d":"","c":"美麗的","s":"Q: Which flower is the most beautiful in the garden? — A: The rose. Everyone loves to look at it.","t":"花園裡哪一種花最美？— 玫瑰，大家都喜歡看它。"}]},{"unit":3,"theme":"Parts of body 身體部位（第03區）","cards":[{"w":"head","p":"n.","d":"","c":"頭","s":"Q: What's wrong, Tom? — A: My head hurts. I didn't sleep well.","t":"湯姆，怎麼了？ — 我的頭好痛，我沒睡好。"},{"w":"eye","p":"n.","d":"","c":"眼睛","s":"Q: What's wrong? — A: My eyes hurt. I played games too long.","t":"怎麼了？ — 我的眼睛好痛，我玩遊戲玩太久了。"},{"w":"ear","p":"n.","d":"","c":"耳朵","s":"Q: What's wrong, Amy? — A: My ear hurts. The music is too loud.","t":"艾美，怎麼了？ — 我的耳朵好痛，音樂太大聲了。"},{"w":"tooth (teeth)","p":"n.","d":"","c":"牙齒","s":"Q: What's wrong? — A: My teeth hurt. I ate too much candy.","t":"怎麼了？ — 我的牙齒好痛，我吃太多糖果了。"},{"w":"throat","p":"n.","d":"","c":"喉嚨","s":"Q: What's wrong with Lisa? — A: Her throat hurts. She can't sing today.","t":"麗莎怎麼了？ — 她的喉嚨痛，她今天不能唱歌。"},{"w":"neck","p":"n.","d":"","c":"脖子","s":"Q: What's wrong, Dad? — A: My neck hurts. I can't turn my head.","t":"爸爸，怎麼了？ — 我的脖子好痛，我不能轉頭。"},{"w":"shoulder","p":"n.","d":"","c":"肩膀","s":"Q: What's wrong? — A: My shoulders hurt. My schoolbag is too heavy.","t":"怎麼了？ — 我的肩膀好痛，我的書包太重了。"},{"w":"arm","p":"n.","d":"","c":"手臂","s":"Q: What's wrong with Ben? — A: His arm hurts. He fell off his bike.","t":"班怎麼了？ — 他的手臂受傷了，他從腳踏車上摔下來。"},{"w":"back","p":"n.","d":"","c":"背","s":"Q: What's wrong, Grandpa? — A: My back hurts. I carried a big box.","t":"爺爺，怎麼了？ — 我的背好痛，我搬了一個大箱子。"},{"w":"stomach","p":"n.","d":"","c":"胃","s":"Q: What's wrong? — A: My stomach hurts. I ate too much ice cream.","t":"怎麼了？ — 我的胃好痛，我吃了太多冰淇淋。"},{"w":"leg","p":"n.","d":"","c":"腿","s":"Q: What's wrong, Mom? — A: My legs hurt. I walked for three hours.","t":"媽媽，怎麼了？ — 我的腿好痛，我走了三個小時。"},{"w":"knee","p":"n.","d":"","c":"膝蓋","s":"Q: What's wrong with Tom? — A: His knee hurts. He fell down in the park.","t":"湯姆怎麼了？ — 他的膝蓋受傷了，他在公園跌倒了。"},{"w":"foot (feet)","p":"n.","d":"","c":"腳","s":"Q: What's wrong? — A: My feet hurt. My new shoes are too small.","t":"怎麼了？ — 我的腳好痛，我的新鞋太小了。"},{"w":"toe","p":"n.","d":"","c":"腳趾","s":"Q: What's wrong, Ken? — A: My toe hurts. I kicked the door.","t":"肯，怎麼了？ — 我的腳趾好痛，我踢到門了。"},{"w":"hand","p":"n.","d":"","c":"手","s":"Q: Mom, can I eat now? — A: Wash your hands first, or you will get sick.","t":"媽媽，我現在可以吃了嗎？ — 先洗手，不然你會生病。"},{"w":"finger","p":"n.","d":"","c":"手指","s":"Q: I just played with the dog. — A: Wash your fingers, and they will be clean again.","t":"我剛剛跟狗玩。 — 洗洗你的手指，這樣它們就會再變乾淨。"},{"w":"nail","p":"n.","d":"","c":"指甲","s":"Q: Are my hands dirty? — A: Yes. Cut your nails, and your hands will look clean.","t":"我的手很髒嗎？ — 是的。剪剪指甲，這樣你的手看起來就會很乾淨。"},{"w":"face","p":"n.","d":"","c":"臉","s":"Q: I just got up. I am still tired. — A: Wash your face, and you will wake up.","t":"我剛起床，還很睏。 — 洗把臉，這樣你就會清醒了。"},{"w":"hair","p":"n.","d":"","c":"頭髮","s":"Q: I played soccer all afternoon. — A: Wash your hair tonight, or it will smell bad.","t":"我踢了一整個下午的足球。 — 今晚要洗頭髮，不然會很臭。"},{"w":"mouth","p":"n.","d":"","c":"嘴巴","s":"Q: My hands are dirty. Can I eat this cookie? — A: Don't touch your mouth with dirty hands, or you will get sick.","t":"我的手很髒，我可以吃這塊餅乾嗎？ — 不要用髒手碰嘴巴，不然你會生病。"},{"w":"lip","p":"n.","d":"","c":"嘴唇","s":"Q: Ouch! My mouth hurts. — A: Don't bite your lips, or they will hurt more.","t":"哎唷！我的嘴巴好痛。 — 不要咬嘴唇，不然會更痛。"},{"w":"nose","p":"n.","d":"","c":"鼻子","s":"Q: Mr. Lee, Ken is doing something bad! — A: Ken, don't pick your nose in class, or your classmates will laugh at you.","t":"李老師，肯在做壞事！ — 肯，上課不要挖鼻孔，不然同學會笑你。"},{"w":"body","p":"n.","d":"","c":"身體","s":"Q: I'm so tired after the game. — A: Wash your body, and you will sleep well tonight.","t":"比賽完我好累。 — 洗個澡，這樣你今晚就會睡得好。"},{"w":"heart","p":"n.","d":"","c":"心","s":"Q: I just ran for ten minutes. — A: Touch your heart, and you can feel it beating fast.","t":"我剛剛跑了十分鐘。 — 摸摸你的心臟，這樣你就能感覺到它跳得很快。"}]},{"unit":4,"theme":"Health 健康（第04區）","cards":[{"w":"cold","p":"n.","d":"","c":"感冒","s":"Q: What's wrong with you? — A: I have a cold. I played in the rain yesterday.","t":"你怎麼了？ — 我感冒了，我昨天在雨中玩。"},{"w":"fever","p":"n.","d":"","c":"發燒","s":"Q: What's wrong with Tom? — A: He has a fever. His head is very hot.","t":"湯姆怎麼了？ — 他發燒了，他的頭很燙。"},{"w":"headache","p":"n.","d":"","c":"頭痛","s":"Q: What's wrong with your mom? — A: She has a headache. The kids are too noisy.","t":"你媽媽怎麼了？ — 她頭痛，小孩們太吵了。"},{"w":"sore","p":"adj.","d":"","c":"疼痛的","s":"Q: What's wrong, Lisa? — A: I have a sore throat. I can't sing today.","t":"麗莎，怎麼了？ — 我喉嚨痛，我今天不能唱歌。"},{"w":"have (has) a runny nose","p":"v.phr.","d":"","c":"流鼻涕","s":"Q: What's wrong with Amy? — A: She has a runny nose. She has a cold, too.","t":"艾美怎麼了？ — 她流鼻涕，她也感冒了。"},{"w":"sick","p":"adj.","d":"","c":"生病的","s":"Q: How does Ben feel today? — A: He feels sick. He can't go to school.","t":"班今天覺得怎麼樣？ — 他覺得不舒服（生病了），他不能去上學。"},{"w":"well","p":"adj.","d":"","c":"（身體）安好的","s":"Q: Does your grandma feel OK today? — A: No, she doesn't. She doesn't feel well. She has a fever.","t":"你奶奶今天覺得還好嗎？ — 不，她不好。她覺得不舒服，她發燒了。"},{"w":"tired","p":"adj.","d":"","c":"疲倦的","s":"Q: How do you feel this morning? — A: I feel tired. I studied until midnight.","t":"你今天早上覺得怎麼樣？ — 我覺得很累，我讀書讀到半夜。"},{"w":"weak","p":"adj.","d":"","c":"虛弱的","s":"Q: How does Grandpa feel? — A: He feels weak. He can't walk far.","t":"爺爺覺得怎麼樣？ — 他覺得很虛弱，他不能走遠。"},{"w":"strong","p":"adj.","d":"","c":"強壯的","s":"Q: Do you feel good after swimming? — A: Yes, I do. I swim every day, so I feel strong.","t":"你游泳後覺得很好嗎？ — 是的，我覺得很好。我每天游泳，所以我覺得很強壯。"},{"w":"healthy","p":"adj.","d":"","c":"健康的","s":"Q: Does your dad feel good? — A: Yes, he does. He runs every morning, so he feels healthy.","t":"你爸爸覺得身體好嗎？ — 是的，他很好。他每天早上跑步，所以他覺得很健康。"},{"w":"comfortable","p":"adj.","d":"","c":"舒適的","s":"Q: How do your new shoes feel? — A: They feel comfortable. I can walk all day.","t":"你的新鞋穿起來怎麼樣？ — 它們很舒適，我可以走一整天。"},{"w":"medicine","p":"n.","d":"","c":"藥","s":"Q: Ben has a fever. What does he have to do? — A: He has to take some medicine and stay in bed.","t":"班發燒了，他必須做什麼？ — 他必須吃一些藥並躺在床上休息。"},{"w":"health","p":"n.","d":"","c":"健康","s":"Q: Does your dad smoke? — A: Yes, he does. He should stop. It's bad for his health.","t":"你爸爸抽菸嗎？ — 是的，他抽菸。他應該戒掉，抽菸對他的健康不好。"},{"w":"life","p":"n.","d":"","c":"生活；生命","s":"Q: Do I have to be rich to be happy? — A: No, you don't have to. You should enjoy your life every day.","t":"我必須很有錢才會快樂嗎？ — 不，你不必。你應該每天享受你的生活。"},{"w":"death","p":"n.","d":"","c":"死亡","s":"Q: Does Tim have to come to school today? — A: No, he doesn't have to. He is sad about the death of his dog.","t":"提姆今天必須來上學嗎？ — 不，他不必。他為他的狗死掉而難過。"}]},{"unit":5,"theme":"Forms of Address 稱謂（第05區）","cards":[{"w":"Mr.","p":"abbr.","d":"","c":"先生（加姓）","s":"Q: Who is that man? — A: He is Mr. Wang. He teaches us math.","t":"那位男士是誰？ — 他是王先生，他教我們數學。"},{"w":"Mrs.","p":"abbr.","d":"","c":"太太","s":"Q: Who is she? Is she Mr. Chen's wife? — A: Yes, she is. She is Mrs. Chen. She works at a bank.","t":"她是誰？她是陳先生的太太嗎？ — 是的，她是。她是陳太太，她在銀行工作。"},{"w":"Miss","p":"n.","d":"","c":"小姐","s":"Q: Who is your new music teacher? — A: She is Miss Lin. She isn't married.","t":"你的新音樂老師是誰？ — 她是林小姐，她還沒結婚。"},{"w":"Ms.","p":"abbr.","d":"","c":"女士","s":"Q: Who is that woman? Does she teach English? — A: Yes, she does. She is Ms. Lee, our English teacher.","t":"那位女士是誰？她教英文嗎？ — 是的，她教。她是李女士，我們的英文老師。"},{"w":"doctor (Dr.)","p":"n.","d":"","c":"醫生","s":"Q: Who is he? Do you know him? — A: Yes, I do. He is Dr. Huang. He works at the hospital.","t":"他是誰？你認識他嗎？ — 是的，我認識。他是黃醫生，他在醫院工作。"},{"w":"name","p":"n.","d":"","c":"名字","s":"Q: What's your name? Do you have an English name? — A: Yes, I do. My English name is Amy.","t":"你叫什麼名字？你有英文名字嗎？— 有，我的英文名字是艾美。"},{"w":"sir","p":"n.","d":"","c":"先生（稱呼，不加姓）","s":"Q: Excuse me, sir. Does this bus go to the zoo? — A: Yes, it does. Get off at the third stop.","t":"先生，不好意思，這班公車有到動物園嗎？ — 是的，有。在第三站下車。"}]},{"unit":6,"theme":"Family 家庭（第06區）","cards":[{"w":"father (dad, daddy)","p":"n.","d":"","c":"父親；爸爸","s":"Q: Who is that tall man? — A: He is my father. I call him Dad.","t":"那位高高的男士是誰？ — 他是我的父親，我叫他爸爸。"},{"w":"mother (mom, mommy)","p":"n.","d":"","c":"母親；媽媽","s":"Q: Who is she? — A: She is Tom's mother. Tom calls her Mom.","t":"她是誰？ — 她是湯姆的母親，湯姆叫她媽媽。"},{"w":"grandfather (grandpa)","p":"n.","d":"","c":"祖父；爺爺","s":"Q: Who is that old man? — A: He is Amy and Ben's grandfather. He is their dad's father.","t":"那位老先生是誰？ — 他是艾美和班的爺爺，他是他們爸爸的父親。"},{"w":"grandmother (grandma)","p":"n.","d":"","c":"祖母；奶奶","s":"Q: Who is she? Is she your teacher? — A: No, she isn't. She is my grandmother. She is my dad's mother.","t":"她是誰？她是你的老師嗎？ — 不，她不是。她是我的奶奶，她是我爸爸的母親。"},{"w":"uncle","p":"n.","d":"","c":"伯父；叔叔；舅舅","s":"Q: Who is he? — A: He is Lisa's uncle. He is her father's brother.","t":"他是誰？ — 他是麗莎的叔叔，他是她爸爸的弟弟。"},{"w":"aunt","p":"n.","d":"","c":"伯母；阿姨；姑姑","s":"Q: Who is she? — A: She is Tom and Mary's aunt. She is their mother's sister.","t":"她是誰？ — 她是湯姆和瑪麗的阿姨，她是他們媽媽的姊妹。"},{"w":"husband","p":"n.","d":"","c":"丈夫","s":"Q: Is Mr. Chen Ms. Lin's brother? — A: No, he isn't. He is Ms. Lin's husband.","t":"陳先生是林女士的哥哥嗎？ — 不，他不是。他是林女士的丈夫。"},{"w":"wife","p":"n.","d":"","c":"妻子","s":"Q: Is she your uncle's sister? — A: No, she isn't. She is my uncle's wife. She is my aunt.","t":"她是你叔叔的姊妹嗎？ — 不，她不是。她是我叔叔的妻子，她是我的嬸嬸。"},{"w":"married","p":"adj.","d":"","c":"已婚的","s":"Q: Is Ms. Wu your aunt? Is she Mr. Wu's wife? — A: Yes, she is. She is married to Mr. Wu.","t":"吳女士是你的阿姨嗎？她是吳先生的太太嗎？ — 是的，她是。她嫁給了吳先生（她是已婚的）。"},{"w":"son","p":"n.","d":"","c":"兒子","s":"Q: Is that boy Mr. and Mrs. Wang's child? — A: Yes, he is. He is their only son.","t":"那個男孩是王先生和王太太的小孩嗎？ — 是的，他是。他是他們唯一的兒子。"},{"w":"daughter","p":"n.","d":"","c":"女兒","s":"Q: Is that girl your child, Mrs. Lee? — A: No, she isn't. She is my sister's daughter.","t":"李太太，那個女孩是您的小孩嗎？ — 不，她不是。她是我姊姊的女兒。"},{"w":"cousin","p":"n.","d":"","c":"堂表兄弟姊妹","s":"Q: Is Ben your brother? — A: No, he isn't. He is my cousin. He is my uncle's son.","t":"班是你的兄弟嗎？ — 不，他不是。他是我的堂哥，他是我叔叔的兒子。"},{"w":"brother (brothers)","p":"n.","d":"","c":"兄弟","s":"Q: How many brothers do you have? — A: I have two brothers. They are older than me.","t":"你有幾個兄弟？ — 我有兩個哥哥，他們比我大。"},{"w":"sister","p":"n.","d":"","c":"姊妹","s":"Q: How many sisters does Amy have? — A: She has one sister. Her name is Lily.","t":"艾美有幾個姊妹？ — 她有一個姊妹，她的名字叫莉莉。"},{"w":"parent (parents)","p":"n.","d":"","c":"父（母）親；父母","s":"Q: How many children do your parents have? — A: My parents have three children: my two sisters and me.","t":"你的父母有幾個小孩？ — 我的父母有三個小孩：我的兩個姊姊和我。"},{"w":"relative (relatives)","p":"n.","d":"","c":"親戚","s":"Q: How many relatives does your mom have in Tainan? — A: She has many relatives there. We visit them at Chinese New Year.","t":"你媽媽在台南有幾個親戚？ — 她在那裡有很多親戚，我們過年時去拜訪他們。"},{"w":"born","p":"v.","d":"","c":"出生（be born）","s":"Q: How many children do Mr. and Mrs. Lin have? — A: They have two. Their baby was born last month.","t":"林先生和林太太有幾個小孩？ — 他們有兩個，他們的寶寶上個月出生。"},{"w":"family","p":"n.","d":"","c":"家庭；家人","s":"Q: What does your family do on Sundays? — A: My family goes hiking. We love the mountains.","t":"你的家人星期日做什麼？ — 我的家人去健行，我們很愛山。"},{"w":"live","p":"v.","d":"","c":"住","s":"Q: What do your grandparents do? — A: They are farmers. They live in the country.","t":"你的祖父母做什麼工作？ — 他們是農夫，他們住在鄉下。"},{"w":"grow (grows)","p":"v.","d":"","c":"成長；長大","s":"Q: What does your son do? — A: He is a student now. He wants to be a doctor when he grows up.","t":"你的兒子做什麼？ — 他現在是學生，他長大後想當醫生。"}]},{"unit":7,"theme":"Numbers 數字（第07區）","cards":[{"w":"one","p":"num.","d":"","c":"一","s":"Q: How many noses are there on your face? — A: There is only one nose.","t":"你臉上有幾個鼻子？ — 只有一個鼻子。"},{"w":"two","p":"num.","d":"","c":"二","s":"Q: How many eyes are there on your face? — A: There are two eyes.","t":"你臉上有幾隻眼睛？ — 有兩隻眼睛。"},{"w":"three","p":"num.","d":"","c":"三","s":"Q: How many people are there in your family? — A: There are three: my dad, my mom and me.","t":"你家有幾個人？ — 有三個：我爸爸、我媽媽和我。"},{"w":"four","p":"num.","d":"","c":"四","s":"Q: How many seasons are there in a year? — A: There are four seasons.","t":"一年有幾個季節？ — 有四個季節。"},{"w":"five","p":"num.","d":"","c":"五","s":"Q: How many fingers are there on one hand? — A: There are five fingers.","t":"一隻手上有幾根手指？ — 有五根手指。"},{"w":"seven","p":"num.","d":"","c":"七","s":"Q: How many days are there in a week? — A: There are seven days.","t":"一個星期有幾天？ — 有七天。"},{"w":"eight","p":"num.","d":"","c":"八","s":"Q: How many legs are there on a spider? — A: There are eight legs.","t":"一隻蜘蛛有幾隻腳？ — 有八隻腳。"},{"w":"ten","p":"num.","d":"","c":"十","s":"Q: How many fingers are there on your two hands? — A: There are ten fingers.","t":"你的兩隻手上有幾根手指？ — 有十根手指。"},{"w":"twelve","p":"num.","d":"","c":"十二","s":"Q: How many months are there in a year? — A: There are twelve months.","t":"一年有幾個月？ — 有十二個月。"},{"w":"twenty","p":"num.","d":"","c":"二十","s":"Q: How many students are there in your class? — A: There are twenty students: ten boys and ten girls.","t":"你們班上有幾個學生？ — 有二十個學生：十個男生和十個女生。"},{"w":"thirty","p":"num.","d":"","c":"三十","s":"Q: How many days are there in June? — A: There are thirty days.","t":"六月有幾天？ — 有三十天。"},{"w":"sixty","p":"num.","d":"","c":"六十","s":"Q: How many minutes are there in an hour? — A: There are sixty minutes.","t":"一小時有幾分鐘？ — 有六十分鐘。"},{"w":"hundred","p":"num.","d":"","c":"百","s":"Q: How many pages are there in your English book? — A: There are one hundred pages.","t":"你的英文書有幾頁？ — 有一百頁。"},{"w":"thousand","p":"num.","d":"","c":"千","s":"Q: How many students are there in your school? — A: There are two thousand students. It's a big school.","t":"你們學校有多少學生？ — 有兩千個學生，這是一所大學校。"},{"w":"million","p":"num.","d":"","c":"百萬","s":"Q: How many people are there in Taipei? — A: There are more than two million people.","t":"台北有多少人？ — 有超過兩百萬人。"},{"w":"six","p":"num.","d":"","c":"六","s":"Q: How old is your little brother? — A: He is six years old. He goes to elementary school.","t":"你弟弟幾歲？ — 他六歲，他上小學。"},{"w":"nine","p":"num.","d":"","c":"九","s":"Q: How old is Amy's cat? — A: It is nine years old. It's an old cat.","t":"艾美的貓幾歲？ — 牠九歲了，牠是一隻老貓。"},{"w":"eleven","p":"num.","d":"","c":"十一","s":"Q: How old are Ben and Lily? — A: They are eleven years old. They are in the same class.","t":"班和莉莉幾歲？ — 他們十一歲，他們同班。"},{"w":"thirteen","p":"num.","d":"","c":"十三","s":"Q: How old are you? — A: I am thirteen years old. I'm in junior high school.","t":"你幾歲？ — 我十三歲，我讀國中。"},{"w":"fourteen","p":"num.","d":"","c":"十四","s":"Q: How old is your cousin? — A: She is fourteen. She is one year older than me.","t":"你表姊幾歲？ — 她十四歲，她比我大一歲。"},{"w":"fifteen","p":"num.","d":"","c":"十五","s":"Q: How old is Tom? — A: He is fifteen years old. He is a teenager.","t":"湯姆幾歲？ — 他十五歲，他是青少年。"},{"w":"sixteen","p":"num.","d":"","c":"十六","s":"Q: How old is your sister? — A: She is sixteen. She goes to senior high school.","t":"你姊姊幾歲？ — 她十六歲，她讀高中。"},{"w":"eighteen","p":"num.","d":"","c":"十八","s":"Q: How old is your brother? — A: He is eighteen years old. He can drive a car now.","t":"你哥哥幾歲？ — 他十八歲，他現在可以開車了。"},{"w":"nineteen","p":"num.","d":"","c":"十九","s":"Q: How old is Mary? — A: She is nineteen. She will be twenty next year.","t":"瑪麗幾歲？ — 她十九歲，她明年就二十歲了。"},{"w":"forty","p":"num.","d":"","c":"四十","s":"Q: How old is your father? — A: He is forty years old. He looks young.","t":"你爸爸幾歲？ — 他四十歲，他看起來很年輕。"},{"w":"seventy","p":"num.","d":"","c":"七十","s":"Q: How old is your grandfather? — A: He is seventy years old, but he is still strong.","t":"你爺爺幾歲？ — 他七十歲，但他還是很強壯。"},{"w":"eighty","p":"num.","d":"","c":"八十","s":"Q: How old is your grandmother? — A: She is eighty years old. She walks slowly.","t":"你奶奶幾歲？ — 她八十歲，她走路很慢。"},{"w":"ninety","p":"num.","d":"","c":"九十","s":"Q: How old is that old man? — A: He is ninety years old. He lives next to us.","t":"那位老先生幾歲？ — 他九十歲，他住在我們隔壁。"},{"w":"zero","p":"num.","d":"","c":"零","s":"Q: What's five minus five? — A: It's zero.","t":"五減五是多少？ — 是零。"},{"w":"seventeen","p":"num.","d":"","c":"十七","s":"Q: What's ten plus seven? — A: It's seventeen.","t":"十加七是多少？ — 是十七。"},{"w":"fifty","p":"num.","d":"","c":"五十","s":"Q: What's twenty plus thirty? — A: It's fifty.","t":"二十加三十是多少？ — 是五十。"},{"w":"number","p":"n.","d":"","c":"數字；號碼","s":"Q: What's nine plus four? — A: It's thirteen. It's my lucky number!","t":"九加四是多少？ — 是十三，那是我的幸運數字！"},{"w":"total","p":"n.","d":"","c":"總數；總計","s":"Q: What's two hundred plus three hundred? — A: It's five hundred. The total is five hundred dollars.","t":"兩百加三百是多少？ — 是五百，總共是五百元。"},{"w":"first","p":"num.","d":"","c":"第一（的）","s":"Q: Which floor does your grandma live on? — A: She lives on the first floor. She can't walk up the stairs.","t":"你奶奶住幾樓？ — 她住一樓，她不能爬樓梯。"},{"w":"second","p":"num.","d":"","c":"第二（的）","s":"Q: Which floor do you live on? — A: I live on the second floor.","t":"你住幾樓？ — 我住二樓。"},{"w":"third","p":"num.","d":"","c":"第三（的）","s":"Q: Which floor do Ben and his parents live on? — A: They live on the third floor.","t":"班和他的父母住幾樓？ — 他們住三樓。"},{"w":"fourth","p":"num.","d":"","c":"第四（的）","s":"Q: Which floor does Tom live on? — A: He lives on the fourth floor, above us.","t":"湯姆住幾樓？ — 他住四樓，在我們樓上。"},{"w":"fifth","p":"num.","d":"","c":"第五（的）","s":"Q: Which floor do your cousins live on? — A: They live on the fifth floor.","t":"你的表兄弟姊妹住幾樓？ — 他們住五樓。"},{"w":"eighth","p":"num.","d":"","c":"第八（的）","s":"Q: Which floor does your uncle work on? — A: He works on the eighth floor of that building.","t":"你叔叔在幾樓上班？ — 他在那棟大樓的八樓上班。"},{"w":"ninth","p":"num.","d":"","c":"第九（的）","s":"Q: Which floor do you and your family live on? — A: We live on the ninth floor. We can see the park.","t":"你和你的家人住幾樓？ — 我們住九樓，我們可以看到公園。"},{"w":"eleventh","p":"num.","d":"","c":"第十一（的）","s":"Q: When does Amy have her birthday party? — A: She has it on the eleventh of May.","t":"艾美什麼時候辦生日派對？ — 她在五月十一日辦。"},{"w":"fourteenth","p":"num.","d":"","c":"第十四（的）","s":"Q: What's the date today? — A: It's the fourteenth of February.","t":"今天幾月幾日？ — 今天是二月十四日。"},{"w":"fifteenth","p":"num.","d":"","c":"第十五（的）","s":"Q: When do the students have the English test? — A: They have it on the fifteenth of June.","t":"學生們什麼時候考英文？ — 他們六月十五日考。"},{"w":"nineteenth","p":"num.","d":"","c":"第十九（的）","s":"Q: When does your brother come home from America? — A: He comes home on the nineteenth of July.","t":"你哥哥什麼時候從美國回家？ — 他七月十九日回家。"},{"w":"last","p":"adj.","d":"","c":"最後的","s":"Q: When do we have the school party? — A: We have it on the last day of this month.","t":"我們什麼時候辦學校派對？ — 我們在這個月的最後一天辦。"},{"w":"many","p":"adj.","d":"","c":"許多的（可數）","s":"Q: How many friends does Amy have? — A: She has many friends. She is very friendly.","t":"艾美有幾個朋友？ — 她有很多朋友，她很友善。"},{"w":"a lot (of)","p":"phr.","d":"","c":"許多的","s":"Q: How many books do your parents have? — A: They have a lot of books. They love reading.","t":"你的父母有多少書？ — 他們有很多書，他們很愛閱讀。"},{"w":"much","p":"adj.","d":"","c":"許多的（不可數）","s":"Q: How much time do you have today? — A: I don't have much time. I have a test tomorrow.","t":"你今天有多少時間？ — 我沒有很多時間，我明天有考試。"},{"w":"several","p":"adj.","d":"","c":"幾個的","s":"Q: How many friends do you have in Tainan? — A: I have several friends there.","t":"你在台南有幾個朋友？ — 我在那裡有幾個朋友。"},{"w":"some","p":"adj.","d":"","c":"一些","s":"Q: How much water do you want? — A: I want some water. I'm thirsty.","t":"你想要多少水？ — 我想要一些水，我口渴了。"},{"w":"a few","p":"phr.","d":"","c":"一些；幾個（可數）","s":"Q: How many apples do we have? — A: We only have a few apples. Let's buy some more.","t":"我們有幾顆蘋果？ — 我們只有幾顆蘋果，我們再買一些吧。"},{"w":"a little","p":"phr.","d":"","c":"一點點（不可數）","s":"Q: How much milk does Ben want? — A: He wants a little milk, not a lot.","t":"班想要多少牛奶？ — 他想要一點點牛奶，不要很多。"},{"w":"few","p":"adj.","d":"","c":"很少的（可數）","s":"Q: How many friends does the new student have? — A: He has very few friends. He feels lonely.","t":"那個新同學有幾個朋友？ — 他的朋友很少，他覺得很寂寞。"},{"w":"little","p":"adj.","d":"","c":"很少的（不可數）","s":"Q: How much money does your brother have? — A: He has very little money. He can't buy the toy.","t":"你弟弟有多少錢？ — 他的錢很少，他買不起那個玩具。"},{"w":"any","p":"adj.","d":"","c":"任何的","s":"Q: How many brothers does Tim have? — A: He doesn't have any brothers. He has two sisters.","t":"提姆有幾個兄弟？ — 他沒有任何兄弟，他有兩個姊妹。"},{"w":"all","p":"pron.","d":"","c":"全部；都","s":"Q: Do your classmates like the new teacher? — A: Yes, they do. All of them like her.","t":"你的同學喜歡新老師嗎？ — 是的，他們喜歡。他們全部都喜歡她。"},{"w":"both","p":"pron.","d":"","c":"兩者都","s":"Q: Does Ken have any brothers? — A: Yes, he does. He has two, and both of them play basketball.","t":"肯有兄弟嗎？ — 是的，他有。他有兩個，他們兩個都打籃球。"},{"w":"more","p":"adj.","d":"","c":"更多的","s":"Q: How much rice does your dad want? — A: He wants more rice. He is still hungry.","t":"你爸爸想要多少飯？ — 他想要更多飯，他還很餓。"},{"w":"less","p":"adj.","d":"","c":"較少的","s":"Q: How much sugar do your grandparents eat now? — A: They eat less sugar now. It's good for their health.","t":"你的祖父母現在吃多少糖？ — 他們現在吃比較少的糖，這對他們的健康有好處。"}]},{"unit":8,"theme":"Time 時間（第08區）","cards":[{"w":"time","p":"n.","d":"","c":"時間","s":"Q: What time is it? — A: It's seven thirty. It's time to go to school.","t":"現在幾點？ — 七點半，該去上學了。"},{"w":"clock","p":"n.","d":"","c":"時鐘","s":"Q: What time is it? — A: Look at the clock on the wall. It's five o'clock.","t":"現在幾點？ — 看牆上的時鐘，現在五點。"},{"w":"watch","p":"n.","d":"","c":"手錶","s":"Q: What time is it, Ben? — A: Let me look at my watch. It's four o'clock.","t":"班，現在幾點？ — 我看一下我的手錶，現在四點。"},{"w":"o'clock","p":"adv.","d":"","c":"……點鐘","s":"Q: What time is it now? — A: It's three o'clock. Let's go home.","t":"現在幾點？ — 三點整，我們回家吧。"},{"w":"half","p":"n.","d":"","c":"一半；半小時","s":"Q: What time is it now? — A: It's half past six. Dinner is ready.","t":"現在幾點？ — 六點半，晚餐準備好了。"},{"w":"quarter","p":"n.","d":"","c":"十五分鐘；四分之一","s":"Q: What time is it? — A: It's a quarter past two. (2:15)","t":"現在幾點？ — 兩點十五分。"},{"w":"past","p":"prep.","d":"","c":"（時間）超過；過了","s":"Q: What time is it? — A: It's ten past eight. (8:10) We are late!","t":"現在幾點？ — 八點十分，我們遲到了！"},{"w":"a.m.","p":"abbr.","d":"","c":"上午（用在時間後）","s":"Q: What time is it in Taipei now? — A: It's 7 a.m. People are going to work.","t":"台北現在幾點？ — 上午七點，人們正要去上班。"},{"w":"p.m.","p":"abbr.","d":"","c":"下午（用在時間後）","s":"Q: What time is it? — A: It's 4 p.m. School is over.","t":"現在幾點？ — 下午四點，放學了。"},{"w":"noon","p":"n.","d":"","c":"中午","s":"Q: What time is it? — A: It's twelve. It's noon. Let's have lunch.","t":"現在幾點？ — 十二點，中午了，我們吃午餐吧。"},{"w":"already","p":"adv.","d":"","c":"已經","s":"Q: What time is it? — A: It's already ten o'clock! Go to bed now.","t":"現在幾點？ — 已經十點了！現在去睡覺。"},{"w":"hour","p":"n.","d":"","c":"小時","s":"Q: What time is it? — A: It's eleven. We have one hour before lunch.","t":"現在幾點？ — 十一點，午餐前我們還有一個小時。"},{"w":"minute (minutes)","p":"n.","d":"","c":"分鐘","s":"Q: What time is it? — A: It's 7:55. The bus comes in five minutes.","t":"現在幾點？ — 七點五十五分，公車五分鐘後來。"},{"w":"second (seconds)","p":"n.","d":"","c":"秒","s":"Q: What time is it? — A: It's 11:59:50. Only ten seconds to the new year!","t":"現在幾點？ — 十一點五十九分五十秒，再十秒就新年了！"},{"w":"moment","p":"n.","d":"","c":"片刻；一會兒","s":"Q: What time is it, Mom? — A: Wait a moment. I can't find my phone.","t":"媽，現在幾點？ — 等一下，我找不到我的手機。"},{"w":"Monday","p":"n.","d":"","c":"星期一","s":"Q: What day is it today? — A: It's Monday. A new week starts today.","t":"今天星期幾？ — 今天星期一，新的一週從今天開始。"},{"w":"Wednesday","p":"n.","d":"","c":"星期三","s":"Q: What day is it today? — A: It's Wednesday. It's the middle of the week.","t":"今天星期幾？ — 今天星期三，是一週的中間。"},{"w":"today","p":"n.","d":"","c":"今天","s":"Q: What day is it today? — A: Today is Friday. We have a test.","t":"今天星期幾？ — 今天星期五，我們有考試。"},{"w":"tomorrow","p":"n.","d":"","c":"明天","s":"Q: What day is it today? — A: It's Friday. Tomorrow is Saturday. No school!","t":"今天星期幾？ — 今天星期五，明天星期六，不用上學！"},{"w":"yesterday","p":"n.","d":"","c":"昨天","s":"Q: What day is it today? — A: It's Monday. Yesterday was Sunday.","t":"今天星期幾？ — 今天星期一，昨天是星期日。"},{"w":"day","p":"n.","d":"","c":"日子；天","s":"Q: What day is it today? — A: It's Sunday. It's my favorite day of the week.","t":"今天星期幾？ — 今天星期日，這是我一週中最喜歡的一天。"},{"w":"week","p":"n.","d":"","c":"星期；週","s":"Q: What day is it today? — A: It's Sunday. It's the first day of the week.","t":"今天星期幾？ — 今天星期日，是一週的第一天。"},{"w":"January","p":"n.","d":"","c":"一月","s":"Q: When is New Year's Day? — A: It's on January 1st.","t":"元旦是什麼時候？ — 在一月一日。"},{"w":"February","p":"n.","d":"","c":"二月","s":"Q: When is Valentine's Day? — A: It's on February 14th.","t":"情人節是什麼時候？ — 在二月十四日。"},{"w":"March","p":"n.","d":"","c":"三月","s":"Q: When is your sister's sixteenth birthday? — A: It's in March. She wants a big cake.","t":"你姊姊的十六歲生日是什麼時候？ — 在三月，她想要一個大蛋糕。"},{"w":"April","p":"n.","d":"","c":"四月","s":"Q: When is Children's Day in Taiwan? — A: It's on April 4th.","t":"台灣的兒童節是什麼時候？ — 在四月四日。"},{"w":"May","p":"n.","d":"","c":"五月","s":"Q: When is Mother's Day? — A: It's on the second Sunday in May.","t":"母親節是什麼時候？ — 在五月的第二個星期日。"},{"w":"June","p":"n.","d":"","c":"六月","s":"Q: When is the Dragon Boat Festival this year? — A: It's in June. We eat rice dumplings.","t":"今年端午節是什麼時候？ — 在六月，我們吃粽子。"},{"w":"July","p":"n.","d":"","c":"七月","s":"Q: When is your thirteenth birthday? — A: It's in July, in the summer vacation.","t":"你的十三歲生日是什麼時候？ — 在七月，在暑假期間。"},{"w":"August","p":"n.","d":"","c":"八月","s":"Q: When is Father's Day in Taiwan? — A: It's on August 8th.","t":"台灣的父親節是什麼時候？ — 在八月八日。"},{"w":"September","p":"n.","d":"","c":"九月","s":"Q: When is Teacher's Day? — A: It's on September 28th.","t":"教師節是什麼時候？ — 在九月二十八日。"},{"w":"October","p":"n.","d":"","c":"十月","s":"Q: When is Halloween? — A: It's on October 31st.","t":"萬聖節是什麼時候？ — 在十月三十一日。"},{"w":"November","p":"n.","d":"","c":"十一月","s":"Q: When is Thanksgiving in America? — A: It's in November. People eat a big dinner.","t":"美國的感恩節是什麼時候？ — 在十一月，人們吃一頓大餐。"},{"w":"December","p":"n.","d":"","c":"十二月","s":"Q: When is Christmas? — A: It's on December 25th.","t":"聖誕節是什麼時候？ — 在十二月二十五日。"},{"w":"season","p":"n.","d":"","c":"季節","s":"Q: When is your birthday? — A: It's in summer. Summer is my favorite season.","t":"你的生日是什麼時候？ — 在夏天，夏天是我最喜歡的季節。"},{"w":"spring","p":"n.","d":"","c":"春天","s":"Q: When is Sports Day? — A: It's in spring, in April. The flowers are beautiful.","t":"運動會是什麼時候？ — 在春天，在四月。花很漂亮。"},{"w":"summer","p":"n.","d":"","c":"夏天","s":"Q: When is your brother's eighteenth birthday? — A: It's in summer, in August. It's very hot.","t":"你哥哥的十八歲生日是什麼時候？ — 在夏天，在八月。天氣很熱。"},{"w":"autumn (fall)","p":"n.","d":"","c":"秋天","s":"Q: When is the Moon Festival? — A: It's in autumn, in September or October.","t":"中秋節是什麼時候？ — 在秋天，在九月或十月。"},{"w":"winter","p":"n.","d":"","c":"冬天","s":"Q: When is Chinese New Year? — A: It's in winter, in January or February.","t":"農曆新年是什麼時候？ — 在冬天，在一月或二月。"},{"w":"Saturday","p":"n.","d":"","c":"星期六","s":"Q: What does Tom do on weekends? — A: He plays basketball on Saturday mornings.","t":"湯姆週末做什麼？ — 他星期六早上打籃球。"},{"w":"Sunday","p":"n.","d":"","c":"星期日","s":"Q: What do you and your family do on weekends? — A: We go to church on Sunday.","t":"你和你的家人週末做什麼？ — 我們星期日去教會。"},{"w":"weekend","p":"n.","d":"","c":"週末","s":"Q: What does your dad do on Saturdays? — A: He doesn't work on the weekend. He sleeps late.","t":"你爸爸星期六做什麼？ — 他週末不用工作，他睡得很晚。"},{"w":"morning","p":"n.","d":"","c":"早上","s":"Q: What does Amy do on Sundays? — A: She goes jogging in the park in the morning.","t":"艾美星期日做什麼？ — 她早上去公園慢跑。"},{"w":"afternoon","p":"n.","d":"","c":"下午","s":"Q: What do your classmates do on Fridays? — A: They play soccer in the afternoon after class.","t":"你的同學星期五做什麼？ — 他們下午下課後踢足球。"},{"w":"evening","p":"n.","d":"","c":"傍晚；晚上","s":"Q: What does your mom do on Mondays? — A: She takes a cooking class in the evening, after dinner.","t":"你媽媽星期一做什麼？ — 她傍晚吃完晚餐後去上烹飪課。"},{"w":"night","p":"n.","d":"","c":"夜晚；晚上","s":"Q: What do you do on Saturdays? — A: I watch movies with my family at night.","t":"你星期六做什麼？ — 我晚上和家人一起看電影。"},{"w":"Tuesday","p":"n.","d":"","c":"星期二","s":"Q: When does Lisa have art class? — A: She has art class on Tuesday.","t":"麗莎什麼時候上美術課？ — 她星期二上美術課。"},{"w":"Thursday","p":"n.","d":"","c":"星期四","s":"Q: When do you have music class? — A: I have music class on Thursday.","t":"你什麼時候上音樂課？ — 我星期四上音樂課。"},{"w":"Friday","p":"n.","d":"","c":"星期五","s":"Q: When do Ben and Tom have PE class? — A: They have PE class on Friday afternoon.","t":"班和湯姆什麼時候上體育課？ — 他們星期五下午上體育課。"},{"w":"now","p":"adv.","d":"","c":"現在","s":"Q: When do we have math class? — A: We have it now! Hurry up!","t":"我們什麼時候上數學課？ — 現在就是！快點！"},{"w":"soon","p":"adv.","d":"","c":"很快；不久","s":"Q: When does Tim have science class? — A: He has it soon, in five minutes.","t":"提姆什麼時候上自然課？ — 很快，再五分鐘就上了。"},{"w":"later","p":"adv.","d":"","c":"稍後；等一下","s":"Q: When does Amy have social studies class? — A: She has it later today, after lunch.","t":"艾美什麼時候上社會課？ — 她今天稍後上，在午餐後。"},{"w":"early","p":"adv.","d":"","c":"早；早的","s":"Q: When do the students have Chinese class? — A: They have it early in the morning, at eight.","t":"學生們什麼時候上國文課？ — 他們早上很早就上，在八點。"},{"w":"late","p":"adv.","d":"","c":"晚；晚的","s":"Q: When does your brother have English class? — A: He has it late in the afternoon, at four o'clock.","t":"你弟弟什麼時候上英文課？ — 他下午很晚才上，在四點。"},{"w":"year","p":"n.","d":"","c":"年","s":"Q: When does your family go to Japan? — A: We go there every year, in July.","t":"你家什麼時候去日本？ — 我們每年七月去那裡。"},{"w":"month","p":"n.","d":"","c":"月；月份","s":"Q: When does your aunt visit you? — A: She visits us on the first day of every month.","t":"你阿姨什麼時候來看你們？ — 她每個月的第一天來看我們。"},{"w":"once","p":"adv.","d":"","c":"一次","s":"Q: How often does Grandma call you? — A: She calls me once a week, on Sunday night.","t":"奶奶多久打電話給你一次？ — 她一週打一次，在星期日晚上。"},{"w":"tonight","p":"adv.","d":"","c":"今晚","s":"Q: When do we have the party? — A: We have it tonight, at seven o'clock.","t":"我們什麼時候開派對？ — 今晚，七點。"},{"w":"next","p":"adj.","d":"","c":"下一個的","s":"Q: When is the English test? — A: It's next Friday. Let's study together.","t":"英文考試是什麼時候？ — 下星期五，我們一起讀書吧。"},{"w":"last","p":"adj.","d":"","c":"上一個的；最近的","s":"Q: When was Ben's birthday party? — A: It was last Sunday. It was fun.","t":"班的生日派對是什麼時候？ — 上星期日，很好玩。"},{"w":"ago","p":"adv.","d":"","c":"……以前","s":"Q: When was Tom in Japan? — A: He was there two years ago.","t":"湯姆什麼時候在日本？ — 他兩年前在那裡。"},{"w":"future","p":"n.","d":"","c":"未來","s":"Q: When can people live on the moon? — A: Maybe in the future.","t":"人們什麼時候可以住在月球上？ — 也許在未來。"}]},{"unit":9,"theme":"Money 金錢（第09區）","cards":[{"w":"dollar (dollars)","p":"n.","d":"","c":"元","s":"Q: How much is this pen? — A: It's twenty dollars.","t":"這支筆多少錢？ — 它二十元。"},{"w":"cent (cents)","p":"n.","d":"","c":"（一）分錢","s":"Q: How much is this candy? — A: It's only fifty cents.","t":"這顆糖果多少錢？ — 它只要五十分錢。"},{"w":"price","p":"n.","d":"","c":"價格","s":"Q: How much is the new bike? — A: The price is three thousand dollars.","t":"這輛新腳踏車多少錢？ — 價格是三千元。"},{"w":"change","p":"n.","d":"","c":"零錢；找的錢","s":"Q: How much is it? — A: It's eighty dollars. Here is your change, twenty dollars.","t":"這個多少錢？ — 八十元。這是找你的零錢，二十元。"},{"w":"cheap","p":"adj.","d":"","c":"便宜的","s":"Q: How much are these socks? — A: They're fifty dollars. They're very cheap.","t":"這些襪子多少錢？ — 它們五十元，很便宜。"},{"w":"expensive","p":"adj.","d":"","c":"昂貴的","s":"Q: How much are those shoes? — A: They're five thousand dollars. They're too expensive!","t":"那雙鞋子多少錢？ — 它們五千元，太貴了！"},{"w":"buy","p":"v.","d":"","c":"買","s":"Q: How much are the apples? — A: They're ten dollars each. I want to buy six.","t":"這些蘋果多少錢？ — 一個十元，我想買六個。"},{"w":"spend","p":"v.","d":"","c":"（人）花（錢）","s":"Q: How much do you spend on lunch every day? — A: I spend sixty dollars on lunch.","t":"你每天午餐花多少錢？ — 我午餐花六十元。"},{"w":"money","p":"n.","d":"","c":"錢","s":"Q: How much do your parents spend on books? — A: They spend a lot of money on books. They love reading.","t":"你爸媽花多少錢買書？ — 他們花很多錢在書上，他們很愛閱讀。"},{"w":"cost (costs)","p":"v.","d":"","c":"（物品）價錢為","s":"Q: How much does this T-shirt cost? — A: It costs three hundred dollars.","t":"這件T恤要多少錢？ — 它要三百元。"},{"w":"pay (pays)","p":"v.","d":"","c":"付錢","s":"Q: Does your dad pay for dinner? — A: Yes, he does. He always pays for dinner.","t":"你爸爸付晚餐的錢嗎？ — 是的，他會。他總是付晚餐的錢。"},{"w":"borrow","p":"v.","d":"","c":"借入","s":"Q: Do you have money for the bus? — A: No, I don't. Can I borrow twenty dollars from you?","t":"你有搭公車的錢嗎？ — 不，我沒有。我可以跟你借二十元嗎？"},{"w":"lend (lends)","p":"v.","d":"","c":"借出","s":"Q: Does your sister lend you money? — A: Yes, she does. She often lends me fifty dollars.","t":"你姊姊會借你錢嗎？ — 是的，她會。她常常借我五十元。"}]},{"unit":10,"theme":"Food & Drinks 食物與飲料（第10區）","cards":[{"w":"hungry","p":"adj.","d":"","c":"飢餓的","s":"Q: What would you like to eat? — A: I'm very hungry. I'd like a big bowl of noodles.","t":"你想吃什麼？ — 我好餓，我想要一大碗麵。"},{"w":"thirsty","p":"adj.","d":"","c":"口渴的","s":"Q: What would you like to drink? — A: I'm thirsty. I'd like a glass of water.","t":"你想喝什麼？ — 我口渴了，我想要一杯水。"},{"w":"full","p":"adj.","d":"","c":"飽的；滿的","s":"Q: Would you like some more cake? — A: No, thank you. I'm full.","t":"你想再吃一些蛋糕嗎？ — 不用了，謝謝，我吃飽了。"},{"w":"menu","p":"n.","d":"","c":"菜單","s":"Q: What would you like to eat, sir? — A: Can I see the menu, please?","t":"先生，您想吃什麼？ — 可以請你給我看一下菜單嗎？"},{"w":"order","p":"v.","d":"","c":"點餐","s":"Q: Are you ready? What would you like? — A: I'd like to order a pizza, please.","t":"您準備好了嗎？您想要什麼？ — 我想要點一個披薩，謝謝。"},{"w":"food","p":"n.","d":"","c":"食物","s":"Q: What would you like to eat tonight? — A: I'd like some Japanese food.","t":"你今晚想吃什麼？ — 我想吃一些日本料理（食物）。"},{"w":"hamburger (burger)","p":"n.","d":"","c":"漢堡","s":"Q: What would you like for lunch? — A: I'd like a hamburger, please.","t":"你午餐想吃什麼？ — 我想要一個漢堡，謝謝。"},{"w":"fries (French fries)","p":"n.","d":"","c":"炸薯條","s":"Q: What would you like with your hamburger? — A: I'd like some French fries.","t":"你的漢堡想配什麼？ — 我想要一些薯條。"},{"w":"hot dog","p":"n.","d":"","c":"熱狗","s":"Q: What would Ben like to eat? — A: He'd like a hot dog.","t":"班想吃什麼？ — 他想要一個熱狗。"},{"w":"pizza","p":"n.","d":"","c":"披薩","s":"Q: What would you like for dinner? — A: I'd like a big pizza with cheese.","t":"你晚餐想吃什麼？ — 我想要一個有起司的大披薩。"},{"w":"ice cream","p":"n.","d":"","c":"冰淇淋","s":"Q: What would you like after dinner? — A: I'd like some chocolate ice cream.","t":"晚餐後你想吃什麼？ — 我想要一些巧克力冰淇淋。"},{"w":"Coke","p":"n.","d":"","c":"可樂","s":"Q: What would you like to drink? — A: I'd like a Coke, please.","t":"你想喝什麼？ — 我想要一杯可樂，謝謝。"},{"w":"ice","p":"n.","d":"","c":"冰","s":"Q: Would you like some water? — A: Yes, please. I'd like it with ice.","t":"你想要一些水嗎？ — 好的，麻煩了。我想要加冰的。"},{"w":"juice","p":"n.","d":"","c":"果汁","s":"Q: What would your sister like to drink? — A: She'd like a glass of apple juice.","t":"你妹妹想喝什麼？ — 她想要一杯蘋果汁。"},{"w":"tea","p":"n.","d":"","c":"茶","s":"Q: What would Grandma like to drink? — A: She'd like a cup of green tea.","t":"奶奶想喝什麼？ — 她想要一杯綠茶。"},{"w":"coffee","p":"n.","d":"","c":"咖啡","s":"Q: What would your dad like to drink? — A: He'd like a cup of hot coffee.","t":"你爸爸想喝什麼？ — 他想要一杯熱咖啡。"},{"w":"fruit","p":"n.","d":"","c":"水果","s":"Q: Do you like apples and bananas? — A: Yes, I do. I like all kinds of fruit.","t":"你喜歡蘋果和香蕉嗎？ — 是的，我喜歡。我喜歡各種水果。"},{"w":"apple","p":"n.","d":"","c":"蘋果","s":"Q: Does Tom like fruit? — A: Yes, he does. He eats an apple every day.","t":"湯姆喜歡水果嗎？ — 是的，他喜歡。他每天吃一顆蘋果。"},{"w":"orange","p":"n.","d":"","c":"柳橙","s":"Q: Do the kids like fruit juice? — A: Yes, they do. They like orange juice.","t":"孩子們喜歡果汁嗎？ — 是的，他們喜歡。他們喜歡柳橙汁。"},{"w":"banana (bananas)","p":"n.","d":"","c":"香蕉","s":"Q: Do monkeys like fruit? — A: Yes, they do. They love yellow bananas.","t":"猴子喜歡水果嗎？ — 是的，牠們喜歡。牠們很愛黃色的香蕉。"},{"w":"grape (grapes)","p":"n.","d":"","c":"葡萄","s":"Q: Does your sister like purple fruit? — A: Yes, she does. She likes grapes very much.","t":"你妹妹喜歡紫色的水果嗎？ — 是的，她喜歡。她非常喜歡葡萄。"},{"w":"guava (guavas)","p":"n.","d":"","c":"芭樂","s":"Q: Does Grandpa like Taiwanese fruit? — A: Yes, he does. He likes green guavas.","t":"爺爺喜歡台灣的水果嗎？ — 是的，他喜歡。他喜歡綠色的芭樂。"},{"w":"papaya","p":"n.","d":"","c":"木瓜","s":"Q: Do your parents like fruit milk? — A: Yes, they do. They like papaya milk.","t":"你爸媽喜歡水果牛奶嗎？ — 是的，他們喜歡。他們喜歡木瓜牛奶。"},{"w":"peach (peaches)","p":"n.","d":"","c":"桃子","s":"Q: Does Amy like soft and sweet fruit? — A: Yes, she does. She likes pink peaches.","t":"艾美喜歡軟軟甜甜的水果嗎？ — 是的，她喜歡。她喜歡粉紅色的桃子。"},{"w":"pear (pears)","p":"n.","d":"","c":"梨子","s":"Q: Does your mom like apples? — A: No, she doesn't. She likes pears.","t":"你媽媽喜歡蘋果嗎？ — 不，她不喜歡。她喜歡梨子。"},{"w":"lemon","p":"n.","d":"","c":"檸檬","s":"Q: Does your dad like sweet tea? — A: No, he doesn't. He likes lemon tea.","t":"你爸爸喜歡甜的茶嗎？ — 不，他不喜歡。他喜歡檸檬茶。"},{"w":"strawberry (strawberries)","p":"n.","d":"","c":"草莓","s":"Q: Do you like red fruit? — A: Yes, I do. I like strawberries.","t":"你喜歡紅色的水果嗎？ — 是的，我喜歡。我喜歡草莓。"},{"w":"watermelon","p":"n.","d":"","c":"西瓜","s":"Q: Does your brother like summer fruit? — A: Yes, he does. He likes watermelon. It's big and sweet.","t":"你哥哥喜歡夏天的水果嗎？ — 是的，他喜歡。他喜歡西瓜，它又大又甜。"},{"w":"tomato (tomatoes)","p":"n.","d":"","c":"番茄","s":"Q: Do you like red vegetables? — A: Yes, I do. I like tomatoes.","t":"你喜歡紅色的蔬菜嗎？ — 是的，我喜歡。我喜歡番茄。"},{"w":"vegetable (vegetables)","p":"n.","d":"","c":"蔬菜","s":"Q: Does your little brother like green food? — A: No, he doesn't. He doesn't like vegetables.","t":"你弟弟喜歡綠色的食物嗎？ — 不，他不喜歡。他不喜歡蔬菜。"},{"w":"lettuce","p":"n.","d":"","c":"萵苣；生菜","s":"Q: Do rabbits like vegetables? — A: Yes, they do. They like lettuce.","t":"兔子喜歡蔬菜嗎？ — 是的，牠們喜歡。牠們喜歡生菜。"},{"w":"bean","p":"n.","d":"","c":"豆子","s":"Q: Does your grandma like sweet soup? — A: Yes, she does. She likes red bean soup.","t":"你奶奶喜歡甜湯嗎？ — 是的，她喜歡。她喜歡紅豆湯。"},{"w":"pumpkin","p":"n.","d":"","c":"南瓜","s":"Q: Do you like Halloween food? — A: Yes, I do. I like pumpkin pie.","t":"你喜歡萬聖節的食物嗎？ — 是的，我喜歡。我喜歡南瓜派。"},{"w":"meat","p":"n.","d":"","c":"肉","s":"Q: Does your sister like beef and pork? — A: No, she doesn't. She doesn't like meat.","t":"你姊姊喜歡牛肉和豬肉嗎？ — 不，她不喜歡。她不喜歡肉。"},{"w":"beef","p":"n.","d":"","c":"牛肉","s":"Q: Do you like noodles? — A: Yes, I do. I like beef noodles.","t":"你喜歡麵嗎？ — 是的，我喜歡。我喜歡牛肉麵。"},{"w":"pork","p":"n.","d":"","c":"豬肉","s":"Q: Does Grandpa like meat? — A: Yes, he does. He likes pork with rice.","t":"爺爺喜歡肉嗎？ — 是的，他喜歡。他喜歡豬肉配飯。"},{"w":"chicken","p":"n.","d":"","c":"雞肉","s":"Q: Do your kids like fried food? — A: Yes, they do. They like fried chicken.","t":"你的孩子們喜歡炸的食物嗎？ — 是的，他們喜歡。他們喜歡炸雞。"},{"w":"fish","p":"n.","d":"","c":"魚；魚肉","s":"Q: Does your cat like meat? — A: Yes, it does. But it likes fish best.","t":"你的貓喜歡肉嗎？ — 是的，牠喜歡。但牠最喜歡魚。"},{"w":"ham","p":"n.","d":"","c":"火腿","s":"Q: Do you like pizza? — A: Yes, I do. I like ham and cheese pizza.","t":"你喜歡披薩嗎？ — 是的，我喜歡。我喜歡火腿起司披薩。"},{"w":"cheese","p":"n.","d":"","c":"起司；乳酪","s":"Q: Does the little mouse like milk? — A: No, it doesn't. It likes cheese.","t":"那隻小老鼠喜歡牛奶嗎？ — 不，牠不喜歡。牠喜歡起司。"},{"w":"chocolate","p":"n.","d":"","c":"巧克力","s":"Q: Do your sisters like sweet food? — A: Yes, they do. They like chocolate very much.","t":"你的姊妹們喜歡甜食嗎？ — 是的，她們喜歡。她們非常喜歡巧克力。"},{"w":"candy","p":"n.","d":"","c":"糖果","s":"Q: Does Ben like sweet food? — A: Yes, he does. He likes candy, but it's bad for his teeth.","t":"班喜歡甜食嗎？ — 是的，他喜歡。他喜歡糖果，但糖果對他的牙齒不好。"},{"w":"popcorn","p":"n.","d":"","c":"爆米花","s":"Q: Do you like movies? — A: Yes, I do. I like eating popcorn at the movies.","t":"你喜歡電影嗎？ — 是的，我喜歡。我喜歡在看電影時吃爆米花。"},{"w":"cake","p":"n.","d":"","c":"蛋糕","s":"Q: Does your mom like chocolate? — A: Yes, she does. She likes chocolate cake.","t":"你媽媽喜歡巧克力嗎？ — 是的，她喜歡。她喜歡巧克力蛋糕。"},{"w":"pie","p":"n.","d":"","c":"派","s":"Q: Do you like apples? — A: Yes, I do. I like apple pie best.","t":"你喜歡蘋果嗎？ — 是的，我喜歡。我最喜歡蘋果派。"},{"w":"bake","p":"v.","d":"","c":"烘烤","s":"Q: Do your grandparents like to make bread? — A: Yes, they do. They like to bake bread and cakes.","t":"你的爺爺奶奶喜歡做麵包嗎？ — 是的，他們喜歡。他們喜歡烤麵包和蛋糕。"},{"w":"cook","p":"v.","d":"","c":"煮飯；烹調","s":"Q: Does your dad like to work in the kitchen? — A: Yes, he does. He likes to cook dinner for us.","t":"你爸爸喜歡在廚房工作嗎？ — 是的，他喜歡。他喜歡煮晚餐給我們吃。"},{"w":"egg (eggs)","p":"n.","d":"","c":"蛋","s":"Q: How many eggs does Mom need for the cake? — A: She needs three. She doesn't need any milk.","t":"媽媽做蛋糕需要幾顆蛋？ — 她需要三顆，她不需要任何牛奶。"},{"w":"bun (buns)","p":"n.","d":"","c":"小圓麵包；包子","s":"Q: How many buns do you want? — A: I want two. I'm very hungry.","t":"你想要幾個小圓麵包？ — 我想要兩個，我很餓。"},{"w":"dumpling (dumplings)","p":"n.","d":"","c":"水餃；湯圓","s":"Q: How many dumplings does Dad want? — A: He wants twenty! He has them for dinner.","t":"爸爸想要幾顆水餃？ — 他想要二十顆！他晚餐要吃。"},{"w":"cookie (cookies)","p":"n.","d":"","c":"餅乾","s":"Q: How many cookies do the kids have? — A: They have ten. They want to share them.","t":"孩子們有幾片餅乾？ — 他們有十片，他們想要分享。"},{"w":"bread","p":"n.","d":"","c":"麵包","s":"Q: How much bread do we have? — A: We don't have any. Let's buy some.","t":"我們有多少麵包？ — 我們一點都沒有了，我們去買一些吧。"},{"w":"rice","p":"n.","d":"","c":"米飯","s":"Q: How much rice does your brother eat? — A: He eats three bowls every day.","t":"你哥哥吃多少飯？ — 他每天吃三碗。"},{"w":"salt","p":"n.","d":"","c":"鹽","s":"Q: How much salt does the soup need? — A: It needs a little.","t":"這湯需要多少鹽？ — 它需要一點點。"},{"w":"sugar","p":"n.","d":"","c":"糖","s":"Q: How much sugar do you want in your coffee? — A: I don't want any, thanks.","t":"你的咖啡裡要加多少糖？ — 我一點都不要，謝謝。"},{"w":"oil","p":"n.","d":"","c":"油","s":"Q: How much oil does Mom need? — A: She needs a little. She is cooking eggs.","t":"媽媽需要多少油？ — 她需要一點點，她正在煎蛋。"},{"w":"butter","p":"n.","d":"","c":"奶油","s":"Q: Do we have any butter? — A: Yes, we have some. It's in the fridge.","t":"我們有奶油嗎？ — 有，我們有一些，在冰箱裡。"},{"w":"milk","p":"n.","d":"","c":"牛奶","s":"Q: How much milk does the baby drink? — A: She drinks three bottles a day.","t":"這個寶寶喝多少牛奶？ — 她一天喝三瓶。"},{"w":"water","p":"n.","d":"","c":"水","s":"Q: How many glasses of water do you drink every day? — A: I drink eight glasses.","t":"你每天喝幾杯水？ — 我喝八杯。"},{"w":"soup","p":"n.","d":"","c":"湯","s":"Q: How does the soup taste? — A: It's good, but it needs more salt.","t":"這湯嚐起來怎麼樣？ — 很好，但它需要多一點鹽。"},{"w":"steak","p":"n.","d":"","c":"牛排","s":"Q: How does your steak taste? — A: It's great. I like beef.","t":"你的牛排嚐起來怎麼樣？ — 很棒，我喜歡牛肉。"},{"w":"salad","p":"n.","d":"","c":"沙拉","s":"Q: How does the salad taste? — A: It's fresh. It has lettuce and tomatoes.","t":"這沙拉嚐起來怎麼樣？ — 很新鮮，裡面有生菜和番茄。"},{"w":"delicious","p":"adj.","d":"","c":"美味的","s":"Q: How does Mom's beef soup taste? — A: It tastes delicious.","t":"媽媽的牛肉湯嚐起來怎麼樣？ — 它嚐起來很美味。"},{"w":"yummy","p":"adj.","d":"","c":"好吃的","s":"Q: How do the cookies taste? — A: They're yummy! I want more.","t":"這些餅乾嚐起來怎麼樣？ — 它們好好吃！我還想要。"},{"w":"sweet","p":"adj.","d":"","c":"甜的","s":"Q: How does the watermelon taste? — A: It tastes very sweet.","t":"這西瓜嚐起來怎麼樣？ — 它嚐起來很甜。"},{"w":"hot","p":"adj.","d":"","c":"熱的；燙的；辣的","s":"Q: How do the noodles taste? — A: They're too hot. Wait a minute.","t":"這些麵嚐起來怎麼樣？ — 它們太燙了，等一下吧。"},{"w":"burn (burns)","p":"v.","d":"","c":"燒焦；燃燒","s":"Q: How does the toast taste? — A: It tastes bad. Dad often burns it.","t":"這土司嚐起來怎麼樣？ — 嚐起來很糟，爸爸常常把它烤焦。"},{"w":"breakfast","p":"n.","d":"","c":"早餐","s":"Q: What do you have for breakfast? — A: I have toast and milk every morning.","t":"你早餐吃什麼？ — 我每天早上吃土司和喝牛奶。"},{"w":"toast","p":"n.","d":"","c":"土司","s":"Q: What does Dad have for breakfast? — A: He has toast and coffee for breakfast.","t":"爸爸早餐吃什麼？ — 他早餐吃土司、喝咖啡。"},{"w":"drink","p":"v.","d":"","c":"喝","s":"Q: What do your kids have for breakfast? — A: They have bread, and they drink a glass of milk.","t":"你的孩子們早餐吃什麼？ — 他們吃麵包，而且喝一杯牛奶。"},{"w":"boil (boils)","p":"v.","d":"","c":"煮沸；水煮","s":"Q: What does Grandma have for breakfast? — A: She has two eggs. She boils them in water.","t":"奶奶早餐吃什麼？ — 她吃兩顆蛋，她用水把蛋煮熟。"},{"w":"lunch","p":"n.","d":"","c":"午餐","s":"Q: What does Amy have for lunch? — A: She has rice and fish at noon.","t":"艾美午餐吃什麼？ — 她中午吃飯和魚。"},{"w":"sandwich","p":"n.","d":"","c":"三明治","s":"Q: What do you have for lunch? — A: I have a ham sandwich for lunch.","t":"你午餐吃什麼？ — 我午餐吃火腿三明治。"},{"w":"noodles","p":"n.","d":"","c":"麵條","s":"Q: What does your dad have for lunch? — A: He has beef noodles for lunch.","t":"你爸爸午餐吃什麼？ — 他午餐吃牛肉麵。"},{"w":"eat (eats)","p":"v.","d":"","c":"吃","s":"Q: What does your brother have for dinner? — A: He eats rice and pork for dinner.","t":"你哥哥晚餐吃什麼？ — 他晚餐吃飯和豬肉。"},{"w":"dinner","p":"n.","d":"","c":"晚餐","s":"Q: What do your parents have for dinner? — A: They have soup and steak in the evening.","t":"你爸媽晚餐吃什麼？ — 他們晚上吃湯和牛排。"},{"w":"meal","p":"n.","d":"","c":"一餐","s":"Q: What does your family have for dinner on Sundays? — A: We have a big meal together.","t":"你們家星期天晚餐吃什麼？ — 我們一起吃一頓大餐。"},{"w":"barbecue","p":"n.","d":"","c":"烤肉","s":"Q: What do you have for dinner on Moon Festival? — A: We have a barbecue with our neighbors.","t":"中秋節你們晚餐吃什麼？ — 我們和鄰居一起烤肉。"},{"w":"snack","p":"n.","d":"","c":"點心","s":"Q: What do you have after school? — A: I have a snack: some fruit and milk.","t":"你放學後吃什麼？ — 我吃點心：一些水果和牛奶。"}]},{"unit":11,"theme":"Tableware 餐具（第11區）","cards":[{"w":"chopsticks","p":"n.","d":"","c":"筷子","s":"Q: What do you use to eat noodles? — A: I use chopsticks. They are easy for me.","t":"你用什麼吃麵？ — 我用筷子，筷子對我來說很容易。"},{"w":"spoon","p":"n.","d":"","c":"湯匙","s":"Q: What does your little brother use to eat soup? — A: He uses a spoon.","t":"你弟弟用什麼喝湯？ — 他用湯匙。"},{"w":"fork (forks)","p":"n.","d":"","c":"叉子","s":"Q: Do your American friends use chopsticks? — A: No, they don't. They use forks.","t":"你的美國朋友用筷子嗎？ — 不，他們不用，他們用叉子。"},{"w":"knife","p":"n.","d":"","c":"刀子","s":"Q: Does your dad use chopsticks to eat steak? — A: No, he doesn't. He uses a knife and a fork.","t":"你爸爸用筷子吃牛排嗎？ — 不，他不用，他用刀子和叉子。"},{"w":"cup","p":"n.","d":"","c":"茶杯；杯子","s":"Q: What does your mom use to drink coffee? — A: She uses a big cup.","t":"你媽媽用什麼喝咖啡？ — 她用一個大杯子。"},{"w":"glass","p":"n.","d":"","c":"玻璃杯","s":"Q: I'm thirsty. Can I have a glass of water, please? — A: Sure. Here you are.","t":"我口渴了，可以給我一杯水嗎？ — 當然，給你。"},{"w":"bowl","p":"n.","d":"","c":"碗","s":"Q: Mom, can I have a bowl of rice, please? — A: Sure. Here you are. It's hot!","t":"媽，可以給我一碗飯嗎？ — 當然，給你，很燙喔！"},{"w":"plate","p":"n.","d":"","c":"盤子","s":"Q: Can I have a plate, please? I want some cake. — A: Sure. Here's a clean one.","t":"可以給我一個盤子嗎？我想吃一些蛋糕。 — 當然，這裡有一個乾淨的。"},{"w":"dish","p":"n.","d":"","c":"菜餚；盤子","s":"Q: Can I have this chicken dish, please? — A: Sure. Do you want rice with it?","t":"我可以點這道雞肉料理嗎？ — 好的，您要配飯嗎？"},{"w":"lid","p":"n.","d":"","c":"蓋子","s":"Q: Can I have a lid for my cup, please? The tea is hot. — A: Of course. Put it on, and your tea stays hot.","t":"可以給我一個杯蓋嗎？茶很燙。 — 當然可以，蓋上去，你的茶就會保溫。"}]},{"unit":12,"theme":"Clothing & Accessories 衣物與配件（第12區）","cards":[{"w":"coat","p":"n.","d":"","c":"大衣","s":"Q: What are you wearing today? It's so cold. — A: I'm wearing a long coat. It's warm.","t":"你今天穿什麼？好冷喔。 — 我穿著一件長大衣，很暖和。"},{"w":"jacket","p":"n.","d":"","c":"夾克","s":"Q: What is your brother wearing? — A: He is wearing a black jacket.","t":"你哥哥穿著什麼？ — 他穿著一件黑色夾克。"},{"w":"sweater","p":"n.","d":"","c":"毛衣","s":"Q: What is Grandma wearing? — A: She is wearing a warm sweater.","t":"奶奶穿著什麼？ — 她穿著一件保暖的毛衣。"},{"w":"dress","p":"n.","d":"","c":"洋裝","s":"Q: What is Amy wearing to the party? — A: She is wearing a pink dress. She looks beautiful.","t":"艾美穿什麼去派對？ — 她穿著一件粉紅色洋裝，看起來很美。"},{"w":"skirt (skirts)","p":"n.","d":"","c":"裙子","s":"Q: What are the girls wearing? — A: They are wearing white shirts and blue skirts.","t":"女孩們穿著什麼？ — 她們穿著白襯衫和藍裙子。"},{"w":"shirt","p":"n.","d":"","c":"襯衫","s":"Q: What is your dad wearing today? — A: He is wearing a white shirt and a tie.","t":"你爸爸今天穿著什麼？ — 他穿著白襯衫，打著領帶。"},{"w":"T-shirt","p":"n.","d":"","c":"T恤","s":"Q: What are you wearing? It's so hot! — A: I'm wearing a T-shirt and shorts.","t":"你穿什麼？好熱喔！ — 我穿著T恤和短褲。"},{"w":"shorts","p":"n.","d":"","c":"短褲","s":"Q: What is Ben wearing to the beach? — A: He is wearing shorts.","t":"班穿什麼去海邊？ — 他穿著短褲。"},{"w":"pants","p":"n.","d":"","c":"長褲","s":"Q: What are you wearing for the hike? — A: I'm wearing long pants and a jacket.","t":"你健行要穿什麼？ — 我穿長褲和一件夾克。"},{"w":"pocket (pockets)","p":"n.","d":"","c":"口袋","s":"Q: What is Tom wearing? — A: He is wearing a jacket with two big pockets.","t":"湯姆穿著什麼？ — 他穿著一件有兩個大口袋的夾克。"},{"w":"clothes","p":"n.","d":"","c":"衣服","s":"Q: What are the children wearing for Halloween? — A: They are wearing funny clothes.","t":"孩子們萬聖節穿什麼？ — 他們穿著好笑的衣服。"},{"w":"uniform","p":"n.","d":"","c":"制服","s":"Q: What do students wear at your school? — A: We wear a school uniform every day.","t":"你們學校的學生穿什麼？ — 我們每天穿校服。"},{"w":"wear (wears)","p":"v.","d":"","c":"穿；戴","s":"Q: What does your mom wear to work? — A: She wears a dress and a coat.","t":"你媽媽穿什麼去上班？ — 她穿洋裝和大衣。"},{"w":"bag","p":"n.","d":"","c":"袋子；包包","s":"Q: Whose bag is this? It's on my desk. — A: It's mine. Thank you.","t":"這是誰的包包？它在我桌上。 — 是我的，謝謝你。"},{"w":"wallet","p":"n.","d":"","c":"皮夾","s":"Q: Whose wallet is this? There is money in it. — A: It's Dad's. He is looking for it.","t":"這是誰的皮夾？裡面有錢。 — 是爸爸的，他正在找它。"},{"w":"umbrella","p":"n.","d":"","c":"雨傘","s":"Q: Whose umbrella is this? It's wet. — A: It's Amy's. It's raining outside.","t":"這是誰的雨傘？它是濕的。 — 是艾美的，外面在下雨。"},{"w":"comb","p":"n.","d":"","c":"梳子","s":"Q: Whose comb is this? — A: It's my sister's. She uses it every morning.","t":"這是誰的梳子？ — 是我妹妹的，她每天早上用它。"},{"w":"button","p":"n.","d":"","c":"鈕扣","s":"Q: Whose button is this? It's on the floor. — A: It's mine. It's from my shirt.","t":"這是誰的鈕扣？它在地板上。 — 是我的，是我襯衫上的。"},{"w":"cap","p":"n.","d":"","c":"棒球帽；便帽","s":"Q: It's very sunny today. What should I do? — A: Put on your cap.","t":"今天太陽好大，我該怎麼辦？ — 戴上你的帽子。"},{"w":"hat","p":"n.","d":"","c":"帽子","s":"Q: Does Ben wear a hat in class? — A: No, he doesn't. The teacher says, \"Take off your hat.\"","t":"班上課時戴帽子嗎？ — 不，他不戴。老師說：「把帽子脫下來。」"},{"w":"glove (gloves)","p":"n.","d":"","c":"手套","s":"Q: Do your hands feel cold? — A: Yes, they do. Let me put on my gloves.","t":"你的手覺得冷嗎？ — 是的，讓我戴上手套。"},{"w":"mask","p":"n.","d":"","c":"口罩；面具","s":"Q: I have a cold. What should I do? — A: Put on a mask, and drink a lot of water.","t":"我感冒了，我該怎麼辦？ — 戴上口罩，並且多喝水。"},{"w":"tie","p":"n.","d":"","c":"領帶","s":"Q: Dad, you're home! Are you tired? — A: Yes. Let me take off my tie and rest.","t":"爸，你回來了！你累了嗎？ — 是啊，讓我拿下領帶休息一下。"},{"w":"belt","p":"n.","d":"","c":"皮帶","s":"Q: How much is this brown belt? — A: It is 350 dollars.","t":"這條咖啡色皮帶多少錢？ — 它是三百五十元。"},{"w":"ring","p":"n.","d":"","c":"戒指","s":"Q: How much does this gold ring cost? — A: It costs 5,000 dollars. It's expensive!","t":"這枚金戒指要多少錢？ — 它要五千元，好貴！"},{"w":"jeans","p":"n.","d":"","c":"牛仔褲","s":"Q: How much do these blue jeans cost? — A: They cost 900 dollars.","t":"這件藍色牛仔褲要多少錢？ — 它要九百元。"},{"w":"shoes","p":"n.","d":"","c":"鞋子","s":"Q: How much are those black shoes? — A: They are 1,200 dollars.","t":"那雙黑色鞋子多少錢？ — 它們是一千兩百元。"},{"w":"socks","p":"n.","d":"","c":"襪子","s":"Q: How much does a pair of socks cost? — A: It costs 60 dollars.","t":"一雙襪子要多少錢？ — 一雙要六十元。"}]},{"unit":13,"theme":"Colors 顏色（第13區）","cards":[{"w":"color","p":"n.","d":"","c":"顏色","s":"Q: What color is your new jacket? — A: It's black and white. I like it a lot.","t":"你的新夾克是什麼顏色？ — 它是黑白相間的，我很喜歡。"},{"w":"black","p":"adj.","d":"","c":"黑色（的）","s":"Q: What color is your father's tie? — A: It's black. He wears it to work.","t":"你爸爸的領帶是什麼顏色？ — 是黑色的，他打它去上班。"},{"w":"white","p":"adj.","d":"","c":"白色（的）","s":"Q: What color are your school socks? — A: They are white.","t":"你們學校的襪子是什麼顏色？ — 它們是白色的。"},{"w":"gray","p":"adj.","d":"","c":"灰色（的）","s":"Q: What color are Grandpa's pants? — A: They are gray, like a cloudy sky.","t":"爺爺的長褲是什麼顏色？ — 它們是灰色的，像陰天的天空。"},{"w":"brown","p":"adj.","d":"","c":"棕色（的）","s":"Q: What color is your wallet? — A: It's brown. It's in my pocket.","t":"你的皮夾是什麼顏色？ — 是棕色的，在我的口袋裡。"},{"w":"red","p":"adj.","d":"","c":"紅色（的）","s":"Q: What does Mom want to buy? — A: She wants to buy a pair of red shoes.","t":"媽媽想要買什麼？ — 她想要買一雙紅色的鞋子。"},{"w":"pink","p":"adj.","d":"","c":"粉紅色（的）","s":"Q: What do the girls want to buy? — A: They want to buy two pink skirts.","t":"女孩們想要買什麼？ — 她們想要買兩件粉紅色裙子。"},{"w":"orange","p":"adj.","d":"","c":"橘色（的）","s":"Q: Does Tom want to buy a black cap? — A: No, he doesn't. He wants to buy an orange cap.","t":"湯姆想要買一頂黑色棒球帽嗎？ — 不，他不想。他想要買一頂橘色的棒球帽。"},{"w":"yellow","p":"adj.","d":"","c":"黃色（的）","s":"Q: Do you and your sister want to buy umbrellas? — A: Yes, we do. We want to buy two yellow umbrellas.","t":"你和你妹妹想要買雨傘嗎？ — 是的，我們想。我們想要買兩把黃色雨傘。"},{"w":"green","p":"adj.","d":"","c":"綠色（的）","s":"Q: What's your favorite color? — A: My favorite color is green. I love trees.","t":"你最喜歡的顏色是什麼？ — 我最喜歡的顏色是綠色，我喜愛樹木。"},{"w":"blue","p":"adj.","d":"","c":"藍色（的）","s":"Q: What's Ben's favorite color? — A: It's blue. He loves the sea and the sky.","t":"班最喜歡的顏色是什麼？ — 是藍色，他喜愛大海和天空。"},{"w":"purple","p":"adj.","d":"","c":"紫色（的）","s":"Q: What's your sister's favorite color? — A: Her favorite color is purple. She likes grapes.","t":"你妹妹最喜歡的顏色是什麼？ — 她最喜歡的顏色是紫色，她喜歡葡萄。"}]},{"unit":14,"theme":"Sports, Interests & Hobbies 運動、興趣與嗜好（第14區）","cards":[{"w":"hobby","p":"n.","d":"","c":"嗜好","s":"Q: What's your hobby? What do you like to do? — A: I like to take pictures in the park.","t":"你的嗜好是什麼？你喜歡做什麼？ — 我喜歡在公園拍照。"},{"w":"sing (singing)","p":"v.","d":"","c":"唱歌","s":"Q: What does Amy like to do? — A: She likes singing in the music room.","t":"艾美喜歡做什麼？ — 她喜歡在音樂教室唱歌。"},{"w":"song (songs)","p":"n.","d":"","c":"歌曲","s":"Q: What do you like to do after school? — A: I like to sing English songs.","t":"你放學後喜歡做什麼？ — 我喜歡唱英文歌。"},{"w":"music","p":"n.","d":"","c":"音樂","s":"Q: Does Tina enjoy listening to music? — A: Yes, she does. She listens to it every night.","t":"蒂娜喜歡聽音樂嗎？ — 是的，她喜歡。她每天晚上都聽。"},{"w":"dance","p":"v.","d":"","c":"跳舞","s":"Q: What do you and your sister like to do? — A: We like to dance to pop music.","t":"你和你妹妹喜歡做什麼？ — 我們喜歡隨著流行音樂跳舞。"},{"w":"draw (drawing)","p":"v.","d":"","c":"畫圖","s":"Q: Does Ben enjoy drawing? — A: Yes, he does. He has many pictures of cats in his notebook.","t":"班喜歡畫圖嗎？ — 是的，他喜歡。他的筆記本裡有很多貓的圖。"},{"w":"paint (painting)","p":"v.","d":"","c":"（用顏料）畫圖","s":"Q: Do your parents enjoy painting? — A: No, they don't. They enjoy reading books.","t":"你爸媽喜歡畫畫嗎？ — 不，他們不喜歡。他們喜歡看書。"},{"w":"cook","p":"v.","d":"","c":"煮飯；烹飪","s":"Q: What does your father like to do on Sundays? — A: He likes to cook dinner for us.","t":"你爸爸星期天喜歡做什麼？ — 他喜歡為我們煮晚餐。"},{"w":"movie (movies)","p":"n.","d":"","c":"電影","s":"Q: Do they enjoy watching movies? — A: Yes, they do. They go to the theater every weekend.","t":"他們喜歡看電影嗎？ — 是的，他們喜歡。他們每個週末都去戲院。"},{"w":"comic","p":"adj.","d":"","c":"漫畫的","s":"Q: What does Tom like to do on weekends? — A: He likes to read comic books.","t":"湯姆週末喜歡做什麼？ — 他喜歡看漫畫書。"},{"w":"swim","p":"v.","d":"","c":"游泳","s":"Q: Can your brother swim? — A: Yes, he can. He goes to the pool every week.","t":"你哥哥會游泳嗎？ — 是的，他會。他每週都去游泳池。"},{"w":"surf","p":"v.","d":"","c":"衝浪","s":"Q: Can you surf? — A: No, I can't. But I want to learn it at the beach.","t":"你會衝浪嗎？ — 不，我不會。但我想在海灘學。"},{"w":"sail","p":"v.","d":"","c":"航行；駕船","s":"Q: Can your uncle sail a boat? — A: Yes, he can. He often takes us out on the lake.","t":"你叔叔會駕船嗎？ — 是的，他會。他常帶我們到湖上。"},{"w":"climb","p":"v.","d":"","c":"爬；攀登","s":"Q: Can Grandpa climb the mountain? — A: Yes, he can. He is old, but he is strong.","t":"爺爺爬得上這座山嗎？ — 是的，他可以。他年紀大，但很強壯。"},{"w":"run","p":"v.","d":"","c":"跑步","s":"Q: Can the twins run fast? — A: Yes, they can. They are the fastest in our class.","t":"那對雙胞胎跑得快嗎？ — 是的，他們可以。他們是我們班跑最快的。"},{"w":"piano","p":"n.","d":"","c":"鋼琴","s":"Q: Can Amy play the piano? — A: Yes, she can. She plays it very well.","t":"艾美會彈鋼琴嗎？ — 是的，她會。她彈得很好。"},{"w":"violin","p":"n.","d":"","c":"小提琴","s":"Q: Can you play the violin? — A: No, I can't. But my sister can.","t":"你會拉小提琴嗎？ — 不，我不會。但我姊姊會。"},{"w":"guitar","p":"n.","d":"","c":"吉他","s":"Q: Can your father play the guitar? — A: Yes, he can. He plays it and sings for us.","t":"你爸爸會彈吉他嗎？ — 是的，他會。他邊彈邊唱給我們聽。"},{"w":"drum (drums)","p":"n.","d":"","c":"鼓","s":"Q: Can Tom play the drums? — A: No, he can't. But he wants to learn.","t":"湯姆會打鼓嗎？ — 不，他不會。但他想學。"},{"w":"flute","p":"n.","d":"","c":"長笛；笛子","s":"Q: Can your cousins play the flute? — A: Yes, they can. They play it in music class.","t":"你的表姊妹們會吹長笛嗎？ — 是的，她們會。她們在音樂課吹。"},{"w":"basketball","p":"n.","d":"","c":"籃球","s":"Q: Let's play basketball after school. — A: OK! See you on the playground.","t":"我們放學後去打籃球吧。 — 好啊！操場見。"},{"w":"baseball","p":"n.","d":"","c":"棒球","s":"Q: Would you like to play baseball with us? — A: Sure. I have a new bat and a glove.","t":"你想和我們一起打棒球嗎？ — 當然。我有新的球棒和手套。"},{"w":"soccer","p":"n.","d":"","c":"足球","s":"Q: Let's play soccer in the park. — A: Good idea! Ben and Tom can come, too.","t":"我們去公園踢足球吧。 — 好主意！班和湯姆也可以來。"},{"w":"tennis","p":"n.","d":"","c":"網球","s":"Q: Would you like to play tennis with us this Saturday? — A: Sorry, I can't. I have math class.","t":"你這星期六想和我們一起打網球嗎？ — 抱歉，我不行。我有數學課。"},{"w":"badminton","p":"n.","d":"","c":"羽毛球","s":"Q: Let's play badminton in the gym. — A: OK. It's too windy outside.","t":"我們在體育館打羽毛球吧。 — 好。外面風太大了。"},{"w":"dodge ball","p":"n.","d":"","c":"躲避球","s":"Q: Would you like to play dodge ball with us? — A: Yes, I'd love to. It's fun!","t":"你想跟我們一起玩躲避球嗎？ — 是的，我很樂意。好好玩！"},{"w":"frisbee","p":"n.","d":"","c":"飛盤","s":"Q: Let's play frisbee on the beach. — A: Great! I'll throw it to you first.","t":"我們在海灘玩飛盤吧。 — 太好了！我先丟給你。"},{"w":"chess","p":"n.","d":"","c":"西洋棋","s":"Q: Would you like to play chess with Grandpa and me? — A: Sure. But Grandpa is very good at it!","t":"你想和爺爺跟我一起下西洋棋嗎？ — 當然，但是爺爺很厲害！"},{"w":"ball","p":"n.","d":"","c":"球","s":"Q: Let's play ball in the yard. — A: OK. Throw it to me!","t":"我們在院子裡玩球吧。 — 好，丟給我！"},{"w":"kite","p":"n.","d":"","c":"風箏","s":"Q: Would you like to fly a kite with us? It's windy today. — A: Yes, I'd love to.","t":"你想和我們一起放風箏嗎？今天風很大。 — 是的，我很樂意。"},{"w":"camp (camping)","p":"v.","d":"","c":"露營","s":"Q: Would you like to go camping with us this weekend? — A: Yes! Let's sleep under the stars.","t":"你這個週末想和我們一起去露營嗎？ — 好！我們來睡在星空下吧。"},{"w":"picnic","p":"n.","d":"","c":"野餐","s":"Q: Would you like to have a picnic with us in the park? — A: Sure. I'll bring some sandwiches.","t":"你想和我們一起在公園野餐嗎？ — 當然。我會帶一些三明治。"},{"w":"hike (hiking)","p":"v.","d":"","c":"健行","s":"Q: Let's go hiking on the mountain tomorrow. — A: OK. Let's meet at seven in the morning.","t":"我們明天去山上健行吧。 — 好。我們早上七點見面。"},{"w":"play (playing)","p":"v.","d":"","c":"玩；打（球）","s":"Q: What are the children doing now? — A: They are playing in the yard.","t":"孩子們現在在做什麼？ — 他們正在院子裡玩。"},{"w":"game","p":"n.","d":"","c":"遊戲；比賽","s":"Q: What are you doing now? — A: I'm playing a computer game with my brother.","t":"你現在在做什麼？ — 我正在和弟弟玩電腦遊戲。"},{"w":"toy","p":"n.","d":"","c":"玩具","s":"Q: What is the baby doing now? — A: He is playing with his toy car.","t":"寶寶現在在做什麼？ — 他正在玩他的玩具車。"},{"w":"doll (dolls)","p":"n.","d":"","c":"洋娃娃","s":"Q: What is your little sister doing now? — A: She is playing with her dolls.","t":"你妹妹現在在做什麼？ — 她正在玩她的洋娃娃。"},{"w":"card","p":"n.","d":"","c":"卡片","s":"Q: What are you doing now, Amy? — A: I'm making a birthday card for Mom.","t":"艾美，你現在在做什麼？ — 我正在為媽媽做生日卡片。"},{"w":"fish (fishing)","p":"v.","d":"","c":"釣魚","s":"Q: What are Dad and Uncle Ben doing now? — A: They are fishing by the river.","t":"爸爸和班叔叔現在在做什麼？ — 他們正在河邊釣魚。"},{"w":"jog (jogging)","p":"v.","d":"","c":"慢跑","s":"Q: What is Mom doing now? — A: She is jogging in the park.","t":"媽媽現在在做什麼？ — 她正在公園慢跑。"},{"w":"exercise","p":"v.","d":"","c":"運動","s":"Q: How often do you exercise? — A: Three times a week. It keeps me healthy.","t":"你多久運動一次？ — 一週三次。它讓我保持健康。"},{"w":"sports","p":"n.","d":"","c":"運動","s":"Q: How often does your brother play sports? — A: He plays every day after school.","t":"你哥哥多久做一次運動？ — 他每天放學後都運動。"},{"w":"trip","p":"n.","d":"","c":"（短程）旅行","s":"Q: How often does your family take a trip? — A: We take one every summer.","t":"你們家多久去旅行一次？ — 我們每年夏天都去一次。"},{"w":"band","p":"n.","d":"","c":"樂團","s":"Q: How often does your band practice? — A: We practice twice a week, on Mondays and Fridays.","t":"你的樂團多久練習一次？ — 我們一週練習兩次，在星期一和星期五。"},{"w":"team","p":"n.","d":"","c":"隊；團隊","s":"Q: How often do you and your team practice? — A: We practice on Tuesdays and Thursdays.","t":"你和你的隊友多久練習一次？ — 我們每星期二和星期四練習。"},{"w":"stamp (stamps)","p":"n.","d":"","c":"郵票","s":"Q: What does your grandpa usually do in his free time? — A: He usually collects stamps from different countries.","t":"你爺爺空閒時通常做什麼？ — 他通常收集各國的郵票。"},{"w":"fan","p":"n.","d":"","c":"粉絲；狂熱愛好者","s":"Q: What do you usually do in your free time? — A: I listen to my favorite singer. I'm a big fan of her.","t":"你空閒時通常做什麼？ — 我聽我最喜歡的歌手的歌。我是她的超級粉絲。"},{"w":"race","p":"n.","d":"","c":"賽跑","s":"Q: What do Tom and Ben usually do in their free time? — A: They practice running for the race on sports day.","t":"湯姆和班空閒時通常做什麼？ — 他們練跑步，準備運動會的賽跑。"},{"w":"win","p":"v.","d":"","c":"贏","s":"Q: What does your sister usually do in her free time? — A: She practices the piano. She wants to win first prize.","t":"你姊姊空閒時通常做什麼？ — 她練鋼琴，她想得第一名。"},{"w":"lose","p":"v.","d":"","c":"輸","s":"Q: What do you and your friends usually do in your free time? — A: We play basketball. Sometimes we lose, but we always have fun.","t":"你和朋友們空閒時通常做什麼？ — 我們打籃球。有時候我們會輸，但總是玩得很開心。"}]},{"unit":15,"theme":"Houses & Apartments 房屋與公寓（第15區）","cards":[{"w":"bed","p":"n.","d":"","c":"床","s":"Q: Where is the cat? — A: It's on my bed. It's sleeping.","t":"貓在哪裡？ — 牠在我的床上，牠正在睡覺。"},{"w":"sofa","p":"n.","d":"","c":"沙發","s":"Q: Where is the dog? — A: It's on the sofa in the living room.","t":"狗在哪裡？ — 牠在客廳的沙發上。"},{"w":"couch","p":"n.","d":"","c":"沙發","s":"Q: Where are my comic books? — A: They're on the couch, next to the TV.","t":"我的漫畫書在哪裡？ — 它們在沙發上，電視旁邊。"},{"w":"chair","p":"n.","d":"","c":"椅子","s":"Q: Where is my schoolbag? — A: It's under your chair.","t":"我的書包在哪裡？ — 它在你的椅子下面。"},{"w":"desk","p":"n.","d":"","c":"書桌","s":"Q: Where are my books? — A: They're on your desk.","t":"我的書在哪裡？ — 它們在你的書桌上。"},{"w":"table","p":"n.","d":"","c":"桌子","s":"Q: Where does Mom put the cake? — A: She puts it on the table.","t":"媽媽把蛋糕放在哪裡？ — 她把它放在桌上。"},{"w":"drawer","p":"n.","d":"","c":"抽屜","s":"Q: Where do you keep your pens? — A: I keep them in the drawer.","t":"你把筆放在哪裡？ — 我把它們放在抽屜裡。"},{"w":"lamp","p":"n.","d":"","c":"檯燈","s":"Q: Where is the lamp? — A: It's on the desk, next to the computer.","t":"檯燈在哪裡？ — 它在書桌上，電腦旁邊。"},{"w":"blanket","p":"n.","d":"","c":"毯子","s":"Q: Where is my blanket? I'm cold. — A: It's on your bed.","t":"我的毯子在哪裡？我好冷。 — 它在你的床上。"},{"w":"towel (towels)","p":"n.","d":"","c":"毛巾","s":"Q: Where are the towels? — A: They're in the bathroom.","t":"毛巾在哪裡？ — 它們在浴室裡。"},{"w":"key (keys)","p":"n.","d":"","c":"鑰匙","s":"Q: Where are my keys? — A: They're in your pocket, Dad!","t":"我的鑰匙在哪裡？ — 爸爸，它們在你的口袋裡！"},{"w":"umbrella","p":"n.","d":"","c":"雨傘","s":"Q: Where does Dad keep his umbrella? — A: He keeps it behind the door.","t":"爸爸把他的雨傘放在哪裡？ — 他把它放在門後面。"},{"w":"basket","p":"n.","d":"","c":"籃子","s":"Q: Where are the apples? — A: They're in the basket on the table.","t":"蘋果在哪裡？ — 它們在桌上的籃子裡。"},{"w":"pot","p":"n.","d":"","c":"鍋子；壺","s":"Q: Where is the soup? — A: It's in the pot in the kitchen.","t":"湯在哪裡？ — 它在廚房的鍋子裡。"},{"w":"candle (candles)","p":"n.","d":"","c":"蠟燭","s":"Q: Where are the candles? — A: They're on the birthday cake.","t":"蠟燭在哪裡？ — 它們在生日蛋糕上。"},{"w":"mat","p":"n.","d":"","c":"墊子","s":"Q: Where do we put our shoes? — A: Put them on the mat by the door.","t":"我們把鞋子放在哪裡？ — 把它們放在門邊的墊子上。"},{"w":"bench","p":"n.","d":"","c":"長椅","s":"Q: Is there a bench in the garden? — A: Yes, there is. Grandma often sits on it.","t":"花園裡有長椅嗎？ — 是的，有。奶奶常常坐在上面。"},{"w":"light","p":"n.","d":"","c":"燈；燈光","s":"Q: Is there a light in the bathroom? — A: Yes, there is. But it doesn't work now.","t":"浴室裡有燈嗎？ — 是的，有。但是它現在壞了。"},{"w":"television (TV)","p":"n.","d":"","c":"電視","s":"Q: Is there a television in your bedroom? — A: No, there isn't. It's in the living room.","t":"你的臥室裡有電視嗎？ — 不，沒有。它在客廳裡。"},{"w":"computer","p":"n.","d":"","c":"電腦","s":"Q: Is there a computer in your room? — A: Yes, there is. I do my homework on it.","t":"你的房間裡有電腦嗎？ — 是的，有。我用它寫功課。"},{"w":"telephone (phone)","p":"n.","d":"","c":"電話","s":"Q: Is there a telephone in the kitchen? — A: No, there isn't. It's on the table in the living room.","t":"廚房裡有電話嗎？ — 不，沒有。它在客廳的桌上。"},{"w":"radio","p":"n.","d":"","c":"收音機","s":"Q: Is there a radio in Grandpa's room? — A: Yes, there is. He listens to it every morning.","t":"爺爺的房間裡有收音機嗎？ — 是的，有。他每天早上都聽。"},{"w":"camera","p":"n.","d":"","c":"照相機","s":"Q: Is there a camera in your bag? — A: Yes, there is. I want to take pictures in the park.","t":"你的包包裡有相機嗎？ — 是的，有。我想在公園拍照。"},{"w":"fan","p":"n.","d":"","c":"電風扇","s":"Q: Is there a fan in your bedroom? It's so hot. — A: No, there isn't. Let's go to the living room.","t":"你的臥室裡有電風扇嗎？好熱喔。 — 不，沒有。我們去客廳吧。"},{"w":"refrigerator (fridge)","p":"n.","d":"","c":"冰箱","s":"Q: Is there any milk in the refrigerator? — A: Yes, there is. It's next to the eggs.","t":"冰箱裡有牛奶嗎？ — 是的，有。它在蛋的旁邊。"},{"w":"machine","p":"n.","d":"","c":"機器","s":"Q: Is there a washing machine in your apartment? — A: Yes, there is. It's on the balcony.","t":"你的公寓裡有洗衣機嗎？ — 是的，有。它在陽台上。"},{"w":"tape (tapes)","p":"n.","d":"","c":"錄音帶；膠帶","s":"Q: Are there any English tapes in the box? — A: Yes, there are. We can listen to them.","t":"箱子裡有英文錄音帶嗎？ — 是的，有。我們可以聽它們。"},{"w":"video (videos)","p":"n.","d":"","c":"影片；錄影帶","s":"Q: Are there any funny videos on your phone? — A: Yes, there are. Let's watch them together!","t":"你的手機裡有好笑的影片嗎？ — 是的，有。我們一起看吧！"},{"w":"pipe","p":"n.","d":"","c":"管子；水管","s":"Q: Is there any water in the pipe? — A: No, there isn't. It's broken.","t":"水管裡有水嗎？ — 不，沒有。它破了。"},{"w":"house","p":"n.","d":"","c":"房子","s":"Q: What is there near the park? — A: There is a big house with a garden.","t":"公園附近有什麼？ — 有一棟有花園的大房子。"},{"w":"apartment","p":"n.","d":"","c":"公寓","s":"Q: How many bedrooms are there in your apartment? — A: There are three bedrooms.","t":"你的公寓裡有幾間臥室？ — 有三間臥室。"},{"w":"door","p":"n.","d":"","c":"門","s":"Q: What is there on the door? — A: There is a picture of our family.","t":"門上有什麼？ — 有一張我們的全家福照片。"},{"w":"window (windows)","p":"n.","d":"","c":"窗戶","s":"Q: How many windows are there in your room? — A: There are two. They are very big.","t":"你的房間裡有幾扇窗戶？ — 有兩扇，它們很大。"},{"w":"wall","p":"n.","d":"","c":"牆壁","s":"Q: What is there on the wall? — A: There is a clock and two pictures.","t":"牆上有什麼？ — 有一個時鐘和兩幅畫。"},{"w":"floor","p":"n.","d":"","c":"地板","s":"Q: What is there on the floor? — A: There are some toys. Please pick them up.","t":"地板上有什麼？ — 有一些玩具，請把它們撿起來。"},{"w":"gate","p":"n.","d":"","c":"大門","s":"Q: Who is there at the gate? — A: There is a man with a big box.","t":"大門口有誰？ — 有一個拿著大箱子的男人。"},{"w":"stairs","p":"n.","d":"","c":"樓梯","s":"Q: How many floors are there in your house? — A: There are three. We walk up the stairs to our bedrooms.","t":"你家有幾層樓？ — 有三層。我們走樓梯上去臥室。"},{"w":"home","p":"n.","d":"","c":"家","s":"Q: Where are you, Ben? — A: I'm at home. I'm watching TV.","t":"班，你在哪裡？ — 我在家，我正在看電視。"},{"w":"room","p":"n.","d":"","c":"房間","s":"Q: Where is Amy? — A: She's in her room. She's doing her homework.","t":"艾美在哪裡？ — 她在她的房間，她正在寫功課。"},{"w":"bedroom","p":"n.","d":"","c":"臥室","s":"Q: Where are you, Lisa? — A: I'm in my bedroom. I'm getting ready for bed.","t":"麗莎，你在哪裡？ — 我在我的臥室，我正準備睡覺。"},{"w":"bathroom","p":"n.","d":"","c":"浴室","s":"Q: Where is Dad? — A: He's in the bathroom. He's taking a shower.","t":"爸爸在哪裡？ — 他在浴室，他正在淋浴。"},{"w":"kitchen","p":"n.","d":"","c":"廚房","s":"Q: Where are you, Mom? — A: I'm in the kitchen. I'm cooking dinner.","t":"媽媽，你在哪裡？ — 我在廚房，我正在煮晚餐。"},{"w":"dining room","p":"n.","d":"","c":"飯廳","s":"Q: Where are Grandpa and Grandma? — A: They're in the dining room. They're having lunch.","t":"爺爺和奶奶在哪裡？ — 他們在飯廳，他們正在吃午餐。"},{"w":"living room","p":"n.","d":"","c":"客廳","s":"Q: Where are the kids? — A: They're in the living room. They're playing games.","t":"孩子們在哪裡？ — 他們在客廳，他們正在玩遊戲。"},{"w":"balcony","p":"n.","d":"","c":"陽台","s":"Q: Where are you, Tom? — A: I'm on the balcony. I'm looking at the stars.","t":"湯姆，你在哪裡？ — 我在陽台上，我正在看星星。"},{"w":"garden","p":"n.","d":"","c":"花園","s":"Q: Where is Grandma? — A: She's in the garden. She's watering the flowers.","t":"奶奶在哪裡？ — 她在花園，她正在澆花。"},{"w":"yard","p":"n.","d":"","c":"庭院；院子","s":"Q: Where are you and your dog? — A: We're in the yard. We're playing with a ball.","t":"你和你的狗在哪裡？ — 我們在院子裡，我們正在玩球。"},{"w":"clean","p":"v.","d":"","c":"打掃","s":"Q: What do you do on Saturday mornings? — A: I clean my room.","t":"你星期六早上做什麼？ — 我打掃我的房間。"},{"w":"wash (washes)","p":"v.","d":"","c":"清洗","s":"Q: What does your brother do after dinner? — A: He washes the dishes.","t":"你哥哥晚餐後做什麼？ — 他洗碗。"},{"w":"fix","p":"v.","d":"","c":"修理","s":"Q: Does your dad fix things at home? — A: Yes, he does. Our old lamp works again now.","t":"你爸爸會在家修東西嗎？ — 是的，他會。我們的舊檯燈現在又能用了。"},{"w":"build","p":"v.","d":"","c":"建造","s":"Q: What do your uncle and his friends do? — A: They build houses. They are workers.","t":"你叔叔和他的朋友們做什麼？ — 他們蓋房子，他們是工人。"},{"w":"bath","p":"n.","d":"","c":"洗澡；浴缸","s":"Q: Does Amy take a bath every night? — A: No, she doesn't. She takes a shower.","t":"艾美每天晚上泡澡嗎？ — 不，她沒有。她淋浴。"},{"w":"street","p":"n.","d":"","c":"街道","s":"Q: Where does Tina live? — A: She lives on Park street.","t":"蒂娜住在哪裡？ — 她住在公園街。"},{"w":"road","p":"n.","d":"","c":"道路；路","s":"Q: Where do your grandparents live? — A: They live on Zhongshan road, near the station.","t":"你的爺爺奶奶住在哪裡？ — 他們住在中山路，車站附近。"}]},{"unit":16,"theme":"School 學校（第16區）","cards":[{"w":"Chinese","p":"n.","d":"","c":"中文；國文","s":"Q: What class do you have on Monday morning? — A: I have Chinese class first.","t":"你星期一早上有什麼課？ — 我第一堂是國文課。"},{"w":"English","p":"n.","d":"","c":"英語","s":"Q: What class does Amy have on Tuesday? — A: She has English class with Mr. Smith.","t":"艾美星期二有什麼課？ — 她有史密斯老師的英文課。"},{"w":"math (mathematics)","p":"n.","d":"","c":"數學","s":"Q: What class do Tom and Ben have now? — A: They have math class. They're counting numbers.","t":"湯姆和班現在上什麼課？ — 他們在上數學課，他們正在算數字。"},{"w":"history","p":"n.","d":"","c":"歷史","s":"Q: What class does your brother have this afternoon? — A: He has history class. He learns about the past.","t":"你哥哥今天下午有什麼課？ — 他有歷史課，他學習過去的事。"},{"w":"lesson (lessons)","p":"n.","d":"","c":"課","s":"Q: How many English lessons do you have a week? — A: I have five.","t":"你一週有幾堂英文課？ — 我有五堂。"},{"w":"course","p":"n.","d":"","c":"課程","s":"Q: What course does your mom take on Saturdays? — A: She takes a cooking class.","t":"你媽媽星期六上什麼課程？ — 她上烹飪課。"},{"w":"art","p":"n.","d":"","c":"美術","s":"Q: What's your favorite subject? — A: My favorite subject is art. I like to draw.","t":"你最喜歡的科目是什麼？ — 我最喜歡的科目是美術，我喜歡畫畫。"},{"w":"music","p":"n.","d":"","c":"音樂","s":"Q: What's Lisa's favorite subject? — A: Her favorite subject is music. She sings very well.","t":"麗莎最喜歡的科目是什麼？ — 她最喜歡的科目是音樂，她唱歌唱得很好。"},{"w":"PE (physical education)","p":"n.","d":"","c":"體育","s":"Q: What's Tom's favorite subject? — A: His favorite subject is PE. He loves to run.","t":"湯姆最喜歡的科目是什麼？ — 他最喜歡的科目是體育，他很愛跑步。"},{"w":"science","p":"n.","d":"","c":"自然科學","s":"Q: What's your favorite subject, Ben? — A: It's science. I like to learn about plants and animals.","t":"班，你最喜歡的科目是什麼？ — 是自然科學，我喜歡學習植物和動物。"},{"w":"language (languages)","p":"n.","d":"","c":"語言","s":"Q: What's Amy's favorite subject? — A: English. She can speak three languages.","t":"艾美最喜歡的科目是什麼？ — 英文。她會說三種語言。"},{"w":"dictionary","p":"n.","d":"","c":"字典","s":"Q: Can I borrow your dictionary? — A: Sure. Here you are.","t":"我可以借你的字典嗎？ — 當然，給你。"},{"w":"map","p":"n.","d":"","c":"地圖","s":"Q: Can I borrow your map of Taiwan? — A: Sorry, I'm using it now.","t":"我可以借你的臺灣地圖嗎？ — 抱歉，我現在正在用。"},{"w":"notebook","p":"n.","d":"","c":"筆記本","s":"Q: Can I borrow your notebook? I want to copy the notes. — A: OK. Here you are.","t":"我可以借你的筆記本嗎？我想抄筆記。 — 好，給你。"},{"w":"paper","p":"n.","d":"","c":"紙","s":"Q: Can I borrow a piece of paper? — A: Sure. Here you are.","t":"我可以借一張紙嗎？ — 當然，給你。"},{"w":"book","p":"n.","d":"","c":"書","s":"Q: Can I borrow this book? — A: Yes, you can. Please bring it back on Friday.","t":"我可以借這本書嗎？ — 可以，請在星期五還回來。"},{"w":"chalk","p":"n.","d":"","c":"粉筆","s":"Q: Can I borrow some chalk, Mr. Lee? — A: Sure. Write the answer on the blackboard.","t":"李老師，我可以借一些粉筆嗎？ — 當然，把答案寫在黑板上。"},{"w":"workbook","p":"n.","d":"","c":"作業本","s":"Q: Open your workbook to page ten. — A: OK, Ms. Lin.","t":"把你的作業本翻到第十頁。 — 好的，林老師。"},{"w":"page","p":"n.","d":"","c":"頁","s":"Q: Turn to page 25, please. — A: Page 25? OK.","t":"請翻到第 25 頁。 — 第 25 頁嗎？好。"},{"w":"blackboard","p":"n.","d":"","c":"黑板","s":"Q: Look at the blackboard, everyone. — A: Yes, Mr. Lee.","t":"大家看黑板。 — 是的，李老師。"},{"w":"picture","p":"n.","d":"","c":"圖片；照片","s":"Q: Look at the picture and tell me about it. — A: There are three cats in it.","t":"看這張圖片，然後跟我說說它。 — 圖裡有三隻貓。"},{"w":"listen","p":"v.","d":"","c":"聽","s":"Q: Listen carefully, everyone. — A: Yes, Ms. Chen.","t":"大家仔細聽。 — 是的，陳老師。"},{"w":"repeat","p":"v.","d":"","c":"重複；跟著唸","s":"Q: Repeat after me: \"apple.\" — A: \"Apple.\"","t":"跟著我唸：「apple」。 — 「Apple。」"},{"w":"say","p":"v.","d":"","c":"說；講","s":"Q: Say \"Good morning\" to your teacher. — A: Good morning, Ms. Wang!","t":"跟你的老師說「早安」。 — 王老師早安！"},{"w":"read","p":"v.","d":"","c":"讀；唸","s":"Q: Please read the story out loud, Tom. — A: OK, Ms. Lin.","t":"湯姆，請把這個故事大聲唸出來。 — 好的，林老師。"},{"w":"write","p":"v.","d":"","c":"寫","s":"Q: Write your name on the paper, please. — A: OK. Can I use a pencil?","t":"請在紙上寫你的名字。 — 好，我可以用鉛筆嗎？"},{"w":"spell","p":"v.","d":"","c":"拼字","s":"Q: Spell the word \"book,\" please. — A: B-O-O-K.","t":"請拼出 book 這個字。 — B-O-O-K。"},{"w":"draw","p":"v.","d":"","c":"畫","s":"Q: Draw a cat in your notebook. — A: OK. Can I color it, too?","t":"在你的筆記本裡畫一隻貓。 — 好，我也可以幫牠上色嗎？"},{"w":"answer","p":"v.","d":"","c":"回答","s":"Q: Please answer my question, Ben. — A: Sorry, I don't know.","t":"班，請回答我的問題。 — 抱歉，我不知道。"},{"w":"talk","p":"v.","d":"","c":"說話","s":"Q: Don't talk in class, Amy. — A: Sorry, Mr. Wang.","t":"艾美，上課不要說話。 — 對不起，王老師。"},{"w":"pen (pens)","p":"n.","d":"","c":"筆","s":"Q: What do you have in your pencil case? — A: I have two pens. One is red and one is blue.","t":"你的鉛筆盒裡有什麼？ — 我有兩支筆，一支紅色、一支藍色。"},{"w":"pencil","p":"n.","d":"","c":"鉛筆","s":"Q: What does Amy have in her pencil case? — A: She has a long pencil.","t":"艾美的鉛筆盒裡有什麼？ — 她有一支長鉛筆。"},{"w":"eraser","p":"n.","d":"","c":"橡皮擦","s":"Q: What does Tom have in his pencil case? — A: He has a small eraser. It looks like a car.","t":"湯姆的鉛筆盒裡有什麼？ — 他有一個小橡皮擦，它看起來像一輛車。"},{"w":"ruler (rulers)","p":"n.","d":"","c":"尺","s":"Q: What do Ben and Lisa have in their pencil cases? — A: They have rulers. They can draw straight lines.","t":"班和麗莎的鉛筆盒裡有什麼？ — 他們有尺，他們可以畫直線。"},{"w":"glue","p":"n.","d":"","c":"膠水","s":"Q: Do you have any glue in your pencil case? — A: Yes, I do. Here you are.","t":"你的鉛筆盒裡有膠水嗎？ — 有，給你。"},{"w":"marker","p":"n.","d":"","c":"麥克筆；簽字筆","s":"Q: Does Lisa have a marker in her pencil case? — A: No, she doesn't. Ask Ben.","t":"麗莎的鉛筆盒裡有麥克筆嗎？ — 不，她沒有。問班吧。"},{"w":"elementary school","p":"n.","d":"","c":"小學","s":"Q: What school does your little sister go to? — A: She goes to Da-an elementary school.","t":"你妹妹讀哪一所學校？ — 她讀大安國小。"},{"w":"junior high school","p":"n.","d":"","c":"國中","s":"Q: What school do you go to? — A: I go to Ren-ai junior high school.","t":"你讀哪一所學校？ — 我讀仁愛國中。"},{"w":"senior high school","p":"n.","d":"","c":"高中","s":"Q: Where does your brother study? — A: He studies at a senior high school in Taipei.","t":"你哥哥在哪裡讀書？ — 他在臺北的一所高中讀書。"},{"w":"school","p":"n.","d":"","c":"學校","s":"Q: Where do you and your sister go in the morning? — A: We go to school.","t":"你和你妹妹早上去哪裡？ — 我們去上學。"},{"w":"classroom","p":"n.","d":"","c":"教室","s":"Q: Where are the students? — A: They're in the classroom. They're having English class.","t":"學生們在哪裡？ — 他們在教室裡，他們正在上英文課。"},{"w":"gym","p":"n.","d":"","c":"體育館","s":"Q: Where do you play basketball on rainy days? — A: We play in the gym.","t":"下雨天你們在哪裡打籃球？ — 我們在體育館打。"},{"w":"playground","p":"n.","d":"","c":"操場","s":"Q: Where does Ben run after school? — A: He runs on the playground.","t":"班放學後在哪裡跑步？ — 他在操場上跑步。"},{"w":"library","p":"n.","d":"","c":"圖書館","s":"Q: Where does Amy read books? — A: She reads books in the library. It's quiet there.","t":"艾美在哪裡看書？ — 她在圖書館看書，那裡很安靜。"},{"w":"seesaw","p":"n.","d":"","c":"蹺蹺板","s":"Q: What do the two kids play on the playground? — A: They play on the seesaw.","t":"那兩個孩子在操場上玩什麼？ — 他們玩蹺蹺板。"},{"w":"slide","p":"n.","d":"","c":"溜滑梯","s":"Q: Where is your little brother? — A: He's on the slide. He's going down fast!","t":"你弟弟在哪裡？ — 他在溜滑梯上，他正快速滑下來！"},{"w":"teacher","p":"n.","d":"","c":"老師","s":"Q: What does Mr. Lee do? — A: He is an English teacher. He works at our school.","t":"李先生是做什麼的？ — 他是英文老師，他在我們學校工作。"},{"w":"student (students)","p":"n.","d":"","c":"學生","s":"Q: What do Amy and Ben do? — A: They are students. They go to Ren-ai Junior High School.","t":"艾美和班是做什麼的？ — 他們是學生，他們讀仁愛國中。"},{"w":"classmate","p":"n.","d":"","c":"同學","s":"Q: Who is that boy? — A: He's my classmate. We sit next to each other.","t":"那個男孩是誰？ — 他是我的同學，我們坐在彼此旁邊。"},{"w":"friend","p":"n.","d":"","c":"朋友","s":"Q: Who do you play with after school? — A: I play with my best friend, Tina.","t":"你放學後和誰一起玩？ — 我和我最好的朋友蒂娜一起玩。"},{"w":"class","p":"n.","d":"","c":"班級","s":"Q: Is Amy in your class? — A: Yes. We are in the same class.","t":"艾美和你同班嗎？ — 是的，我們在同一班。"},{"w":"teach (teaches)","p":"v.","d":"","c":"教","s":"Q: What does Ms. Wang do? — A: She teaches math.","t":"王老師是做什麼的？ — 她教數學。"},{"w":"learn","p":"v.","d":"","c":"學習","s":"Q: What do you learn in English class? — A: We learn new words and songs.","t":"你們在英文課學什麼？ — 我們學新單字和歌曲。"},{"w":"study (studies)","p":"v.","d":"","c":"讀書；學習","s":"Q: When does Ben study? — A: He studies after dinner every day.","t":"班什麼時候讀書？ — 他每天晚餐後讀書。"},{"w":"explain","p":"v.","d":"","c":"解釋","s":"Q: Does your teacher explain new words in English? — A: Yes, she does. She speaks slowly.","t":"你的老師用英文解釋新單字嗎？ — 是的，她會。她說得很慢。"},{"w":"ask","p":"v.","d":"","c":"問","s":"Q: What do you do when you don't know the answer? — A: I ask my teacher.","t":"當你不知道答案時，你會怎麼做？ — 我會問我的老師。"},{"w":"understand","p":"v.","d":"","c":"了解；懂","s":"Q: Do you understand this sentence? — A: No, I don't. Can you help me?","t":"你懂這個句子嗎？ — 不，我不懂。你可以幫我嗎？"},{"w":"practice (practices)","p":"v.","d":"","c":"練習","s":"Q: What does Lisa do after school? — A: She practices the piano for an hour.","t":"麗莎放學後做什麼？ — 她練習彈鋼琴一個小時。"},{"w":"speak","p":"v.","d":"","c":"說（語言）","s":"Q: Do your parents speak English at home? — A: No, they don't.","t":"你的爸媽在家說英文嗎？ — 不，他們不說。"},{"w":"mark (marks)","p":"v.","d":"","c":"打分數；做記號","s":"Q: What does the teacher do after the test? — A: She marks our tests.","t":"考試後老師做什麼？ — 她批改我們的考卷。"},{"w":"pass","p":"v.","d":"","c":"通過；及格","s":"Q: Does Tom always pass his math tests? — A: Yes, he does. He studies hard.","t":"湯姆數學考試總是及格嗎？ — 是的，他總是及格。他很用功。"},{"w":"fail","p":"v.","d":"","c":"不及格；失敗","s":"Q: Why does Amy study so hard? — A: She doesn't want to fail the English test.","t":"艾美為什麼這麼用功？ — 她不想英文考試不及格。"},{"w":"prepare","p":"v.","d":"","c":"準備","s":"Q: What do you do before a test? — A: I prepare for it. I read my notes again.","t":"考試前你做什麼？ — 我會準備，我會再讀一次筆記。"},{"w":"homework","p":"n.","d":"","c":"功課；作業","s":"Q: Do you have any homework today? — A: Yes, I do. I have a lot.","t":"你今天有功課嗎？ — 有，我有很多。"},{"w":"test","p":"n.","d":"","c":"考試","s":"Q: Does Ben have a math test tomorrow? — A: Yes, he does. He is studying now.","t":"班明天有數學考試嗎？ — 是的，他有。他現在正在讀書。"},{"w":"quiz","p":"n.","d":"","c":"小考","s":"Q: Do we have an English quiz today? — A: No, we don't. It's on Friday.","t":"我們今天有英文小考嗎？ — 不，沒有。在星期五。"},{"w":"grade (grades)","p":"n.","d":"","c":"成績；年級","s":"Q: Does Lisa get good grades? — A: Yes, she does. She is a smart girl.","t":"麗莎的成績好嗎？ — 是的，很好。她是個聰明的女孩。"},{"w":"question (questions)","p":"n.","d":"","c":"問題；疑問","s":"Q: Do you have any questions? — A: Yes. How do you say \"cat\" in Chinese?","t":"你們有任何問題嗎？ — 有。「cat」的中文怎麼說？"},{"w":"problem","p":"n.","d":"","c":"（須解決的）問題","s":"Q: Does Tom have a problem with his homework? — A: Yes, he does. Let's help him.","t":"湯姆的功課有問題嗎？ — 是的，他有。我們來幫他吧。"},{"w":"example","p":"n.","d":"","c":"例子","s":"Q: Does the teacher have an example for this word? — A: Yes, she does. She writes it on the blackboard.","t":"老師有這個字的例子嗎？ — 是的，她有。她把它寫在黑板上。"},{"w":"exercise (exercises)","p":"n.","d":"","c":"練習；習題","s":"Q: Do we have any exercises in the workbook today? — A: Yes, we do. Please do them on page 12.","t":"我們今天作業本有習題嗎？ — 有，請做第 12 頁的。"},{"w":"knowledge","p":"n.","d":"","c":"知識","s":"Q: Does your grandpa have a lot of knowledge? — A: Yes, he does. He reads many books.","t":"你爺爺很有知識嗎？ — 是的，他很有學問。他讀很多書。"},{"w":"story","p":"n.","d":"","c":"故事","s":"Q: Does Grandma have a good story for us? — A: Yes, she does. It's about a little bear.","t":"奶奶有好故事要講給我們聽嗎？ — 是的，她有。是關於一隻小熊的。"},{"w":"envelope","p":"n.","d":"","c":"信封","s":"Q: Do you have an envelope? — A: Yes, I do. Here you are.","t":"你有信封嗎？ — 有，給你。"},{"w":"letter","p":"n.","d":"","c":"信","s":"Q: Does Amy have a letter for me? — A: Yes, she does. It's from your pen pal.","t":"艾美有給我的信嗎？ — 是的，她有。是你筆友寄來的。"},{"w":"postcard","p":"n.","d":"","c":"明信片","s":"Q: Do you have a postcard from Japan? — A: Yes, I do. My aunt sends it to me.","t":"你有從日本寄來的明信片嗎？ — 有，我阿姨寄給我的。"},{"w":"glasses","p":"n.","d":"","c":"眼鏡","s":"Q: Does your teacher wear glasses? — A: Yes, she does. She can't see well without them.","t":"你的老師戴眼鏡嗎？ — 是的，她戴。沒有眼鏡她看不清楚。"},{"w":"present","p":"n.","d":"","c":"禮物","s":"Q: Do you have a birthday present for Ben? — A: Yes, I do. It's a new ball.","t":"你有給班的生日禮物嗎？ — 有，是一顆新球。"}]},{"unit":17,"theme":"Places & Locations 地點與位置（第17區）","cards":[{"w":"beach","p":"n.","d":"","c":"海灘","s":"Q: Where are you going this Sunday? — A: I'm going to the beach. I want to swim in the sea.","t":"你這個星期日要去哪裡？ — 我要去海灘，我想在海裡游泳。"},{"w":"pool","p":"n.","d":"","c":"游泳池","s":"Q: Where is Tom going? — A: He's going to the swimming pool. He has a swimming class.","t":"湯姆要去哪裡？ — 他要去游泳池，他有游泳課。"},{"w":"park","p":"n.","d":"","c":"公園","s":"Q: Where are Amy and Lisa going? — A: They're going to the park. They want to fly kites.","t":"艾美和麗莎要去哪裡？ — 她們要去公園，她們想放風箏。"},{"w":"zoo","p":"n.","d":"","c":"動物園","s":"Q: Where is your class going tomorrow? — A: We're going to the zoo to see lions and monkeys.","t":"你們班明天要去哪裡？ — 我們要去動物園看獅子和猴子。"},{"w":"museum","p":"n.","d":"","c":"博物館","s":"Q: Where is Ben going? — A: He's going to the museum with his dad. They want to see old things.","t":"班要去哪裡？ — 他要和爸爸去博物館，他們想看古老的東西。"},{"w":"theater","p":"n.","d":"","c":"戲院","s":"Q: Where are you and your sister going tonight? — A: We're going to the theater to see a movie.","t":"你和你妹妹今晚要去哪裡？ — 我們要去戲院看電影。"},{"w":"here","p":"adv.","d":"","c":"這裡","s":"Q: Where is my pencil case? — A: It's here, on your desk.","t":"我的鉛筆盒在哪裡？ — 它在這裡，在你的書桌上。"},{"w":"there","p":"adv.","d":"","c":"那裡","s":"Q: Where is the bus stop? — A: It's over there, next to the big tree.","t":"公車站在哪裡？ — 在那裡，在那棵大樹旁邊。"},{"w":"front","p":"n.","d":"","c":"前面","s":"Q: Where is Tom's bike? — A: It's in front of the school gate.","t":"湯姆的腳踏車在哪裡？ — 在校門前面。"},{"w":"back","p":"n.","d":"","c":"後面","s":"Q: Where is Amy? — A: She's in the back of the classroom. She sits in the last row.","t":"艾美在哪裡？ — 她在教室後面，她坐在最後一排。"},{"w":"middle","p":"n.","d":"","c":"中間","s":"Q: Where is the big tree? — A: It's in the middle of the park.","t":"那棵大樹在哪裡？ — 它在公園的中間。"},{"w":"top","p":"n.","d":"","c":"頂端","s":"Q: Where is the cat? — A: It's at the top of the stairs.","t":"貓在哪裡？ — 牠在樓梯的最上面。"},{"w":"restroom","p":"n.","d":"","c":"洗手間","s":"Q: Excuse me. Where is the restroom? — A: It's between the classroom and the library.","t":"不好意思，洗手間在哪裡？ — 在教室和圖書館之間。"},{"w":"bank","p":"n.","d":"","c":"銀行","s":"Q: Where is the bank? — A: It's across from the park.","t":"銀行在哪裡？ — 在公園對面。"},{"w":"post office","p":"n.","d":"","c":"郵局","s":"Q: Where is the post office? — A: It's next to the bank.","t":"郵局在哪裡？ — 在銀行旁邊。"},{"w":"left","p":"n.","d":"","c":"左邊","s":"Q: How do I get to the library? — A: Go straight and turn left at the corner.","t":"我要怎麼去圖書館？ — 直走，然後在轉角左轉。"},{"w":"right","p":"n.","d":"","c":"右邊","s":"Q: How do I get to the train station? — A: Go straight for two blocks. It's on your right.","t":"我要怎麼去火車站？ — 直走兩個街區，它在你的右邊。"},{"w":"hospital","p":"n.","d":"","c":"醫院","s":"Q: Excuse me. How do I get to the hospital? — A: Go straight and turn left. It's on your right.","t":"不好意思，我要怎麼去醫院？ — 直走然後左轉，它在你的右邊。"},{"w":"hotel","p":"n.","d":"","c":"旅館","s":"Q: How do we get to the Sun hotel? — A: Turn right at the bank. It's next to the park.","t":"我們要怎麼去太陽旅館？ — 在銀行右轉，它在公園旁邊。"},{"w":"bookstore","p":"n.","d":"","c":"書店","s":"Q: How does Ben get to the bookstore? — A: He walks along Main Street and turns left.","t":"班怎麼去書店？ — 他沿著緬恩街走，然後左轉。"},{"w":"department store","p":"n.","d":"","c":"百貨公司","s":"Q: How do I get to the department store? — A: Take the MRT. It's across from the station.","t":"我要怎麼去百貨公司？ — 搭捷運，它在車站對面。"},{"w":"supermarket","p":"n.","d":"","c":"超級市場","s":"Q: How does your mom get to the supermarket? — A: She rides her scooter. It isn't far.","t":"你媽媽怎麼去超市？ — 她騎機車去，不遠。"},{"w":"bakery","p":"n.","d":"","c":"麵包店","s":"Q: What does Mr. Chen do at the bakery? — A: He makes bread and cakes.","t":"陳先生在麵包店做什麼？ — 他做麵包和蛋糕。"},{"w":"market","p":"n.","d":"","c":"市場","s":"Q: What do people do at the market? — A: They buy fruit, meat, and vegetables.","t":"人們在市場做什麼？ — 他們買水果、肉和蔬菜。"},{"w":"shop","p":"n.","d":"","c":"商店","s":"Q: What does Amy do at the shop on the corner? — A: She buys pencils and notebooks there.","t":"艾美在轉角的那家店做什麼？ — 她在那裡買鉛筆和筆記本。"},{"w":"store","p":"n.","d":"","c":"商店","s":"Q: What do you do at the store near your home? — A: I buy milk and bread.","t":"你在家附近的商店做什麼？ — 我買牛奶和麵包。"},{"w":"church","p":"n.","d":"","c":"教堂","s":"Q: What does Lisa do at church on Sundays? — A: She sings songs with her family.","t":"麗莎星期日在教堂做什麼？ — 她和家人一起唱歌。"},{"w":"temple","p":"n.","d":"","c":"寺廟","s":"Q: What do people do at the temple? — A: They pray and ask for good luck.","t":"人們在寺廟做什麼？ — 他們拜拜，祈求好運。"},{"w":"factory","p":"n.","d":"","c":"工廠","s":"Q: What does your uncle do at the factory? — A: He makes shoes.","t":"你叔叔在工廠做什麼？ — 他做鞋子。"},{"w":"office","p":"n.","d":"","c":"辦公室","s":"Q: What do your parents do in the office? — A: They work on computers and answer the phone.","t":"你爸媽在辦公室做什麼？ — 他們用電腦工作、接電話。"},{"w":"farm","p":"n.","d":"","c":"農場","s":"Q: What does Grandpa do on the farm? — A: He grows rice and vegetables.","t":"爺爺在農場做什麼？ — 他種稻米和蔬菜。"},{"w":"city","p":"n.","d":"","c":"城市","s":"Q: Where do you live? — A: I live in a big city. It's Taipei.","t":"你住在哪裡？ — 我住在一個大城市，是臺北。"},{"w":"town","p":"n.","d":"","c":"城鎮","s":"Q: Where does your grandma live? — A: She lives in a small town near the sea.","t":"你奶奶住在哪裡？ — 她住在海邊附近的一個小鎮。"},{"w":"country","p":"n.","d":"","c":"鄉村","s":"Q: Where do Tom's grandparents live? — A: They live in the country. There are many farms there.","t":"湯姆的爺爺奶奶住在哪裡？ — 他們住在鄉下，那裡有很多農場。"},{"w":"place","p":"n.","d":"","c":"地方","s":"Q: What place does Ben want to visit this summer? — A: He wants to visit Hualien.","t":"班今年夏天想去哪個地方？ — 他想去花蓮。"},{"w":"north","p":"n.","d":"","c":"北方","s":"Q: Where does Amy live? — A: She lives in Taipei, in the north of Taiwan.","t":"艾美住在哪裡？ — 她住在臺北，在臺灣北部。"},{"w":"south","p":"n.","d":"","c":"南方","s":"Q: Where do your cousins live? — A: They live in Kaohsiung, in the south of Taiwan.","t":"你的堂表兄弟姊妹住在哪裡？ — 他們住在高雄，在臺灣南部。"},{"w":"east","p":"n.","d":"","c":"東方","s":"Q: Where does the sun come up? — A: It comes up in the east.","t":"太陽從哪裡升起？ — 它從東方升起。"},{"w":"west","p":"n.","d":"","c":"西方","s":"Q: Where does Mr. Lee live? — A: He lives in Changhua, in the west of Taiwan.","t":"李先生住在哪裡？ — 他住在彰化，在臺灣西部。"}]},{"unit":18,"theme":"Transportation 交通（第18區）","cards":[{"w":"bicycle (bike)","p":"n.","d":"","c":"腳踏車","s":"Q: How does Amy go to school? — A: She goes to school by bicycle.","t":"艾美怎麼上學？ — 她騎腳踏車上學。"},{"w":"ride","p":"v.","d":"","c":"騎","s":"Q: How do you go to the park? — A: I ride my bike there.","t":"你怎麼去公園？ — 我騎腳踏車去那裡。"},{"w":"scooter","p":"n.","d":"","c":"小型機車","s":"Q: How does your mom go to the market? — A: She rides her scooter there.","t":"你媽媽怎麼去市場？ — 她騎她的機車去那裡。"},{"w":"motorcycle","p":"n.","d":"","c":"機車","s":"Q: How do your brothers go to work? — A: They go to work by motorcycle.","t":"你哥哥們怎麼去上班？ — 他們騎機車去上班。"},{"w":"car","p":"n.","d":"","c":"車子","s":"Q: How does your dad go to work? — A: He goes to work by car.","t":"你爸爸怎麼去上班？ — 他開車去上班。"},{"w":"drive","p":"v.","d":"","c":"駕駛；開車","s":"Q: How do your parents go to the beach? — A: They drive there in their new car.","t":"你爸媽怎麼去海灘？ — 他們開新車去那裡。"},{"w":"bus","p":"n.","d":"","c":"公車","s":"Q: How do you go to school? — A: I go to school by bus.","t":"你怎麼上學？ — 我搭公車上學。"},{"w":"taxi","p":"n.","d":"","c":"計程車","s":"Q: How does Mr. Lee go to the hotel? — A: He takes a taxi.","t":"李先生怎麼去旅館？ — 他搭計程車。"},{"w":"train","p":"n.","d":"","c":"火車","s":"Q: How do Ben and his sister go to Tainan? — A: They go there by train.","t":"班和他妹妹怎麼去臺南？ — 他們搭火車去那裡。"},{"w":"take the MRT","p":"phr.","d":"","c":"搭捷運","s":"Q: How do you and Tom go to the zoo? — A: We take the MRT there.","t":"你和湯姆怎麼去動物園？ — 我們搭捷運去那裡。"},{"w":"fast","p":"adj.","d":"","c":"快的","s":"Q: Do you go to school by MRT? — A: Yes, I do. The MRT is very fast.","t":"你搭捷運上學嗎？ — 是的，我搭捷運。捷運很快。"},{"w":"quick","p":"adj.","d":"","c":"迅速的","s":"Q: Does your dad take a taxi to work? — A: Yes, he does. It's a quick way to get there.","t":"你爸爸搭計程車上班嗎？ — 是的，他搭計程車。那是到那裡的快速方法。"},{"w":"slow","p":"adj.","d":"","c":"慢的","s":"Q: Does Lisa go to school by bus? — A: No, she doesn't. The bus is too slow. She rides her bike.","t":"麗莎搭公車上學嗎？ — 不，她沒有。公車太慢了，她騎腳踏車。"},{"w":"airplane (plane)","p":"n.","d":"","c":"飛機","s":"Q: How long does it take to go to Japan by airplane? — A: It takes about three hours.","t":"搭飛機去日本要多久？ — 大約要三個小時。"},{"w":"fly","p":"v.","d":"","c":"飛","s":"Q: How long does it take to fly to Hong Kong? — A: It takes about two hours.","t":"飛到香港要多久？ — 大約要兩個小時。"},{"w":"boat","p":"n.","d":"","c":"船","s":"Q: How long does it take to go to the island by boat? — A: It takes about thirty minutes.","t":"搭船去那座島要多久？ — 大約要三十分鐘。"},{"w":"ship","p":"n.","d":"","c":"船","s":"Q: How long does it take to go to Penghu? — A: It takes about four hours by ship.","t":"去澎湖要多久？ — 搭船大約要四個小時。"},{"w":"sail","p":"v.","d":"","c":"航行","s":"Q: How long do your uncle and his friends stay on the boat? — A: They sail on the sea for two hours.","t":"你叔叔和他的朋友們在船上待多久？ — 他們在海上航行兩個小時。"},{"w":"arrive","p":"v.","d":"","c":"到達","s":"Q: When do we arrive at the station? — A: In ten minutes. It takes ten minutes from here.","t":"我們什麼時候到達車站？ — 十分鐘後，從這裡過去要十分鐘。"},{"w":"traffic","p":"n.","d":"","c":"交通","s":"Q: How long does it take to go to school by car? — A: About forty minutes. There is a lot of traffic in the morning.","t":"開車上學要多久？ — 大約四十分鐘，早上車很多。"},{"w":"turn","p":"v.","d":"","c":"轉彎","s":"Q: How do I get to the bank? — A: Go straight and turn left at the corner.","t":"我要怎麼去銀行？ — 直走，然後在轉角左轉。"},{"w":"block (blocks)","p":"n.","d":"","c":"街區","s":"Q: How do I get to the post office? — A: Go straight for two blocks. It's on your right.","t":"我要怎麼去郵局？ — 直走兩個街區，它在你的右邊。"},{"w":"cross (crosses)","p":"v.","d":"","c":"越過","s":"Q: How does Amy get to the park? — A: She crosses the street at the traffic light.","t":"艾美怎麼去公園？ — 她在紅綠燈處過馬路。"},{"w":"bridge","p":"n.","d":"","c":"橋","s":"Q: How do we get to the museum? — A: Walk across the bridge. The museum is next to the river.","t":"我們要怎麼去博物館？ — 走過那座橋，博物館就在河邊。"},{"w":"sidewalk","p":"n.","d":"","c":"人行道","s":"Q: How does Ben get to school safely? — A: He walks on the sidewalk, not on the road.","t":"班怎麼安全地走到學校？ — 他走在人行道上，不走在馬路上。"},{"w":"airport","p":"n.","d":"","c":"機場","s":"Q: Where do we take the plane to Japan? — A: We take it at the airport in Taoyuan.","t":"我們在哪裡搭去日本的飛機？ — 我們在桃園的機場搭。"},{"w":"land (lands)","p":"v.","d":"","c":"降落","s":"Q: Where does the plane from Tokyo stop? — A: It lands at the airport in Taoyuan.","t":"從東京來的飛機停在哪裡？ — 它降落在桃園的機場。"},{"w":"station","p":"n.","d":"","c":"車站","s":"Q: Where does Tom take the train? — A: He takes it at the train station.","t":"湯姆在哪裡搭火車？ — 他在火車站搭車。"},{"w":"truck","p":"n.","d":"","c":"卡車","s":"Q: What do the workers drive? — A: They drive a big truck. It carries many boxes.","t":"那些工人開什麼車？ — 他們開一輛大卡車，它載著很多箱子。"}]},{"unit":19,"theme":"Sizes & Measurements 尺寸與度量（第19區）","cards":[{"w":"height","p":"n.","d":"","c":"身高；高度","s":"Q: What's your height? — A: I'm 150 cm tall.","t":"你的身高是多少？ — 我身高一百五十公分。"},{"w":"centimeter (centimeters)","p":"n.","d":"","c":"公分","s":"Q: How tall is your brother? — A: He is 170 centimeters tall.","t":"你哥哥多高？ — 他一百七十公分高。"},{"w":"foot (feet)","p":"n.","d":"","c":"呎","s":"Q: How long is the snake? — A: It's about six feet long.","t":"那條蛇多長？ — 牠大約六呎長。"},{"w":"inch (inches)","p":"n.","d":"","c":"英吋","s":"Q: How long is your ruler? — A: It's twelve inches long. That's one foot.","t":"你的尺多長？ — 它十二英吋長，也就是一呎。"},{"w":"yard (yards)","p":"n.","d":"","c":"碼","s":"Q: How far do you walk to the store? — A: I walk about 100 yards. It's very near.","t":"你走多遠到商店？ — 我走大約一百碼，很近。"},{"w":"mile (miles)","p":"n.","d":"","c":"英里；哩","s":"Q: How far does your uncle run every morning? — A: He runs three miles.","t":"你叔叔每天早上跑多遠？ — 他跑三英里。"},{"w":"far","p":"adj.","d":"","c":"遠的","s":"Q: Does Ben live far from school? — A: Yes, he does. He lives five miles from school, so he goes by bus.","t":"班住得離學校遠嗎？ — 是的，他住得遠。他住在離學校五英里的地方，所以他搭公車。"},{"w":"high","p":"adj.","d":"","c":"高的","s":"Q: How high is Taipei 101? — A: It's about 1,670 feet.","t":"臺北101有多高？ — 它大約一千六百七十呎。"},{"w":"deep","p":"adj.","d":"","c":"深的","s":"Q: How deep is the pool? — A: It's about five feet. Don't swim there alone.","t":"這座游泳池有多深？ — 大約五呎深，不要獨自在那裡游泳。"},{"w":"wide","p":"adj.","d":"","c":"寬的","s":"Q: How wide is the road? — A: It's about twenty feet.","t":"這條路有多寬？ — 它大約二十呎寬。"},{"w":"gram (grams)","p":"n.","d":"","c":"公克","s":"Q: How much sugar do you need for the cake? — A: I need 200 grams of sugar.","t":"做蛋糕你需要多少糖？ — 我需要兩百公克的糖。"},{"w":"kilogram (kilograms)","p":"n.","d":"","c":"公斤","s":"Q: How much does your dog weigh? — A: It weighs ten kilograms.","t":"你的狗多重？ — 牠十公斤重。"},{"w":"pound (pounds)","p":"n.","d":"","c":"磅","s":"Q: How much does the baby weigh? — A: She weighs seven pounds.","t":"那個寶寶多重？ — 她七磅重。"},{"w":"shape","p":"n.","d":"","c":"形狀","s":"Q: What shape do you like? — A: I like stars and hearts.","t":"你喜歡什麼形狀？ — 我喜歡星形和心形。"},{"w":"round","p":"adj.","d":"","c":"圓形的","s":"Q: What shape is the moon tonight? — A: It's round and bright.","t":"今晚的月亮是什麼形狀？ — 它又圓又亮。"},{"w":"circle","p":"n.","d":"","c":"圓圈","s":"Q: What does the teacher draw on the blackboard? — A: She draws a big circle.","t":"老師在黑板上畫什麼？ — 她畫一個大圓圈。"},{"w":"square","p":"adj.","d":"","c":"正方形的","s":"Q: What shape is the gift box? — A: It's square. It has four sides.","t":"那個禮物盒是什麼形狀？ — 它是正方形的，有四個邊。"},{"w":"angle (angles)","p":"n.","d":"","c":"角；邊角","s":"Q: How many angles does a square have? — A: It has four.","t":"一個正方形有幾個角？ — 它有四個。"},{"w":"line","p":"n.","d":"","c":"線；行列","s":"Q: What do the students stand in at lunch time? — A: They stand in a line.","t":"學生們午餐時間站成什麼？ — 他們排成一列（排隊）。"},{"w":"straight","p":"adj.","d":"","c":"直的","s":"Q: What does Amy draw with her ruler? — A: She draws a straight line.","t":"艾美用尺畫什麼？ — 她畫一條直線。"},{"w":"dot (dots)","p":"n.","d":"","c":"點","s":"Q: What do your new socks look like? — A: They're white with red dots.","t":"你的新襪子看起來怎麼樣？ — 它們是白色的，有紅色的點點。"},{"w":"point (points)","p":"n.","d":"","c":"分數；得分","s":"Q: How many points does your team get? — A: We get twenty-five. We win the game!","t":"你們隊得幾分？ — 我們得二十五分，我們贏了比賽！"},{"w":"row","p":"n.","d":"","c":"一排","s":"Q: Where do you sit in class? — A: I sit in the first row.","t":"你上課坐在哪裡？ — 我坐在第一排。"},{"w":"size","p":"n.","d":"","c":"尺寸","s":"Q: What size do you wear? — A: I wear S. I'm not very tall.","t":"你穿什麼尺寸？ — 我穿 S 號，我不是很高。"},{"w":"medium","p":"adj.","d":"","c":"中等的","s":"Q: What size do you and your brother wear? — A: We wear medium.","t":"你和你弟弟穿什麼尺寸？ — 我們穿中號。"},{"w":"large","p":"adj.","d":"","c":"大的","s":"Q: What size Coke does Tom want? — A: He wants a large Coke.","t":"湯姆想要什麼尺寸的可樂？ — 他想要一杯大杯可樂。"},{"w":"bottle","p":"n.","d":"","c":"瓶子","s":"Q: How much water do you want? — A: I want a bottle of water, please.","t":"你想要多少水？ — 我想要一瓶水，謝謝。"},{"w":"cup","p":"n.","d":"","c":"茶杯；一杯","s":"Q: What does Grandpa drink every morning? — A: He drinks a cup of hot tea.","t":"爺爺每天早上喝什麼？ — 他喝一杯熱茶。"},{"w":"glass (glasses)","p":"n.","d":"","c":"玻璃杯；一杯","s":"Q: How much milk does Amy drink every day? — A: She drinks two glasses of milk.","t":"艾美每天喝多少牛奶？ — 她喝兩杯牛奶。"},{"w":"piece","p":"n.","d":"","c":"片；塊","s":"Q: How much cake do you want? — A: I want a piece of cake.","t":"你想要多少蛋糕？ — 我想要一塊蛋糕。"},{"w":"pack","p":"n.","d":"","c":"包","s":"Q: What do the kids buy at the store? — A: They buy a pack of cookies.","t":"孩子們在商店買什麼？ — 他們買一包餅乾。"},{"w":"package","p":"n.","d":"","c":"包裹","s":"Q: What does Mom get from Grandma today? — A: She gets a big package. There are cookies in it.","t":"媽媽今天收到奶奶寄來的什麼？ — 她收到一個大包裹，裡面有餅乾。"},{"w":"pair","p":"n.","d":"","c":"一雙；一對","s":"Q: What does Ben need for PE class? — A: He needs a new pair of shoes.","t":"班上體育課需要什麼？ — 他需要一雙新鞋子。"},{"w":"dozen","p":"n.","d":"","c":"（一）打","s":"Q: How many eggs do we need for the cake? — A: We need a dozen eggs.","t":"做蛋糕我們需要幾顆蛋？ — 我們需要一打蛋。"},{"w":"kilo (kilos)","p":"n.","d":"","c":"公斤（簡稱）","s":"Q: How much rice do your parents buy? — A: They buy two kilos of rice.","t":"你爸媽買多少米？ — 他們買兩公斤的米。"},{"w":"big (bigger)","p":"adj.","d":"","c":"大的","s":"Q: Is an elephant small? — A: No, it isn't. It's much bigger than a horse.","t":"大象很小嗎？ — 不，牠不小。牠比馬大得多。"},{"w":"small (smaller)","p":"adj.","d":"","c":"小的","s":"Q: Is a mouse big? — A: No, it isn't. It's smaller than a cat.","t":"老鼠很大嗎？ — 不，牠不大。牠比貓小。"},{"w":"little","p":"adj.","d":"","c":"小的","s":"Q: Do you have a big dog? — A: No, I don't. I have a little dog. It's very cute.","t":"你有一隻大狗嗎？ — 不，我沒有。我有一隻小狗，牠很可愛。"},{"w":"long (longer)","p":"adj.","d":"","c":"長的","s":"Q: Does Amy have short hair? — A: No, she doesn't. Her hair is longer than mine.","t":"艾美是短頭髮嗎？ — 不，她不是。她的頭髮比我的長。"},{"w":"short (shorter)","p":"adj.","d":"","c":"短的","s":"Q: Is your pencil long? — A: No, it isn't. It's shorter than my pen.","t":"你的鉛筆很長嗎？ — 不，它不長。它比我的原子筆短。"},{"w":"low (lower)","p":"adj.","d":"","c":"低的","s":"Q: Is this chair high? — A: No, it isn't. It's lower than that table.","t":"這張椅子很高嗎？ — 不，它不高。它比那張桌子低。"},{"w":"light (lighter)","p":"adj.","d":"","c":"輕的","s":"Q: Is your schoolbag heavy? — A: No, it isn't. It's lighter than Ben's bag.","t":"你的書包很重嗎？ — 不，它不重。它比班的書包輕。"}]},{"unit":20,"theme":"Countries & Languages 國家與地區、語言（第20–21區）","cards":[{"w":"country","p":"n.","d":"","c":"國家","s":"Q: What country do you and your family come from? — A: We come from Taiwan.","t":"你和你的家人來自哪個國家？ — 我們來自臺灣。"},{"w":"Taiwan","p":"n.","d":"","c":"臺灣","s":"Q: Where are you from? — A: I'm from Taiwan. I live in Taipei.","t":"你來自哪裡？ — 我來自臺灣，我住在臺北。"},{"w":"China","p":"n.","d":"","c":"中國","s":"Q: Where does Mr. Li come from? — A: He comes from China. He lives in Beijing now.","t":"李先生來自哪裡？ — 他來自中國，他現在住在北京。"},{"w":"America","p":"n.","d":"","c":"美國","s":"Q: Where is your English teacher from? — A: She's from America. She's American.","t":"你的英文老師來自哪裡？ — 她來自美國，她是美國人。"},{"w":"world","p":"n.","d":"","c":"世界","s":"Q: Where do your pen pals live? — A: They live in different countries around the world.","t":"你的筆友們住在哪裡？ — 他們住在世界各地不同的國家。"},{"w":"U.S.A. / USA","p":"n.","d":"","c":"美國（縮寫）","s":"Q: Where does your cousin Ben live? — A: He lives in the U.S.A. He lives in New York.","t":"你的堂哥班住在哪裡？ — 他住在美國，他住在紐約。"},{"w":"R.O.C. / ROC","p":"n.","d":"","c":"中華民國","s":"Q: Does Lisa live in Japan? — A: No, she doesn't. She lives in Taiwan. Its other name is the R.O.C.","t":"莉莎住在日本嗎？ — 不，她不是。她住在臺灣，臺灣的另一個名字是中華民國。"},{"w":"Chinese","p":"n.","d":"","c":"中文","s":"Q: What language do people in Taiwan speak? — A: They speak Chinese.","t":"臺灣的人說什麼語言？ — 他們說中文。"},{"w":"English","p":"n.","d":"","c":"英語","s":"Q: What language does your English teacher speak in class? — A: She speaks English. She doesn't speak Chinese.","t":"你的英文老師上課說什麼語言？ — 她說英語，她不說中文。"}]},{"unit":21,"theme":"Holidays & Festivals 節日與慶典（第22區）","cards":[{"w":"Easter","p":"n.","d":"","c":"復活節","s":"Q: When is Easter? — A: It's in March or April. Children look for eggs on that day.","t":"復活節是什麼時候？ — 它在三月或四月，小孩們在那天找蛋。"},{"w":"festival","p":"n.","d":"","c":"節慶","s":"Q: When is the Moon festival? — A: It's in September or October. We look at the moon and eat moon cakes.","t":"中秋節是什麼時候？ — 它在九月或十月，我們賞月、吃月餅。"},{"w":"vacation","p":"n.","d":"","c":"假期","s":"Q: What do you do on summer vacation? — A: I go to the beach and swim with my family.","t":"你暑假做什麼？ — 我和家人去海邊游泳。"},{"w":"holiday (holidays)","p":"n.","d":"","c":"假日","s":"Q: What does your dad do on Sundays? — A: Sundays are holidays for him, so he doesn't work. He stays home.","t":"你爸爸星期天做什麼？ — 星期天是他的假日，所以他不工作，他待在家裡。"},{"w":"lantern (lanterns)","p":"n.","d":"","c":"燈籠","s":"Q: What do people do at the Lantern Festival? — A: They look at lanterns and eat sweet dumplings.","t":"人們在元宵節做什麼？ — 他們看燈籠、吃湯圓。"},{"w":"celebrate (celebrates)","p":"v.","d":"","c":"慶祝","s":"Q: What does Amy do on Christmas Day? — A: She celebrates it with her family. She gets many presents.","t":"艾美在聖誕節做什麼？ — 她和家人一起慶祝，她收到很多禮物。"},{"w":"Christmas","p":"n.","d":"","c":"聖誕節","s":"Q: What does Grandpa say to you on December 25th? — A: He says, \"Merry Christmas!\" Then he gives me a present.","t":"爺爺在十二月二十五日對你說什麼？ — 他說：「聖誕快樂！」然後他送我一份禮物。"},{"w":"Halloween","p":"n.","d":"","c":"萬聖節","s":"Q: It's October 31st. What do the children say at the door? — A: They say, \"Happy Halloween! Trick or treat!\"","t":"今天是十月三十一日，小孩們在門口說什麼？ — 他們說：「萬聖節快樂！不給糖就搗蛋！」"}]},{"unit":22,"theme":"Occupations 職業（第23區）","cards":[{"w":"doctor (Dr.)","p":"n.","d":"","c":"醫生","s":"Q: What does your mother do? — A: She is a doctor. She works in a hospital.","t":"你媽媽是做什麼的？ — 她是醫生，她在醫院工作。"},{"w":"nurse (nurses)","p":"n.","d":"","c":"護士","s":"Q: What do Amy's aunts do? — A: They are nurses. They help sick people.","t":"艾美的阿姨們是做什麼的？ — 她們是護士，她們幫助生病的人。"},{"w":"dentist","p":"n.","d":"","c":"牙醫","s":"Q: What does Mr. Lin do? — A: He is a dentist. He checks people's teeth.","t":"林先生是做什麼的？ — 他是牙醫，他檢查人們的牙齒。"},{"w":"housewife","p":"n.","d":"","c":"家庭主婦","s":"Q: What does Ben's mom do? — A: She is a housewife. She cooks and cleans at home.","t":"班的媽媽是做什麼的？ — 她是家庭主婦，她在家煮飯、打掃。"},{"w":"job","p":"n.","d":"","c":"工作","s":"Q: What do your parents do? — A: My dad is a teacher, and my mom has a new job at a bank.","t":"你爸媽是做什麼的？ — 我爸爸是老師，我媽媽在銀行有一份新工作。"},{"w":"business","p":"n.","d":"","c":"生意","s":"Q: What do Tom's parents do? — A: They have a small business. They sell shoes.","t":"湯姆的爸媽是做什麼的？ — 他們做小生意，他們賣鞋子。"},{"w":"businessman","p":"n.","d":"","c":"商人","s":"Q: What does Mr. Wang do? — A: He is a businessman. He often travels to other countries.","t":"王先生是做什麼的？ — 他是商人，他常常去其他國家。"},{"w":"boss","p":"n.","d":"","c":"老闆","s":"Q: What does Ms. Chen do at the store? — A: She is the boss. She tells everyone what to do.","t":"陳女士在店裡做什麼？ — 她是老闆，她告訴每個人要做什麼。"},{"w":"actor","p":"n.","d":"","c":"男演員","s":"Q: What does Tom want to be? — A: He wants to be an actor. He wants to be in movies.","t":"湯姆想當什麼？ — 他想當男演員，他想演電影。"},{"w":"actress","p":"n.","d":"","c":"女演員","s":"Q: What do you want to be, Amy? — A: I want to be an actress. I love to act on TV.","t":"艾美，你想當什麼？ — 我想當女演員，我喜歡在電視上演戲。"},{"w":"singer (singers)","p":"n.","d":"","c":"歌手","s":"Q: What do your sisters want to be? — A: They want to be singers. They sing very well.","t":"你的姊妹們想當什麼？ — 她們想當歌手，她們唱歌很好聽。"},{"w":"writer","p":"n.","d":"","c":"作家","s":"Q: What does Kevin want to be? — A: He wants to be a writer. He likes to write stories.","t":"凱文想當什麼？ — 他想當作家，他喜歡寫故事。"},{"w":"reporter","p":"n.","d":"","c":"記者","s":"Q: What do you want to be in the future? — A: I want to be a reporter. I want to report the news on TV.","t":"你將來想當什麼？ — 我想當記者，我想在電視上報新聞。"},{"w":"engineer","p":"n.","d":"","c":"工程師","s":"Q: What does your brother want to be? — A: He wants to be an engineer. He likes computers and machines.","t":"你哥哥想當什麼？ — 他想當工程師，他喜歡電腦和機器。"},{"w":"lawyer (lawyers)","p":"n.","d":"","c":"律師","s":"Q: What do Jenny and Lisa want to be? — A: They want to be lawyers like their father.","t":"珍妮和麗莎想當什麼？ — 她們想像她們的爸爸一樣當律師。"},{"w":"soldier","p":"n.","d":"","c":"軍人","s":"Q: What does Peter want to be? — A: He wants to be a soldier. He wants to keep our country safe.","t":"彼得想當什麼？ — 他想當軍人，他想保衛我們的國家安全。"},{"w":"cowboy (cowboys)","p":"n.","d":"","c":"牛仔","s":"Q: What do the boys want to be at the Halloween party? — A: They want to be cowboys. They wear big hats.","t":"男孩們在萬聖節派對上想扮成什麼？ — 他們想扮成牛仔，他們戴大帽子。"},{"w":"work (works)","p":"v.","d":"","c":"工作","s":"Q: Where does your father work? — A: He works at a bank.","t":"你爸爸在哪裡工作？ — 他在銀行工作。"},{"w":"farmer (farmers)","p":"n.","d":"","c":"農夫","s":"Q: Where do farmers work? — A: They work on farms. They grow rice and vegetables.","t":"農夫在哪裡工作？ — 他們在農場工作，他們種稻米和蔬菜。"},{"w":"fisherman","p":"n.","d":"","c":"漁夫","s":"Q: Where does a fisherman work? — A: He works on a boat at sea.","t":"漁夫在哪裡工作？ — 他在海上的船上工作。"},{"w":"cook","p":"n.","d":"","c":"廚師","s":"Q: Where does the cook work? — A: She works in the kitchen of a restaurant.","t":"那位廚師在哪裡工作？ — 她在一家餐廳的廚房工作。"},{"w":"waiter (waiters)","p":"n.","d":"","c":"男服務生","s":"Q: Where do waiters work? — A: They work in restaurants. They bring food to people.","t":"男服務生在哪裡工作？ — 他們在餐廳工作，他們幫人送餐。"},{"w":"waitress","p":"n.","d":"","c":"女服務生","s":"Q: Where does Mary's sister work? — A: She is a waitress at a coffee shop.","t":"瑪莉的姊姊在哪裡工作？ — 她在一家咖啡店當女服務生。"},{"w":"clerk (clerks)","p":"n.","d":"","c":"店員","s":"Q: Where do Ken and his friend work? — A: They are clerks at a supermarket.","t":"肯和他的朋友在哪裡工作？ — 他們在一家超市當店員。"},{"w":"secretary","p":"n.","d":"","c":"秘書","s":"Q: Where does Ms. Lee work? — A: She works in an office. She is a secretary.","t":"李女士在哪裡工作？ — 她在辦公室工作，她是秘書。"},{"w":"mailman (mail carrier)","p":"n.","d":"","c":"郵差","s":"Q: What does a mailman do? — A: He brings letters to every home.","t":"郵差做什麼？ — 他把信送到每一戶人家。"},{"w":"police","p":"n.","d":"","c":"警察","s":"Q: What do the police do? — A: They help people and keep our city safe.","t":"警察做什麼？ — 他們幫助人們，維護我們城市的安全。"},{"w":"officer","p":"n.","d":"","c":"警官；官員","s":"Q: What does a police officer do? — A: He helps people and catches bad men.","t":"警官做什麼？ — 他幫助人們、抓壞人。"},{"w":"driver (drivers)","p":"n.","d":"","c":"駕駛人；司機","s":"Q: What do bus drivers do? — A: They drive buses and take people to many places.","t":"公車司機做什麼？ — 他們開公車，載人們去很多地方。"},{"w":"salesman","p":"n.","d":"","c":"推銷員","s":"Q: What does a salesman do? — A: He sells things to people.","t":"推銷員做什麼？ — 他把東西賣給人們。"},{"w":"shopkeeper (shopkeepers)","p":"n.","d":"","c":"店主","s":"Q: What do shopkeepers do? — A: They open their stores and sell things.","t":"店主做什麼？ — 他們開店、賣東西。"},{"w":"worker (workers)","p":"n.","d":"","c":"工人","s":"Q: What do the workers do at the factory? — A: They make toys.","t":"工人們在工廠做什麼？ — 他們製作玩具。"}]},{"unit":23,"theme":"Weather & Nature 天氣與自然（第24區）","cards":[{"w":"weather","p":"n.","d":"","c":"天氣","s":"Q: How's the weather today? — A: It's nice. Let's go out and play.","t":"今天天氣如何？ — 天氣很好，我們出去玩吧。"},{"w":"sunny","p":"adj.","d":"","c":"晴朗的","s":"Q: How's the weather in Kaohsiung today? — A: It's sunny. Let's go to the beach.","t":"高雄今天天氣如何？ — 天氣晴朗，我們去海邊吧。"},{"w":"clear","p":"adj.","d":"","c":"晴朗的；清澈的","s":"Q: How's the weather this morning? — A: It's clear. We can see Taipei 101 from here.","t":"今天早上天氣如何？ — 天氣晴朗，我們從這裡就看得到台北101。"},{"w":"cloudy","p":"adj.","d":"","c":"多雲的","s":"Q: How's the weather in Taichung? — A: It's cloudy and gray.","t":"台中天氣如何？ — 多雲、灰灰的。"},{"w":"rainy","p":"adj.","d":"","c":"下雨的","s":"Q: How's the weather today, Mom? — A: It's rainy. Take your umbrella.","t":"媽，今天天氣如何？ — 在下雨，帶你的雨傘。"},{"w":"windy","p":"adj.","d":"","c":"多風的","s":"Q: How's the weather at the beach? — A: It's windy. Let's fly a kite.","t":"海邊天氣如何？ — 風很大，我們來放風箏吧。"},{"w":"snowy","p":"adj.","d":"","c":"下雪的","s":"Q: How's the weather in Japan today? — A: It's snowy. The mountains are all white.","t":"日本今天天氣如何？ — 在下雪，山都變成白色的了。"},{"w":"hot","p":"adj.","d":"","c":"熱的","s":"Q: What's the weather like in Taiwan in summer? — A: It's very hot. We often go swimming.","t":"台灣夏天的天氣怎麼樣？ — 非常熱，我們常常去游泳。"},{"w":"warm","p":"adj.","d":"","c":"溫暖的","s":"Q: What's the weather like in spring? — A: It's warm. Many flowers come out.","t":"春天的天氣怎麼樣？ — 很溫暖，很多花都開了。"},{"w":"cool","p":"adj.","d":"","c":"涼爽的","s":"Q: What's the weather like in fall? — A: It's cool. It's a good time for hiking.","t":"秋天的天氣怎麼樣？ — 很涼爽，是健行的好時節。"},{"w":"cold","p":"adj.","d":"","c":"寒冷的","s":"Q: What's the weather like here in winter? — A: It's cold. Wear your coat.","t":"這裡冬天的天氣怎麼樣？ — 很冷，穿上你的大衣。"},{"w":"dry","p":"adj.","d":"","c":"乾的；乾燥的","s":"Q: What's the weather like in Tainan in fall? — A: It's dry. There isn't much water in the river.","t":"台南秋天的天氣怎麼樣？ — 很乾燥，河裡沒什麼水。"},{"w":"wet","p":"adj.","d":"","c":"濕的","s":"Q: What's the weather like in Keelung in winter? — A: It's very wet. People always carry umbrellas.","t":"基隆冬天的天氣怎麼樣？ — 很潮濕，人們總是帶著雨傘。"},{"w":"rain","p":"v.","d":"","c":"下雨","s":"Q: Does it often rain in Keelung? — A: Yes, it does. Take an umbrella with you.","t":"基隆常常下雨嗎？ — 是的，常常下。帶把傘吧。"},{"w":"shower","p":"n.","d":"","c":"陣雨；淋浴","s":"Q: Is it going to rain today? — A: Yes, it is. There's going to be a shower this afternoon.","t":"今天會下雨嗎？ — 會，今天下午會有一場陣雨。"},{"w":"cloud (clouds)","p":"n.","d":"","c":"雲","s":"Q: Is it going to rain? — A: Maybe. Look at those dark clouds.","t":"會下雨嗎？ — 也許會，看那些烏雲。"},{"w":"rainbow","p":"n.","d":"","c":"彩虹","s":"Q: Is it going to rain again? — A: No, it isn't. Look! There is a rainbow over the mountain.","t":"又要下雨了嗎？ — 不會。看！山上有一道彩虹。"},{"w":"snow","p":"v.","d":"","c":"下雪","s":"Q: Does it snow in Taipei in winter? — A: No, it doesn't. But it sometimes does on high mountains.","t":"台北冬天會下雪嗎？ — 不會，但是高山上有時候會。"},{"w":"wind","p":"n.","d":"","c":"風","s":"Q: Do we need to close the windows? — A: Yes, we do. The wind is very strong.","t":"我們需要關窗戶嗎？ — 需要，風很強。"},{"w":"blow","p":"v.","d":"","c":"吹","s":"Q: Does the wind blow hard here in winter? — A: Yes, it does. Wear your coat.","t":"這裡冬天風吹得很強嗎？ — 是的，穿上你的大衣。"},{"w":"typhoon","p":"n.","d":"","c":"颱風","s":"Q: Is a typhoon going to come tomorrow? — A: Yes, it is. There is no school tomorrow.","t":"明天颱風要來嗎？ — 是的，明天停課。"},{"w":"earthquake","p":"n.","d":"","c":"地震","s":"Q: Is it an earthquake? The house is shaking! — A: Yes, it is! Get under the table.","t":"是地震嗎？房子在搖！ — 是的！躲到桌子底下。"},{"w":"sun","p":"n.","d":"","c":"太陽","s":"Q: Where does the sun come up? — A: It comes up in the east.","t":"太陽從哪裡升起？ — 它從東方升起。"},{"w":"shine (shines)","p":"v.","d":"","c":"照耀","s":"Q: What does the sun do in the day? — A: It shines and gives us light.","t":"太陽白天做什麼？ — 它照耀著，給我們光。"},{"w":"moon","p":"n.","d":"","c":"月亮","s":"Q: When do you see the moon? — A: I see it at night. Sometimes it's round.","t":"你什麼時候看得到月亮？ — 我在晚上看到它，它有時候是圓的。"},{"w":"star (stars)","p":"n.","d":"","c":"星星","s":"Q: What do you see in the sky at night? — A: I see many bright stars.","t":"你晚上在天空看到什麼？ — 我看到很多明亮的星星。"},{"w":"sky","p":"n.","d":"","c":"天空","s":"Q: Where do birds fly? — A: They fly in the sky.","t":"鳥在哪裡飛？ — 牠們在天空飛。"},{"w":"earth","p":"n.","d":"","c":"地球","s":"Q: Where do we live? — A: We live on the earth. It is round.","t":"我們住在哪裡？ — 我們住在地球上，它是圓的。"},{"w":"air","p":"n.","d":"","c":"空氣","s":"Q: What do people and animals need? — A: They need air, water and food.","t":"人和動物需要什麼？ — 他們需要空氣、水和食物。"},{"w":"plant (plants)","p":"n.","d":"","c":"植物","s":"Q: What do plants need? — A: They need water and light.","t":"植物需要什麼？ — 它們需要水和光。"},{"w":"nature","p":"n.","d":"","c":"自然；大自然","s":"Q: Does your father love nature? — A: Yes, he does. He often goes to the mountains.","t":"你爸爸熱愛大自然嗎？ — 是的，他常常去山上。"}]},{"unit":24,"theme":"Geographical Terms 地理名詞（第25區）","cards":[{"w":"area","p":"n.","d":"","c":"地區","s":"Q: Is this an old area? — A: Yes, it is. There are many old houses near the station.","t":"這是一個老地區嗎？ — 是的，車站附近有很多老房子。"},{"w":"hill","p":"n.","d":"","c":"小山","s":"Q: What is there near your school? — A: There is a small hill near my school. We often walk up it.","t":"你的學校附近有什麼？ — 我的學校附近有一座小山，我們常常走上去。"},{"w":"mountain (mountains)","p":"n.","d":"","c":"山","s":"Q: Are there any mountains near Taipei? — A: Yes, there are. There are many high mountains near Taipei.","t":"台北附近有山嗎？ — 有，台北附近有很多高山。"},{"w":"island (islands)","p":"n.","d":"","c":"島嶼","s":"Q: What is there near Taiwan? — A: There are many small islands near Taiwan, like Green Island.","t":"台灣附近有什麼？ — 台灣附近有很多小島，像是綠島。"},{"w":"pond","p":"n.","d":"","c":"池塘","s":"Q: Is there a pond in the park? — A: Yes, there is. There are many fish and frogs in it.","t":"公園裡有池塘嗎？ — 有，裡面有很多魚和青蛙。"},{"w":"beach","p":"n.","d":"","c":"海灘","s":"Q: What can you do at the beach? — A: I can play in the sand and swim in the sea.","t":"你在海灘可以做什麼？ — 我可以玩沙，也可以在海裡游泳。"},{"w":"sea","p":"n.","d":"","c":"海","s":"Q: What can your brother do in the sea? — A: He can swim and look at the fish.","t":"你哥哥在海裡可以做什麼？ — 他可以游泳和看魚。"},{"w":"pool","p":"n.","d":"","c":"游泳池","s":"Q: What can we do at the swimming pool? — A: We can swim and play in the water. But don't run there.","t":"我們在游泳池可以做什麼？ — 我們可以游泳、玩水，但不要在那裡跑。"},{"w":"river","p":"n.","d":"","c":"河","s":"Q: What does your grandpa do on Sundays? — A: He goes fishing by the river.","t":"你爺爺星期天做什麼？ — 他去河邊釣魚。"},{"w":"bank","p":"n.","d":"","c":"（河）岸；堤","s":"Q: Where do you and your friends ride bikes? — A: We ride bikes along the river bank.","t":"你和你的朋友在哪裡騎腳踏車？ — 我們沿著河岸騎腳踏車。"},{"w":"lake","p":"n.","d":"","c":"湖","s":"Q: Where does Amy go on vacation? — A: She goes to Sun Moon lake. She takes a boat there.","t":"艾美放假去哪裡？ — 她去日月潭，她在那裡搭船。"},{"w":"spring","p":"n.","d":"","c":"泉","s":"Q: What do people do in Beitou in winter? — A: They take a bath in a hot spring.","t":"人們冬天在北投做什麼？ — 他們去泡溫泉。"}]},{"unit":25,"theme":"Animals & Insects 動物與昆蟲（第26區）","cards":[{"w":"lion","p":"n.","d":"","c":"獅子","s":"Q: What animal is it? It is the king of the animals. — A: It's a lion. It has a big head and a lot of hair.","t":"這是什麼動物？牠是萬獸之王。 — 牠是獅子，牠有大大的頭和很多毛。"},{"w":"tiger","p":"n.","d":"","c":"老虎","s":"Q: What animal is it? It has black and orange lines. — A: It's a tiger. It can run very fast.","t":"這是什麼動物？牠身上有黑色和橘色的條紋。 — 牠是老虎，牠可以跑得很快。"},{"w":"bear","p":"n.","d":"","c":"熊","s":"Q: What animal is it? It is big and brown. It likes honey. — A: It's a bear. Don't go near it.","t":"這是什麼動物？牠又大又是棕色的，牠喜歡蜂蜜。 — 牠是熊，不要靠近牠。"},{"w":"fox","p":"n.","d":"","c":"狐狸","s":"Q: What animal is it? It looks like a dog, and it is very smart. — A: It's a fox. It has a big tail.","t":"這是什麼動物？牠看起來像狗，而且很聰明。 — 牠是狐狸，牠有一條大尾巴。"},{"w":"elephant","p":"n.","d":"","c":"大象","s":"Q: What animal is it? It has a long nose and big ears. — A: It's an elephant. It is very big and heavy.","t":"這是什麼動物？牠有長鼻子和大耳朵。 — 牠是大象，牠又大又重。"},{"w":"hippo","p":"n.","d":"","c":"河馬","s":"Q: What animal is it? It has a big mouth and lives in the river. — A: It's a hippo. It is fat and heavy.","t":"這是什麼動物？牠有一張大嘴巴，住在河裡。 — 牠是河馬，牠又胖又重。"},{"w":"zebra (zebras)","p":"n.","d":"","c":"斑馬","s":"Q: What animals are they? They are black and white. — A: They are zebras. They look like horses.","t":"這些是什麼動物？牠們是黑白相間的。 — 牠們是斑馬，牠們看起來像馬。"},{"w":"monkey (monkeys)","p":"n.","d":"","c":"猴子","s":"Q: What animals are they? They like bananas. — A: They are monkeys. They can climb trees.","t":"這些是什麼動物？牠們喜歡香蕉。 — 牠們是猴子，牠們會爬樹。"},{"w":"kangaroo","p":"n.","d":"","c":"袋鼠","s":"Q: What animal is it? It can jump very high. — A: It's a kangaroo. It has a baby in its pocket.","t":"這是什麼動物？牠可以跳得很高。 — 牠是袋鼠，牠的口袋裡有一隻寶寶。"},{"w":"koala","p":"n.","d":"","c":"無尾熊","s":"Q: What animal is it? It sleeps in the tree all day. — A: It's a koala. It looks like a little bear.","t":"這是什麼動物？牠整天在樹上睡覺。 — 牠是無尾熊，牠看起來像一隻小熊。"},{"w":"dragon","p":"n.","d":"","c":"龍","s":"Q: What animal is it? It can fly, and it is in many Chinese stories. — A: It's a dragon. It isn't a real animal.","t":"這是什麼動物？牠會飛，而且出現在很多中國故事裡。 — 牠是龍，牠不是真的動物。"},{"w":"rabbit","p":"n.","d":"","c":"兔子","s":"Q: What does a rabbit look like? — A: It has long ears and a short tail. It eats vegetables.","t":"兔子長什麼樣子？ — 牠有長耳朵和短尾巴，牠吃蔬菜。"},{"w":"tail","p":"n.","d":"","c":"尾巴","s":"Q: What does your dog look like? — A: It's white, and it has a long tail.","t":"你的狗長什麼樣子？ — 牠是白色的，有一條長尾巴。"},{"w":"mouse (mice)","p":"n.","d":"","c":"老鼠","s":"Q: What do mice look like? — A: They are small and gray. They have long tails.","t":"老鼠長什麼樣子？ — 牠們小小的、灰色的，有長長的尾巴。"},{"w":"rat (rats)","p":"n.","d":"","c":"（大）老鼠","s":"Q: What do rats look like? — A: They look like big mice. They are dirty.","t":"大老鼠長什麼樣子？ — 牠們看起來像大隻的老鼠，牠們很髒。"},{"w":"cow","p":"n.","d":"","c":"母牛","s":"Q: What does a cow look like? — A: It is black and white. It gives us milk.","t":"母牛長什麼樣子？ — 牠是黑白色的，牠給我們牛奶。"},{"w":"ox","p":"n.","d":"","c":"公牛","s":"Q: What does an ox look like? — A: It is big and strong. It helps farmers.","t":"公牛長什麼樣子？ — 牠又大又強壯，牠幫助農夫。"},{"w":"horse (horses)","p":"n.","d":"","c":"馬","s":"Q: What do horses look like? — A: They are tall, and they have long legs. They run fast.","t":"馬長什麼樣子？ — 牠們很高，有長長的腿，牠們跑得很快。"},{"w":"pig","p":"n.","d":"","c":"豬","s":"Q: What does a pig look like? — A: It is pink and fat. It has a short tail.","t":"豬長什麼樣子？ — 牠是粉紅色的、胖胖的，有一條短尾巴。"},{"w":"goat (goats)","p":"n.","d":"","c":"山羊","s":"Q: What do goats look like? — A: They are white. They live on the hill and eat grass.","t":"山羊長什麼樣子？ — 牠們是白色的，牠們住在山丘上吃草。"},{"w":"sheep (sheep)","p":"n.","d":"","c":"綿羊","s":"Q: What do sheep look like? — A: They are white and soft. They eat grass on the farm.","t":"綿羊長什麼樣子？ — 牠們白白的、軟軟的，在農場吃草。"},{"w":"bird (birds)","p":"n.","d":"","c":"鳥","s":"Q: Can birds fly? — A: Yes, they can. They fly in the sky.","t":"鳥會飛嗎？ — 會，牠們在天空飛。"},{"w":"bat","p":"n.","d":"","c":"蝙蝠","s":"Q: Can a bat fly? — A: Yes, it can. It flies at night.","t":"蝙蝠會飛嗎？ — 會，牠在晚上飛。"},{"w":"bee (bees)","p":"n.","d":"","c":"蜜蜂","s":"Q: Can bees fly? — A: Yes, they can. They make honey.","t":"蜜蜂會飛嗎？ — 會，牠們會製造蜂蜜。"},{"w":"butterfly","p":"n.","d":"","c":"蝴蝶","s":"Q: Can the butterfly fly? — A: Yes, it can. It is flying over the flowers.","t":"這隻蝴蝶會飛嗎？ — 會，牠正在花朵上方飛。"},{"w":"duck","p":"n.","d":"","c":"鴨","s":"Q: Can a duck swim? — A: Yes, it can. It swims in the pond.","t":"鴨子會游泳嗎？ — 會，牠在池塘裡游泳。"},{"w":"goose (geese)","p":"n.","d":"","c":"鵝","s":"Q: Can geese swim? — A: Yes, they can. They swim in the lake.","t":"鵝會游泳嗎？ — 會，牠們在湖裡游泳。"},{"w":"fish (fish)","p":"n.","d":"","c":"魚","s":"Q: Can fish fly? — A: No, they can't. But they can swim.","t":"魚會飛嗎？ — 不會，但是牠們會游泳。"},{"w":"frog","p":"n.","d":"","c":"青蛙","s":"Q: Can a frog swim? — A: Yes, it can. It can jump, too.","t":"青蛙會游泳嗎？ — 會，牠也會跳。"},{"w":"turtle","p":"n.","d":"","c":"烏龜","s":"Q: Can a turtle run fast? — A: No, it can't. It walks very slowly.","t":"烏龜可以跑得很快嗎？ — 不行，牠走得很慢。"},{"w":"snake","p":"n.","d":"","c":"蛇","s":"Q: Can a snake walk? — A: No, it can't. It has no legs.","t":"蛇會走路嗎？ — 不會，牠沒有腳。"},{"w":"insect","p":"n.","d":"","c":"昆蟲","s":"Q: How many legs does an insect have? — A: It has six legs.","t":"昆蟲有幾隻腳？ — 牠有六隻腳。"},{"w":"ant (ants)","p":"n.","d":"","c":"螞蟻","s":"Q: How many legs do ants have? — A: They have six legs. They are insects.","t":"螞蟻有幾隻腳？ — 牠們有六隻腳，牠們是昆蟲。"},{"w":"bug (bugs)","p":"n.","d":"","c":"小蟲","s":"Q: How many legs do they have? — A: These little bugs have six legs.","t":"牠們有幾隻腳？ — 這些小蟲有六隻腳。"},{"w":"spider","p":"n.","d":"","c":"蜘蛛","s":"Q: How many legs does a spider have? — A: It has eight legs. It isn't an insect.","t":"蜘蛛有幾隻腳？ — 牠有八隻腳，牠不是昆蟲。"},{"w":"chicken (chickens)","p":"n.","d":"","c":"雞；小雞","s":"Q: How many legs do chickens have? — A: They have two legs. They can't fly well.","t":"雞有幾隻腳？ — 牠們有兩隻腳，牠們飛不太好。"},{"w":"hen (hens)","p":"n.","d":"","c":"母雞","s":"Q: How many hens does your grandpa have? — A: He has ten hens. They give us eggs.","t":"你爺爺有幾隻母雞？ — 他有十隻母雞，牠們給我們蛋。"},{"w":"animal","p":"n.","d":"","c":"動物","s":"Q: What animal do you like best? — A: I like dogs best. They are friendly.","t":"你最喜歡什麼動物？ — 我最喜歡狗，牠們很友善。"},{"w":"pet","p":"n.","d":"","c":"寵物","s":"Q: Do you have a pet? — A: Yes, I do. I have a little cat.","t":"你有養寵物嗎？ — 有，我養了一隻小貓。"},{"w":"cat (cats)","p":"n.","d":"","c":"貓","s":"Q: What animal does your sister like? — A: She likes cats. She has a black one.","t":"你姊姊喜歡什麼動物？ — 她喜歡貓，她有一隻黑貓。"},{"w":"dog","p":"n.","d":"","c":"狗","s":"Q: Does Tom have a pet? — A: Yes, he does. He has a dog. It's very friendly.","t":"湯姆有養寵物嗎？ — 有，他養了一隻狗，牠很友善。"},{"w":"puppy","p":"n.","d":"","c":"小狗","s":"Q: Does Amy like her new puppy? — A: Yes, she does. It's very cute.","t":"艾美喜歡她的新小狗嗎？ — 喜歡，牠非常可愛。"},{"w":"cage","p":"n.","d":"","c":"籠子","s":"Q: Where do you keep your bird? — A: I keep it in a cage.","t":"你把你的鳥養在哪裡？ — 我把牠養在籠子裡。"},{"w":"bite","p":"v.","d":"","c":"咬","s":"Q: Does your dog bite? — A: No, it doesn't. It never bites people.","t":"你的狗會咬人嗎？ — 不會，牠從不咬人。"}]},{"unit":26,"theme":"Articles & Determiners 冠詞與限定詞（第27區）","cards":[{"w":"this","p":"det.","d":"","c":"這個","s":"Q: What is this in your hand? — A: It's a new watch. My grandpa gives it to me.","t":"你手上的這個是什麼？ — 它是一支新手錶，我爺爺送給我的。"},{"w":"that","p":"det.","d":"","c":"那個","s":"Q: What is that big building over there? — A: It's the new library. We read books there.","t":"那邊那棟大建築物是什麼？ — 它是新的圖書館，我們在那裡讀書。"},{"w":"these","p":"det.","d":"","c":"這些","s":"Q: Do you like these shoes? — A: Yes, I do. They are cute and comfortable.","t":"你喜歡這些（這雙）鞋子嗎？ — 是的，我喜歡。它們很可愛又舒適。"},{"w":"those","p":"det.","d":"","c":"那些","s":"Q: Does your sister want those cookies over there? — A: Yes, she does. She loves cookies.","t":"你妹妹想要那邊那些餅乾嗎？ — 是的，她想要。她很愛餅乾。"},{"w":"my","p":"det.","d":"","c":"我的","s":"Q: Whose eraser is this? — A: It's my eraser. Thank you.","t":"這是誰的橡皮擦？ — 是我的橡皮擦，謝謝你。"},{"w":"your","p":"det.","d":"","c":"你（們）的","s":"Q: Do you like your new school, Amy? — A: Yes, I do. My classmates are very nice.","t":"艾美，你喜歡你的新學校嗎？ — 是的，我喜歡。我的同學們都很好。"},{"w":"his","p":"det.","d":"","c":"他的","s":"Q: Whose bike is this? Is it Tom's? — A: Yes, it is. It's his new bike. He rides it to school.","t":"這是誰的腳踏車？是湯姆的嗎？ — 是的，是他的新腳踏車，他騎它去上學。"},{"w":"her","p":"det.","d":"","c":"她的","s":"Q: Does Amy do her homework after dinner? — A: Yes, she does. She is a good student.","t":"艾美晚餐後寫她的功課嗎？ — 是的，她會。她是個好學生。"},{"w":"its","p":"det.","d":"","c":"牠的；它的","s":"Q: Does your dog like its new house? — A: Yes, it does. It sleeps in it every night.","t":"你的狗喜歡牠的新狗屋嗎？ — 是的，牠喜歡。牠每天晚上都睡在裡面。"},{"w":"our","p":"det.","d":"","c":"我們的","s":"Q: Where do you and Ben have English class? — A: We have it in our classroom.","t":"你和班在哪裡上英文課？ — 我們在我們的教室上課。"},{"w":"their","p":"det.","d":"","c":"他們的","s":"Q: What do your parents do on Sundays? — A: They wash their car together.","t":"你爸媽星期天做什麼？ — 他們一起洗他們的車。"},{"w":"a / an","p":"art.","d":"","c":"一（個）","s":"Q: What does Ben want for lunch? — A: He wants an apple and a hamburger.","t":"班午餐想吃什麼？— 他想要一顆蘋果和一個漢堡。"},{"w":"the","p":"art.","d":"","c":"定冠詞（這；那）","s":"Q: What do you see in the sky at night? — A: I see the moon and many stars.","t":"你晚上在天空看到什麼？ — 我看到月亮和很多星星。"},{"w":"every","p":"det.","d":"","c":"每一（個）的","s":"Q: How often does Lisa play tennis? — A: She plays tennis every Sunday.","t":"麗莎多久打一次網球？ — 她每個星期天打網球。"}]},{"unit":27,"theme":"Pronouns & Reflexives 代名詞（第28區）","cards":[{"w":"I (mine)","p":"pron.","d":"","c":"我","s":"Q: Whose pencil case is this? Is it yours, Ben? — A: Yes, it's mine. Thank you.","t":"這是誰的鉛筆盒？班，是你的嗎？ — 是的，是我的。謝謝你。"},{"w":"she (hers)","p":"pron.","d":"","c":"她","s":"Q: Is this pink umbrella Amy's? — A: Yes, it's hers. She uses it every day.","t":"這把粉紅色的雨傘是艾美的嗎？ — 是的，是她的。她每天都用它。"},{"w":"we (ours)","p":"pron.","d":"","c":"我們","s":"Q: Do you and your brother share this room? — A: Yes, we do. This room is ours.","t":"你和你弟弟共用這個房間嗎？ — 是的。這個房間是我們的。"},{"w":"he (him)","p":"pron.","d":"","c":"他","s":"Q: Does Tom play basketball with you? — A: Yes, he does. I play with him every day.","t":"湯姆跟你一起打籃球嗎？ — 是的，他會。我每天都跟他打。"},{"w":"they (them)","p":"pron.","d":"","c":"他們","s":"Q: Do you like your new classmates? — A: Yes, I do. I often help them with math.","t":"你喜歡你的新同學嗎？ — 是的，我喜歡。我常常教他們數學。"},{"w":"you (yourself)","p":"pron.","d":"","c":"你（們）","s":"Q: Can I have some cookies, Grandma? — A: Sure. Help yourself, dear.","t":"奶奶，我可以吃一些餅乾嗎？ — 當然可以，親愛的，自己拿吧（別客氣）。"},{"w":"it (itself)","p":"pron.","d":"","c":"它；牠","s":"Q: Does your robot clean the floor by itself? — A: Yes, it does. It cleans the floor every day.","t":"你的機器人會自己掃地嗎？ — 是的，它會。它每天都掃地。"},{"w":"someone (somebody)","p":"pron.","d":"","c":"某人","s":"Q: Who is at the door? — A: I don't know. Someone is knocking on the door.","t":"誰在門口？ — 我不知道，有人在敲門。"},{"w":"anyone (anybody)","p":"pron.","d":"","c":"任何人","s":"Q: Does anyone in your class have a dictionary? — A: Yes, Amy does. She always brings it to school.","t":"你們班上有任何人有字典嗎？ — 有，艾美有。她總是帶到學校。"},{"w":"everyone (everybody)","p":"pron.","d":"","c":"每一個人","s":"Q: Is everyone here today? — A: No. Tom is sick. He is at home.","t":"今天每個人都到了嗎？ — 沒有，湯姆生病了，他在家。"},{"w":"nobody","p":"pron.","d":"","c":"沒有人","s":"Q: Who is in the classroom now? — A: Nobody is in it. Everyone is on the playground.","t":"現在誰在教室裡？ — 沒有人在裡面，大家都在操場上。"},{"w":"something","p":"pron.","d":"","c":"某事；某物","s":"Q: Do you want something to drink? — A: Yes, please. I'd like some juice.","t":"你想要喝點什麼嗎？ — 好，麻煩你。我想要一些果汁。"},{"w":"anything","p":"pron.","d":"","c":"任何事物","s":"Q: Does your brother need anything from the store? — A: Yes, he does. He needs some milk.","t":"你哥哥需要從商店買任何東西嗎？ — 是的，他需要。他需要一些牛奶。"},{"w":"everything","p":"pron.","d":"","c":"每件事；一切","s":"Q: Do you have everything for the picnic? — A: Yes, we do. We have food, water, and a big blanket.","t":"野餐的東西你們全都準備好了嗎？ — 是的，都好了。我們有食物、水和一條大毯子。"},{"w":"nothing","p":"pron.","d":"","c":"沒東西；沒事","s":"Q: What does Ben have in his pocket? — A: He has nothing. He doesn't have any money.","t":"班的口袋裡有什麼？ — 他什麼都沒有。他沒有任何錢。"},{"w":"all","p":"pron.","d":"","c":"全部","s":"Q: Do your classmates like PE? — A: Yes, all of them like it. They love sports.","t":"你的同學們喜歡體育課嗎？ — 是的，他們全部都喜歡。他們熱愛運動。"},{"w":"both","p":"pron.","d":"","c":"兩者都","s":"Q: Do your parents speak English? — A: Yes, both of them speak English.","t":"你的父母會說英文嗎？ — 會，他們兩個都會說英文。"},{"w":"each","p":"det.","d":"","c":"每一（個）","s":"Q: Does the teacher give the students a book? — A: Yes, she does. Each student has a new book.","t":"老師有發書給學生們嗎？ — 有，她有。每個學生都有一本新書。"},{"w":"most","p":"pron.","d":"","c":"大部分（的人／物）","s":"Q: Do your friends walk to school? — A: Most of them walk to school, but Tom rides his bike.","t":"你的朋友們走路上學嗎？ — 他們大部分走路上學，但湯姆騎腳踏車。"},{"w":"many","p":"pron.","d":"","c":"許多（人／物）","s":"Q: Does your sister have friends at her new school? — A: Yes, she does. Many of her classmates are nice to her.","t":"你妹妹在新學校有朋友嗎？ — 有，她有。她的很多同學都對她很好。"},{"w":"some","p":"pron.","d":"","c":"一些","s":"Q: I have many candies. Do you want some? — A: Yes, please. Thank you.","t":"我有很多糖果，你想要一些嗎？ — 好，麻煩你。謝謝你。"},{"w":"any","p":"det.","d":"","c":"任何的","s":"Q: Does your sister have any pets? — A: No, she doesn't. She is scared of animals.","t":"你妹妹有養任何寵物嗎？ — 沒有，她沒有。她怕動物。"},{"w":"another","p":"det.","d":"","c":"再一個；另一個","s":"Q: This cake is yummy. Can I have another piece? — A: Sure. Here you are.","t":"這蛋糕好好吃，我可以再吃一塊嗎？ — 當然，給你。"},{"w":"other","p":"pron.","d":"","c":"其他的（人／物）","s":"Q: What does Lisa have in her hands? — A: She has an apple in one hand and a banana in the other.","t":"麗莎手上拿著什麼？ — 她一隻手拿著蘋果，另一隻手拿著香蕉。"},{"w":"part","p":"n.","d":"","c":"部分","s":"Q: What part of the movie do you like? — A: I like the end. It is very funny.","t":"你喜歡這部電影的哪個部分？ — 我喜歡結尾，它非常好笑。"}]},{"unit":28,"theme":"Wh-words 疑問詞（第29區）","cards":[{"w":"who","p":"pron.","d":"","c":"誰","s":"Q: Who is that tall girl? — A: She is my cousin, Amy.","t":"那個高個子女孩是誰？ — 她是我的表妹艾美。"},{"w":"how","p":"adv.","d":"","c":"如何；怎麼樣","s":"Q: How is your grandma today? — A: She is much better, thank you.","t":"你奶奶今天好嗎？ — 她好多了，謝謝你。"},{"w":"what","p":"pron.","d":"","c":"什麼","s":"Q: What do you usually do after school? — A: I usually play basketball with my friends.","t":"你放學後通常做什麼？ — 我通常和朋友打籃球。"},{"w":"where","p":"adv.","d":"","c":"哪裡；何處","s":"Q: Where does your uncle live? — A: He lives in Kaohsiung. He works at a hospital there.","t":"你叔叔住在哪裡？ — 他住在高雄，他在那裡的一家醫院工作。"},{"w":"when","p":"adv.","d":"","c":"什麼時候；何時","s":"Q: When do you get up on Sundays? — A: I get up at nine. I don't go to school on Sundays.","t":"你星期天什麼時候起床？ — 我九點起床。我星期天不用上學。"},{"w":"why","p":"adv.","d":"","c":"為什麼","s":"Q: Why does Tom look sad? — A: Because he can't find his dog.","t":"湯姆為什麼看起來很難過？ — 因為他找不到他的狗。"},{"w":"whose","p":"det.","d":"","c":"誰的","s":"Q: Whose notebook is this? Is it yours? — A: No, it isn't. It's Ben's. His name is on it.","t":"這是誰的筆記本？是你的嗎？ — 不，不是。是班的，上面有他的名字。"},{"w":"which","p":"det.","d":"","c":"哪一個","s":"Q: Which bike do you like, the red one or the blue one? — A: I like the blue one. It's really cool.","t":"你喜歡哪一輛腳踏車，紅色的還是藍色的？ — 我喜歡藍色那輛，它真的很酷。"},{"w":"whether","p":"conj.","d":"","c":"是否","s":"Q: Does Ben like coffee? — A: I don't know whether he likes it. Let's ask him.","t":"班喜歡咖啡嗎？ — 我不知道他是否喜歡。我們問問他吧。"},{"w":"while","p":"conj.","d":"","c":"當…的時候","s":"Q: What does your mom do in the evening? — A: She watches TV while I do my homework.","t":"你媽媽晚上做什麼？ — 我寫功課的時候，她在看電視。"}]},{"unit":29,"theme":"Be & auxiliaries Be 動詞與助動詞（第30區）","cards":[{"w":"be (are)","p":"v.","d":"","c":"是；在","s":"Q: Are your parents at home now? — A: No, they aren't. They are at work.","t":"你爸媽現在在家嗎？ — 不，他們不在。他們在上班。"},{"w":"do (does)","p":"v.","d":"","c":"做","s":"Q: Does your sister do her homework after dinner? — A: Yes, she does. She does her homework at eight.","t":"你妹妹晚餐後寫功課嗎？ — 是的，她會。她八點寫功課。"},{"w":"have","p":"v.","d":"","c":"有","s":"Q: Do your grandparents have a pet? — A: Yes, they do. They have a cat. My uncle has two dogs.","t":"你的爺爺奶奶有養寵物嗎？ — 有，他們養一隻貓。我叔叔養兩隻狗。"},{"w":"can","p":"aux.","d":"","c":"能夠；會","s":"Q: Can your brother swim? — A: Yes, he can. He can swim very fast.","t":"你哥哥會游泳嗎？ — 是的，他會。他游得很快。"},{"w":"could","p":"aux.","d":"","c":"能；可以（客氣）","s":"Q: Could you help me, please? — A: Sure. What can I do for you?","t":"可以請你幫我嗎？ — 當然。我能為你做什麼？"},{"w":"may","p":"aux.","d":"","c":"可以；可能","s":"Q: May I use your eraser? — A: Yes, you may. Here you are.","t":"我可以用你的橡皮擦嗎？ — 可以，拿去吧。"},{"w":"will","p":"aux.","d":"","c":"將會","s":"Q: Will your mom cook dinner tonight? — A: No, she won't. We will eat out tonight.","t":"你媽媽今晚會煮晚餐嗎？ — 不，她不會。我們今晚要去外面吃。"},{"w":"must","p":"aux.","d":"","c":"必須","s":"Q: Must we wear our uniforms on Monday? — A: Yes, we must. It's a school rule.","t":"我們星期一必須穿制服嗎？ — 是的，必須。這是校規。"},{"w":"should","p":"aux.","d":"","c":"應該","s":"Q: Should Tom go to bed early tonight? — A: Yes, he should. He has a test tomorrow.","t":"湯姆今晚應該早點睡嗎？ — 是的，他應該。他明天有考試。"}]},{"unit":30,"theme":"Prepositions 介系詞（第31區）","cards":[{"w":"in","p":"prep.","d":"","c":"在…裡面","s":"Q: Where is your cat? — A: It's in the box.","t":"你的貓在哪裡？ — 牠在箱子裡。"},{"w":"inside","p":"prep.","d":"","c":"在…內部","s":"Q: Where do the children play on rainy days? — A: They play inside the house.","t":"下雨天孩子們在哪裡玩？ — 他們在屋子裡面玩。"},{"w":"outside","p":"prep.","d":"","c":"在…外面","s":"Q: Where does your dog sleep? — A: It sleeps outside the house, in the yard.","t":"你的狗睡在哪裡？ — 牠睡在屋外的院子裡。"},{"w":"on","p":"prep.","d":"","c":"在…上面","s":"Q: Where are my books? — A: They are on the desk.","t":"我的書在哪裡？ — 它們在書桌上。"},{"w":"above","p":"prep.","d":"","c":"在…上方","s":"Q: Where is the clock? — A: It's on the wall, above the door.","t":"時鐘在哪裡？ — 在牆上，門的上方。"},{"w":"over","p":"prep.","d":"","c":"在…正上方；越過","s":"Q: Where does Mom hang the lamp? — A: She hangs it over the table.","t":"媽媽把燈掛在哪裡？ — 她把燈掛在桌子正上方。"},{"w":"under","p":"prep.","d":"","c":"在…下面","s":"Q: Where are my shoes? — A: They are under the bed.","t":"我的鞋子在哪裡？ — 它們在床底下。"},{"w":"below","p":"prep.","d":"","c":"在…下方","s":"Q: Where do you write your name? — A: I write it below the picture.","t":"你把名字寫在哪裡？ — 我寫在圖片下方。"},{"w":"behind","p":"prep.","d":"","c":"在…後面","s":"Q: Where is the dog? — A: It's behind the door.","t":"狗在哪裡？ — 牠在門後面。"},{"w":"beside","p":"prep.","d":"","c":"在…旁邊","s":"Q: Where does Amy sit in class? — A: She sits beside me.","t":"艾美上課坐在哪裡？ — 她坐在我旁邊。"},{"w":"near","p":"prep.","d":"","c":"在…附近","s":"Q: Where do your grandparents live? — A: They live near the park.","t":"你的爺爺奶奶住在哪裡？ — 他們住在公園附近。"},{"w":"between","p":"prep.","d":"","c":"在…之間","s":"Q: Where is the bank? — A: It's between the post office and the hospital.","t":"銀行在哪裡？ — 在郵局和醫院之間。"},{"w":"around","p":"prep.","d":"","c":"在…四周","s":"Q: Where do the students sit? — A: They sit around the table.","t":"學生們坐在哪裡？ — 他們圍坐在桌子四周。"},{"w":"at","p":"prep.","d":"","c":"在（時間點）","s":"Q: What time does Ben get up? — A: He gets up at seven o'clock.","t":"班幾點起床？ — 他七點起床。"},{"w":"before","p":"prep.","d":"","c":"在…之前","s":"Q: When do you do your homework? — A: I do it before dinner.","t":"你什麼時候寫功課？ — 我在晚餐前寫。"},{"w":"after","p":"prep.","d":"","c":"在…之後","s":"Q: When does your sister play the piano? — A: She plays it after school.","t":"你妹妹什麼時候彈鋼琴？ — 她放學後彈。"},{"w":"during","p":"prep.","d":"","c":"在…期間","s":"Q: When do you visit your grandma? — A: I visit her during the summer vacation.","t":"你什麼時候去看奶奶？ — 我暑假期間去看她。"},{"w":"from","p":"prep.","d":"","c":"從","s":"Q: When does Mr. Lin work? — A: He works from Monday to Friday.","t":"林先生什麼時候上班？ — 他從星期一工作到星期五。"},{"w":"until","p":"prep.","d":"","c":"直到","s":"Q: How long do you stay at school? — A: I stay at school until five o'clock.","t":"你在學校待多久？ — 我在學校待到五點。"},{"w":"since","p":"prep.","d":"","c":"自從","s":"Q: How long has your family lived in Taipei? — A: We have lived here since 2020.","t":"你們家住在台北多久了？ — 我們從2020年就住在這裡。"},{"w":"to","p":"prep.","d":"","c":"到；往","s":"Q: Where does your brother go every morning? — A: He goes to school by bus.","t":"你哥哥每天早上去哪裡？ — 他搭公車去學校。"},{"w":"into","p":"prep.","d":"","c":"進入…之內","s":"Q: What does the cat do? — A: It jumps into the box.","t":"那隻貓在做什麼？ — 牠跳進箱子裡。"},{"w":"out (out of)","p":"adv.","d":"","c":"向外；在外","s":"Q: Where do the kids run when the bell rings? — A: They run out of the classroom.","t":"鐘響時孩子們跑去哪裡？ — 他們跑出教室。"},{"w":"off","p":"prep.","d":"","c":"離開；脫掉","s":"Q: What do you do at the door? — A: I take off my shoes.","t":"你在門口做什麼？ — 我脫掉鞋子。"},{"w":"up","p":"prep.","d":"","c":"向上","s":"Q: Where does the monkey go? — A: It climbs up the tree.","t":"猴子去哪裡？ — 牠爬上樹。"},{"w":"down","p":"prep.","d":"","c":"向下","s":"Q: What do the kids do on the slide? — A: They go down the slide.","t":"孩子們在溜滑梯上做什麼？ — 他們溜下溜滑梯。"},{"w":"along","p":"prep.","d":"","c":"沿著","s":"Q: Where does Grandpa walk every evening? — A: He walks along the river.","t":"爺爺每天傍晚在哪裡散步？ — 他沿著河邊散步。"},{"w":"across","p":"prep.","d":"","c":"橫越；在…對面","s":"Q: How do I get to the bank? — A: Walk across the street. It's next to the park.","t":"我要怎麼去銀行？ — 過馬路，它在公園旁邊。"},{"w":"through","p":"prep.","d":"","c":"穿過","s":"Q: Does Amy walk through the park to school? — A: Yes, she does. It's a short way.","t":"艾美穿過公園走路上學嗎？ — 是的，那是一條近路。"},{"w":"about","p":"prep.","d":"","c":"關於","s":"Q: What do your friends often talk about? — A: They often talk about soccer.","t":"你的朋友們常聊什麼？ — 他們常聊足球。"},{"w":"for","p":"prep.","d":"","c":"為了；給","s":"Q: Who is this gift for? — A: It's for my dad. His birthday is tomorrow.","t":"這份禮物是給誰的？ — 是給我爸爸的，明天是他生日。"},{"w":"of","p":"prep.","d":"","c":"…的","s":"Q: What is this a picture of? — A: It's a picture of my family.","t":"這是一張什麼的照片？ — 這是一張我家人的照片。"},{"w":"with","p":"prep.","d":"","c":"和；用","s":"Q: Who does Amy go to the park with? — A: She goes there with her dog.","t":"艾美和誰去公園？ — 她和她的狗去那裡。"},{"w":"without","p":"prep.","d":"","c":"沒有","s":"Q: Does Grandpa read without his glasses? — A: No, he doesn't. He can't see without them.","t":"爺爺不戴眼鏡看書嗎？ — 不，他不會。沒有眼鏡他看不見。"},{"w":"like","p":"prep.","d":"","c":"像；如","s":"Q: What does this candy taste like? — A: It tastes like strawberries.","t":"這顆糖吃起來像什麼？ — 它吃起來像草莓。"},{"w":"by","p":"prep.","d":"","c":"藉著；搭乘","s":"Q: How do you go to Tainan? — A: We go there by train.","t":"你們怎麼去台南？ — 我們搭火車去。"},{"w":"than","p":"prep.","d":"","c":"比","s":"Q: Who is taller, you or your brother? — A: My brother is taller than me.","t":"你和你哥哥誰比較高？ — 我哥哥比我高。"},{"w":"except","p":"prep.","d":"","c":"除了…之外","s":"Q: Do all your classmates like PE? — A: Yes, they do. Everyone likes PE except Tom.","t":"你所有同學都喜歡體育課嗎？ — 是的。除了湯姆，大家都喜歡體育課。"}]},{"unit":31,"theme":"Conjunctions 連接詞（第32區）","cards":[{"w":"or","p":"conj.","d":"","c":"或；還是","s":"Q: Does your brother want tea or coffee? — A: He wants coffee. He doesn't like tea.","t":"你哥哥想要茶還是咖啡？ — 他想要咖啡，他不喜歡茶。"},{"w":"and","p":"conj.","d":"","c":"和；而且","s":"Q: What do you have in your bag? — A: I have a pencil case and two books.","t":"你的書包裡有什麼？ — 我有一個鉛筆盒和兩本書。"},{"w":"but","p":"conj.","d":"","c":"但是","s":"Q: Does Amy like math? — A: Yes, she does, but she doesn't like science.","t":"艾美喜歡數學嗎？ — 是的，她喜歡，但是她不喜歡自然。"},{"w":"however","p":"adv.","d":"","c":"然而","s":"Q: Do your parents like the new house? — A: Yes, they do. However, it is far from the MRT station.","t":"你爸媽喜歡新房子嗎？ — 是的，他們喜歡。然而，它離捷運站很遠。"},{"w":"because","p":"conj.","d":"","c":"因為","s":"Q: Why does Tom stay at home today? — A: He stays at home because he is sick.","t":"湯姆今天為什麼待在家？ — 他待在家，因為他生病了。"},{"w":"since","p":"conj.","d":"","c":"因為；自從","s":"Q: Why do you and your sister take a taxi today? — A: Since it is raining hard, we don't want to walk.","t":"你和你妹妹今天為什麼搭計程車？ — 因為雨下得很大，我們不想走路。"},{"w":"though (although)","p":"conj.","d":"","c":"雖然","s":"Q: Does your grandpa walk to the park every day? — A: Yes, he does. Though he is eighty, he walks there every morning.","t":"你爺爺每天走路去公園嗎？ — 是的。雖然他八十歲了，他每天早上都走去那裡。"},{"w":"if","p":"conj.","d":"","c":"如果","s":"Q: What do you usually do on rainy Sundays? — A: If it rains on Sunday, I stay at home and watch TV.","t":"下雨的星期天你通常做什麼？ — 如果星期天下雨，我就待在家看電視。"},{"w":"that","p":"conj.","d":"","c":"引導子句（可省略）","s":"Q: What does your teacher say about the test? — A: She says that it is easy. Don't worry.","t":"你的老師對考試怎麼說？ — 她說考試很簡單。別擔心。"},{"w":"than","p":"conj.","d":"","c":"比","s":"Q: Who runs faster, Tom or Ben? — A: Tom runs faster than Ben does.","t":"誰跑得比較快，湯姆還是班？ — 湯姆跑得比班快。"},{"w":"as","p":"conj.","d":"","c":"和…一樣；如同","s":"Q: Do your two dogs eat a lot? — A: Yes, they do. The small dog eats as much as the big one.","t":"你的兩隻狗吃很多嗎？ — 是的。小狗吃得和大狗一樣多。"}]},{"unit":32,"theme":"Interjections 感嘆詞（第33區）","cards":[{"w":"hello","p":"int.","d":"","c":"哈囉；你好","s":"Q: What does Amy say when she answers the phone? — A: She says, \"hello, this is Amy speaking.\"","t":"艾美接電話時說什麼？ — 她說：「哈囉，我是艾美。」"},{"w":"hi","p":"int.","d":"","c":"嗨","s":"Q: Hi, Ben! Do you go to this school, too? — A: Yes, I do. I'm in Class 7. Nice to meet you.","t":"嗨，班！你也讀這所學校嗎？ — 是的，我在七班。很高興認識你。"},{"w":"hey","p":"int.","d":"","c":"嘿","s":"Q: Hey, Tom! Does your brother want to play basketball with us? — A: Yes, he does. Thank you! He's coming now.","t":"嘿，湯姆！你哥哥想跟我們一起打籃球嗎？ — 是的，他想。謝謝！他現在就來。"},{"w":"good-bye (goodbye, bye)","p":"int.","d":"","c":"再見","s":"Q: What do you say to your teacher after school? — A: I say, \"good-bye, Ms. Wang. See you tomorrow!\"","t":"放學後你跟老師說什麼？ — 我說：「再見，王老師。明天見！」"}]},{"unit":33,"theme":"Other Nouns (Part 1) 其他名詞（上）（第34上區）","cards":[{"w":"box","p":"n.","d":"","c":"盒子","s":"Q: What's this, Mom? — A: It's a box. Your birthday present is in it.","t":"媽，這是什麼？ — 這是一個盒子，你的生日禮物在裡面。"},{"w":"case","p":"n.","d":"","c":"盒；箱；情形","s":"Q: What's that on your desk? — A: It's my pencil case. I keep my pens in it.","t":"你書桌上那是什麼？ — 那是我的鉛筆盒，我把筆放在裡面。"},{"w":"can","p":"n.","d":"","c":"罐；罐頭","s":"Q: What's that in your hand? — A: It's a can of Coke. It's for my brother.","t":"你手上那是什麼？ — 那是一罐可樂，是給我弟弟的。"},{"w":"bell","p":"n.","d":"","c":"鈴；鐘","s":"Q: What's that sound? — A: It's the school bell. Class begins now.","t":"那是什麼聲音？ — 那是學校的鐘聲，現在要上課了。"},{"w":"robot","p":"n.","d":"","c":"機器人","s":"Q: What's this? — A: It's a robot. It cleans the floor for us.","t":"這是什麼？ — 這是一個機器人，它幫我們掃地。"},{"w":"tool","p":"n.","d":"","c":"工具","s":"Q: What's that in Dad's hand? — A: It's a tool. He fixes his bike with it.","t":"爸爸手上那是什麼？ — 那是一個工具，他用它修腳踏車。"},{"w":"nail (nails)","p":"n.","d":"","c":"釘子","s":"Q: What are these? — A: They are nails. Dad needs them to fix the chair.","t":"這些是什麼？ — 這些是釘子，爸爸需要它們來修椅子。"},{"w":"pin (pins)","p":"n.","d":"","c":"大頭針；別針","s":"Q: What are those on the wall? — A: They are pins. They hold the pictures on the wall.","t":"牆上那些是什麼？ — 那些是大頭針，它們把圖片固定在牆上。"},{"w":"rope","p":"n.","d":"","c":"繩子","s":"Q: What's this? — A: It's a jump rope. We use it in PE class.","t":"這是什麼？ — 這是一條跳繩，我們在體育課用它。"},{"w":"string","p":"n.","d":"","c":"線；細繩","s":"Q: What's that? — A: It's a string. I tie the box with it.","t":"那是什麼？ — 那是一條線，我用它綁盒子。"},{"w":"swing","p":"n.","d":"","c":"鞦韆","s":"Q: What's that in the park? — A: It's a swing. The kids love to play on it.","t":"公園裡那是什麼？ — 那是一個鞦韆，小孩們很愛在上面玩。"},{"w":"castle","p":"n.","d":"","c":"城堡","s":"Q: What's that on the hill? — A: It's an old castle. A king lived there.","t":"山丘上那是什麼？ — 那是一座古老的城堡，以前有一位國王住在那裡。"},{"w":"rose (roses)","p":"n.","d":"","c":"玫瑰","s":"Q: What are those red ones in the garden? — A: They are roses. They smell sweet.","t":"花園裡那些紅色的是什麼？ — 它們是玫瑰，聞起來很香。"},{"w":"cellphone","p":"n.","d":"","c":"手機","s":"Q: Does your brother have a phone? — A: Yes, he does. He has a new cellphone.","t":"你哥哥有電話嗎？ — 有，他有。他有一支新手機。"},{"w":"screen","p":"n.","d":"","c":"螢幕","s":"Q: What does your mom need? — A: She needs a new screen for her phone. The old one is broken.","t":"你媽媽需要什麼？ — 她的手機需要一個新螢幕，舊的壞了。"},{"w":"Internet (Net)","p":"n.","d":"","c":"網路","s":"Q: Where do your classmates find the answers? — A: They find them on the Internet.","t":"你的同學們在哪裡找到答案？ — 他們在網路上找到答案。"},{"w":"e-mail","p":"n.","d":"","c":"電子郵件","s":"Q: What does Tom write to his friend? — A: He writes an e-mail to him every week.","t":"湯姆寫什麼給他的朋友？ — 他每週寫一封電子郵件給他。"},{"w":"file","p":"n.","d":"","c":"檔案","s":"Q: What do you need for your report? — A: I need this file on my computer.","t":"你的報告需要什麼？ — 我需要電腦裡的這個檔案。"},{"w":"mail","p":"n.","d":"","c":"信件；郵件","s":"Q: What does the man from the post office bring? — A: He brings the mail to our house every day.","t":"郵局來的那個人帶來什麼？ — 他每天把信件送到我們家。"},{"w":"newspaper","p":"n.","d":"","c":"報紙","s":"Q: What does Grandpa read every morning? — A: He reads the newspaper.","t":"爺爺每天早上讀什麼？ — 他讀報紙。"},{"w":"news","p":"n.","d":"","c":"新聞；消息","s":"Q: What do your parents watch after dinner? — A: They watch the news on TV.","t":"你爸媽晚餐後看什麼？ — 他們看電視新聞。"},{"w":"photo","p":"n.","d":"","c":"照片","s":"Q: What do you have on your desk? — A: I have a photo of my family.","t":"你書桌上有什麼？ — 我有一張全家福照片。"},{"w":"note","p":"n.","d":"","c":"字條；筆記","s":"Q: What does Lisa have in her hand? — A: She has a note from her friend. It says, \"Happy birthday!\"","t":"麗莎手上有什麼？ — 她有一張朋友給的字條，上面寫著「生日快樂！」"},{"w":"gift","p":"n.","d":"","c":"禮物","s":"Q: What does Amy have for her mom? — A: She has a gift for her. It's a pink bag.","t":"艾美有什麼要給她媽媽？ — 她有一份禮物要給她，是一個粉紅色的包包。"},{"w":"ticket (tickets)","p":"n.","d":"","c":"票","s":"Q: What do we need for the movie? — A: We need two tickets. They are 250 dollars each.","t":"我們看電影需要什麼？ — 我們需要兩張票，每張 250 元。"},{"w":"metro","p":"n.","d":"","c":"捷運","s":"Q: How do you and your family go to the zoo? — A: We take the metro. It's fast.","t":"你和家人怎麼去動物園？ — 我們搭捷運，很快。"},{"w":"set","p":"n.","d":"","c":"一套；一組","s":"Q: What do you want for your birthday? — A: I want a set of color pens.","t":"你生日想要什麼？ — 我想要一組彩色筆。"},{"w":"item (items)","p":"n.","d":"","c":"項目；品項","s":"Q: What do you need to buy at the store? — A: I need to buy ten items on this list.","t":"你需要在商店買什麼？ — 我需要買這張清單上的十個品項。"},{"w":"thing (things)","p":"n.","d":"","c":"東西；事情","s":"Q: What do you have in your bag? — A: I have many things in it: books, pens, and a ruler.","t":"你的包包裡有什麼？ — 裡面有很多東西：書、筆和一把尺。"},{"w":"honey","p":"n.","d":"","c":"蜂蜜","s":"Q: Is there any honey for my tea? — A: Yes, there is some in the bottle.","t":"有蜂蜜可以加在我的茶裡嗎？ — 有，瓶子裡有一些。"},{"w":"gas","p":"n.","d":"","c":"瓦斯；汽油","s":"Q: Is there any gas for cooking? — A: No, there isn't any. Dad has to buy some.","t":"有瓦斯可以煮飯嗎？ — 沒有，一點都沒有，爸爸必須去買一些。"},{"w":"power","p":"n.","d":"","c":"電力；力量","s":"Q: Is there any light in the house? — A: No, there isn't. The power is out.","t":"屋子裡有燈光嗎？ — 沒有，停電了。"},{"w":"garbage","p":"n.","d":"","c":"垃圾","s":"Q: Is there any garbage in the kitchen? — A: Yes, there is a lot. Please take it out.","t":"廚房裡有垃圾嗎？ — 有，有很多，請把它拿出去倒。"},{"w":"trash","p":"n.","d":"","c":"垃圾","s":"Q: Is there any trash on the floor? — A: No, there isn't any. The room is clean.","t":"地板上有垃圾嗎？ — 沒有，一點都沒有，房間很乾淨。"},{"w":"mud","p":"n.","d":"","c":"泥巴","s":"Q: Is there any mud on your shoes? — A: Yes, there is. I played in the rain.","t":"你的鞋子上有泥巴嗎？ — 有，我在雨中玩了。"},{"w":"grass","p":"n.","d":"","c":"草","s":"Q: Is there any food for the sheep? — A: Yes, there is a lot of grass on the hill.","t":"有給綿羊吃的食物嗎？ — 有，山丘上有很多草。"},{"w":"space","p":"n.","d":"","c":"空間","s":"Q: Is there any space for a new desk? — A: No, there isn't. My room is too small.","t":"有空間放新書桌嗎？ — 沒有，我的房間太小了。"},{"w":"noise","p":"n.","d":"","c":"噪音；聲響","s":"Q: Is there any noise outside? — A: Yes, there is. The kids are playing ball.","t":"外面有噪音嗎？ — 有，小孩們在玩球。"},{"w":"fire","p":"n.","d":"","c":"火","s":"Q: What is there on the beach? — A: There is a big fire. We are having a barbecue.","t":"海灘上有什麼？ — 有一大堆火，我們正在烤肉。"},{"w":"heat","p":"n.","d":"","c":"熱；熱度","s":"Q: Why is it so hot today? — A: There is a lot of heat from the sun.","t":"今天為什麼這麼熱？ — 太陽的熱度很強。"},{"w":"ground","p":"n.","d":"","c":"地面","s":"Q: What is there on the playground? — A: There is a ball on the ground.","t":"操場上有什麼？ — 地上有一顆球。"},{"w":"corner","p":"n.","d":"","c":"角落；轉角","s":"Q: Is there a store near here? — A: Yes, there is. There is one on the corner.","t":"這附近有商店嗎？ — 有，轉角就有一家。"},{"w":"bottom","p":"n.","d":"","c":"底部","s":"Q: Is there any water in the bottle? — A: Yes, there is a little at the bottom.","t":"瓶子裡有水嗎？ — 有，底部有一點點。"},{"w":"center","p":"n.","d":"","c":"中心","s":"Q: Is there a park in the city? — A: Yes, there is. There is a big park in the center of the city.","t":"城市裡有公園嗎？ — 有，市中心有一座大公園。"},{"w":"side (sides)","p":"n.","d":"","c":"邊；面；旁邊","s":"Q: Are there any stores on this road? — A: Yes, there are. There are stores on both sides of the road.","t":"這條路上有商店嗎？ — 有，路的兩邊都有商店。"},{"w":"seat","p":"n.","d":"","c":"座位","s":"Q: Can I sit with you on the bus? — A: Sure. There is a free seat next to me.","t":"我可以在公車上跟你坐嗎？ — 當然，我旁邊有一個空位。"},{"w":"blank (blanks)","p":"n.","d":"","c":"空格","s":"Q: How many questions are there on the test? — A: There are ten blanks. Write a word in each one.","t":"考試有幾題？ — 有十個空格，每個空格寫一個字。"},{"w":"ghost","p":"n.","d":"","c":"鬼","s":"Q: Why are you scared? — A: My brother says there is a ghost in the old house.","t":"你為什麼害怕？ — 我哥哥說那間老房子裡有鬼。"},{"w":"tree","p":"n.","d":"","c":"樹","s":"Q: What is there in your yard? — A: There is a big tree. Birds sing in it.","t":"你家院子裡有什麼？ — 有一棵大樹，鳥在上面唱歌。"},{"w":"root (roots)","p":"n.","d":"","c":"根","s":"Q: Why is that old plant so strong? — A: There are long roots under it.","t":"那棵老植物為什麼這麼強壯？ — 它下面有很長的根。"},{"w":"seed (seeds)","p":"n.","d":"","c":"種子","s":"Q: What is there in the apple? — A: There are some seeds in it.","t":"蘋果裡有什麼？ — 裡面有一些種子。"},{"w":"flower (flowers)","p":"n.","d":"","c":"花","s":"Q: What is there in the garden? — A: There are many flowers. They are very beautiful.","t":"花園裡有什麼？ — 有很多花，它們很美。"},{"w":"rock (rocks)","p":"n.","d":"","c":"岩石","s":"Q: What is there in the river? — A: There are many big rocks. Don't swim there.","t":"河裡有什麼？ — 有很多大岩石，不要在那裡游泳。"},{"w":"planet (planets)","p":"n.","d":"","c":"行星","s":"Q: Are there other worlds around the sun? — A: Yes, there are. There are eight planets around the sun.","t":"太陽周圍還有其他世界嗎？ — 有，太陽周圍有八顆行星。"}]},{"unit":34,"theme":"Other Nouns (Part 2) 其他名詞（下）（第34下區）","cards":[{"w":"American","p":"n.","d":"","c":"美國人","s":"Q: Who is Mr. Brown? — A: He is our English teacher. He is an American from New York.","t":"布朗先生是誰？ — 他是我們的英文老師，他是來自紐約的美國人。"},{"w":"foreigner (foreigners)","p":"n.","d":"","c":"外國人","s":"Q: Who are those people at the night market? — A: They are foreigners. They come from Japan and Korea.","t":"夜市裡那些人是誰？ — 他們是外國人，來自日本和韓國。"},{"w":"leader","p":"n.","d":"","c":"領導者；隊長","s":"Q: Who is that tall boy? — A: He is Tom, our team leader. Everyone listens to him.","t":"那個高高的男孩是誰？ — 他是湯姆，我們的隊長，大家都聽他的。"},{"w":"member","p":"n.","d":"","c":"成員；會員","s":"Q: Does Amy join the music club? — A: Yes, she does. She is a member of the club.","t":"艾美有參加音樂社嗎？ — 有，她是社團的成員。"},{"w":"player (players)","p":"n.","d":"","c":"球員；選手","s":"Q: Who are those boys in the park? — A: They are basketball players. They play every Sunday.","t":"公園裡那些男孩是誰？ — 他們是籃球員，他們每個星期日都打球。"},{"w":"band","p":"n.","d":"","c":"樂團","s":"Q: What does your brother do after school? — A: He plays the drums in a band.","t":"你哥哥放學後做什麼？ — 他在一個樂團裡打鼓。"},{"w":"club","p":"n.","d":"","c":"社團","s":"Q: What club do you join? — A: I join the English club.","t":"你參加什麼社團？ — 我參加英文社。"},{"w":"group","p":"n.","d":"","c":"團體；小組","s":"Q: Who do you study with? — A: I study with my friends. We have a study group.","t":"你和誰一起讀書？ — 我和朋友們一起讀書，我們有一個讀書小組。"},{"w":"god (God)","p":"n.","d":"","c":"上帝；神","s":"Q: Who do people pray to in the church? — A: They pray to God.","t":"人們在教堂裡向誰禱告？ — 他們向上帝禱告。"},{"w":"chance","p":"n.","d":"","c":"機會","s":"Q: Does Lisa have a chance to go to Japan? — A: Yes, she does. She has a chance to visit her aunt there.","t":"麗莎有機會去日本嗎？ — 有，她有機會去那裡拜訪她的阿姨。"},{"w":"choice (choices)","p":"n.","d":"","c":"選擇","s":"Q: What do we have for lunch? — A: We have two choices: noodles or rice.","t":"我們午餐吃什麼？ — 我們有兩個選擇：麵或飯。"},{"w":"idea","p":"n.","d":"","c":"主意；想法","s":"Q: How can we make Mom happy on Mother's Day? — A: I have a good idea. Let's make a cake for her.","t":"母親節我們要怎麼讓媽媽開心？ — 我有一個好主意，我們來為她做一個蛋糕吧。"},{"w":"habit","p":"n.","d":"","c":"習慣","s":"Q: Does your dad get up early every day? — A: Yes, he does. It's his good habit.","t":"你爸爸每天都早起嗎？ — 是的，這是他的好習慣。"},{"w":"experience","p":"n.","d":"","c":"經驗","s":"Q: Does your mom cook well? — A: Yes, she does. She has a lot of experience in cooking.","t":"你媽媽很會煮飯嗎？ — 是的，她有很多煮飯的經驗。"},{"w":"trouble","p":"n.","d":"","c":"麻煩；困難","s":"Q: Do you need help with your homework? — A: Yes, I do. I have trouble with the math questions.","t":"你的功課需要幫忙嗎？ — 需要，我數學題目有困難。"},{"w":"mistake (mistakes)","p":"n.","d":"","c":"錯誤","s":"Q: Does Ben get 100 on the test? — A: No, he doesn't. He makes two mistakes.","t":"班考試考一百分嗎？ — 沒有，他犯了兩個錯誤。"},{"w":"error","p":"n.","d":"","c":"錯誤","s":"Q: Is your answer right? — A: No, it isn't. There is an error in it.","t":"你的答案對嗎？ — 不對，裡面有一個錯誤。"},{"w":"excuse","p":"n.","d":"","c":"藉口","s":"Q: Why does Tom come late again? — A: He says he gets up late. That's not a good excuse.","t":"湯姆為什麼又遲到了？ — 他說他太晚起床，那不是個好藉口。"},{"w":"reason","p":"n.","d":"","c":"理由；原因","s":"Q: Why do you study English every day? — A: I want to talk to people from other countries. That's my reason.","t":"你為什麼每天讀英文？ — 我想和其他國家的人說話，那就是我的理由。"},{"w":"sight","p":"n.","d":"","c":"視力","s":"Q: Does your grandpa read the newspaper without glasses? — A: No, he doesn't. He has poor sight.","t":"你爺爺不戴眼鏡看報紙嗎？ — 不，他視力不好。"},{"w":"voice","p":"n.","d":"","c":"聲音；嗓音","s":"Q: Does Amy sing well? — A: Yes, she does. She has a beautiful voice.","t":"艾美唱歌好聽嗎？ — 好聽，她有美妙的嗓音。"},{"w":"meeting","p":"n.","d":"","c":"會議","s":"Q: What does Ms. Lin have this afternoon? — A: She has a meeting with other teachers.","t":"林老師今天下午有什麼事？ — 她和其他老師有一個會議。"},{"w":"party","p":"n.","d":"","c":"派對","s":"Q: What do you have on Saturday? — A: We have a birthday party for Amy.","t":"你們星期六有什麼活動？ — 我們要為艾美辦一個生日派對。"},{"w":"interview","p":"n.","d":"","c":"面試；採訪","s":"Q: Where does your sister go today? — A: She goes to a big company. She has a job interview.","t":"你姊姊今天去哪裡？ — 她去一家大公司，她有一個工作面試。"},{"w":"report","p":"n.","d":"","c":"報告；報導","s":"Q: What do you need to write for English class? — A: I need to write a book report.","t":"英文課你需要寫什麼？ — 我需要寫一份讀書報告。"},{"w":"sale","p":"n.","d":"","c":"特價；出售","s":"Q: Why do so many people go to the store today? — A: There is a big sale. Everything is cheap.","t":"今天為什麼這麼多人去那家店？ — 有大特價，所有東西都很便宜。"},{"w":"prize","p":"n.","d":"","c":"獎品；獎","s":"Q: What does Tom get in the race? — A: He gets first prize. It's a new bike.","t":"湯姆在賽跑中得到什麼？ — 他得到第一名的獎品，是一輛新腳踏車。"},{"w":"treat","p":"n.","d":"","c":"請客","s":"Q: Do we need to pay for dinner tonight? — A: No, we don't. It's Dad's treat.","t":"我們今晚晚餐需要付錢嗎？ — 不用，爸爸請客。"},{"w":"tip","p":"n.","d":"","c":"小費","s":"Q: What does Dad give the waiter? — A: He gives him a tip.","t":"爸爸給服務生什麼？ — 他給他小費。"},{"w":"order","p":"n.","d":"","c":"點餐；訂單","s":"Q: What does the waiter say? — A: He says, \"May I take your order?\"","t":"服務生說什麼？ — 他說：「我可以幫您點餐嗎？」"},{"w":"service","p":"n.","d":"","c":"服務","s":"Q: Do you like this restaurant? — A: Yes, I do. The food is good, and the service is great, too.","t":"你喜歡這家餐廳嗎？ — 喜歡，食物很好吃，服務也很棒。"},{"w":"eve (Eve)","p":"n.","d":"","c":"前夕","s":"Q: What do you do on Chinese New Year's Eve? — A: We eat a big dinner with our family.","t":"你們除夕做什麼？ — 我們和家人吃一頓大餐。"},{"w":"age","p":"n.","d":"","c":"年齡","s":"Q: What's your grandma's age? — A: She is seventy years old.","t":"你奶奶幾歲？ — 她七十歲。"},{"w":"birthday","p":"n.","d":"","c":"生日","s":"Q: When is your birthday? — A: It's on May 5th.","t":"你的生日是什麼時候？ — 在五月五日。"},{"w":"dream","p":"n.","d":"","c":"夢想","s":"Q: What's your sister's dream? — A: She wants to be a singer.","t":"你姊姊的夢想是什麼？ — 她想當歌手。"},{"w":"interest (interests)","p":"n.","d":"","c":"興趣","s":"Q: What interests does Ben have? — A: He likes reading and playing chess.","t":"班有什麼興趣？ — 他喜歡閱讀和下西洋棋。"},{"w":"subject","p":"n.","d":"","c":"科目","s":"Q: What's your favorite subject? — A: It's math.","t":"你最喜歡的科目是什麼？ — 是數學。"},{"w":"topic","p":"n.","d":"","c":"主題；話題","s":"Q: What's the topic of today's class? — A: It's animals.","t":"今天上課的主題是什麼？ — 是動物。"},{"w":"word","p":"n.","d":"","c":"字；單字","s":"Q: What does this word mean? — A: It means \"happy.\"","t":"這個字是什麼意思？ — 它的意思是「快樂的」。"},{"w":"sentence","p":"n.","d":"","c":"句子","s":"Q: What's the first sentence on page 10? — A: It's \"Tom has a cat.\"","t":"第十頁的第一個句子是什麼？ — 是「湯姆有一隻貓」。"},{"w":"way","p":"n.","d":"","c":"道路；方法","s":"Q: What's the way to the station? — A: Go straight and turn left.","t":"去車站的路怎麼走？ — 直走然後左轉。"},{"w":"matter","p":"n.","d":"","c":"事情；問題","s":"Q: What's the matter? — A: I have a headache.","t":"怎麼了？ — 我頭痛。"},{"w":"kind","p":"n.","d":"","c":"種類","s":"Q: What kind of music do you like? — A: I like pop music.","t":"你喜歡哪一種音樂？ — 我喜歡流行音樂。"},{"w":"level","p":"n.","d":"","c":"程度；等級","s":"Q: What's the level of this book? — A: It's easy. Children can read it.","t":"這本書的程度如何？ — 很簡單，小孩子都能讀。"},{"w":"mind","p":"n.","d":"","c":"頭腦；心思","s":"Q: You look worried. What's on your mind? — A: I'm worried about the math test.","t":"你看起來很擔心，你在想什麼？ — 我在擔心數學考試。"},{"w":"rule","p":"n.","d":"","c":"規則","s":"Q: What's the first rule in your class? — A: Don't be late for class.","t":"你們班的第一條規則是什麼？ — 上課不要遲到。"},{"w":"action","p":"n.","d":"","c":"動作；行動","s":"Q: Does your brother like action movies? — A: Yes, he does. He watches them every weekend.","t":"你哥哥喜歡動作片嗎？ — 喜歡，他每個週末都看。"},{"w":"fun","p":"n.","d":"","c":"樂趣；好玩的事","s":"Q: Do you and your friends have a good time at the beach? — A: Yes, we do. We have a lot of fun.","t":"你和朋友們在海灘玩得開心嗎？ — 開心，我們玩得很愉快。"},{"w":"joke (jokes)","p":"n.","d":"","c":"笑話","s":"Q: Does Uncle Jack like to make people laugh? — A: Yes, he does. He tells funny jokes.","t":"傑克叔叔喜歡逗人笑嗎？ — 喜歡，他會講好笑的笑話。"},{"w":"story (stories)","p":"n.","d":"","c":"故事","s":"Q: Do the children like books? — A: Yes, they do. They love stories about animals.","t":"孩子們喜歡書嗎？ — 喜歡，他們很愛動物的故事。"},{"w":"program","p":"n.","d":"","c":"節目","s":"Q: What TV program does your dad like? — A: He likes sports shows.","t":"你爸爸喜歡什麼電視節目？ — 他喜歡運動節目。"},{"w":"trick (tricks)","p":"n.","d":"","c":"惡作劇；把戲","s":"Q: Do your classmates like April Fools' Day? — A: Yes, they do. They play tricks on their friends.","t":"你的同學們喜歡愚人節嗎？ — 喜歡，他們會對朋友惡作劇。"},{"w":"smile","p":"n.","d":"","c":"微笑","s":"Q: Do the students like their new teacher? — A: Yes, they do. She has a sweet smile.","t":"學生們喜歡他們的新老師嗎？ — 喜歡，她有甜美的笑容。"},{"w":"joy","p":"n.","d":"","c":"歡樂；喜悅","s":"Q: How does Grandma feel when she sees the baby? — A: She is full of joy.","t":"奶奶看到寶寶時感覺如何？ — 她充滿了喜悅。"},{"w":"pleasure","p":"n.","d":"","c":"榮幸；愉快","s":"Q: Thank you for helping me. — A: It's my pleasure.","t":"謝謝你幫我。 — 這是我的榮幸。（不客氣）"},{"w":"cheer (cheers)","p":"n.","d":"","c":"歡呼；喝采","s":"Q: What do the fans do at the game? — A: They give loud cheers for the team.","t":"球迷在比賽時做什麼？ — 他們為球隊大聲歡呼。"},{"w":"fact","p":"n.","d":"","c":"事實","s":"Q: Does Tom know a lot about koalas? — A: Yes, he does. He knows a fun fact: koalas sleep 20 hours a day.","t":"湯姆對無尾熊很了解嗎？ — 是的，他知道一個有趣的事實：無尾熊一天睡二十個小時。"}]},{"unit":35,"theme":"Other Verbs (Part 1) 其他動詞（上）（第35上區）","cards":[{"w":"feel (feels)","p":"v.","d":"","c":"覺得；感覺","s":"Q: How does your grandma feel today? — A: She feels much better now.","t":"你奶奶今天覺得怎麼樣？ — 她現在覺得好多了。"},{"w":"smell","p":"v.","d":"","c":"聞起來","s":"Q: How do the flowers in your garden smell? — A: They smell sweet.","t":"你花園裡的花聞起來怎麼樣？ — 它們聞起來很香。"},{"w":"sound (sounds)","p":"v.","d":"","c":"聽起來","s":"Q: How does the new song sound? — A: It sounds great. I love it.","t":"這首新歌聽起來怎麼樣？ — 聽起來很棒，我很喜歡。"},{"w":"taste","p":"v.","d":"","c":"嚐起來；品嚐","s":"Q: How do these cookies taste? — A: They taste sweet and yummy.","t":"這些餅乾嚐起來怎麼樣？ — 又甜又好吃。"},{"w":"know (knows)","p":"v.","d":"","c":"知道；認識","s":"Q: Does Lisa have Tom's phone number? — A: Yes, she does. She knows his number.","t":"麗莎有湯姆的電話號碼嗎？ — 有，她知道他的號碼。"},{"w":"remember","p":"v.","d":"","c":"記得","s":"Q: Do you remember my name? — A: Yes, I do. You're Lisa.","t":"你記得我的名字嗎？ — 記得，你是麗莎。"},{"w":"think","p":"v.","d":"","c":"想；認為","s":"Q: What do you say about this book? — A: I think it's very interesting.","t":"你對這本書有什麼看法？ — 我認為它很有趣。"},{"w":"believe","p":"v.","d":"","c":"相信","s":"Q: Does Amy say ghosts are real? — A: No, she doesn't. She doesn't believe in ghosts.","t":"艾美說鬼是真的嗎？ — 不，她不相信有鬼。"},{"w":"hope","p":"v.","d":"","c":"希望","s":"Q: Do you have any plans for tomorrow? — A: Yes. We want to go to the beach. I hope it will be sunny.","t":"你明天有什麼計畫嗎？ — 有，我們想去海邊，我希望會是晴天。"},{"w":"want (wants)","p":"v.","d":"","c":"想要","s":"Q: What does your sister ask for on her birthday? — A: She wants a new bike.","t":"你妹妹生日要求什麼？ — 她想要一輛新腳踏車。"},{"w":"need (needs)","p":"v.","d":"","c":"需要","s":"Q: What does Ben take to art class? — A: He needs some color pens.","t":"班帶什麼去美術課？ — 他需要一些彩色筆。"},{"w":"wish","p":"v.","d":"","c":"祝福；希望","s":"Q: What do you say to Tom on his birthday? — A: I say, \"I wish you a happy birthday!\"","t":"湯姆生日時你對他說什麼？ — 我說：「祝你生日快樂！」"},{"w":"like (likes)","p":"v.","d":"","c":"喜歡","s":"Q: What does your brother do after school? — A: He likes to play basketball. He plays every day.","t":"你哥哥放學後做什麼？ — 他喜歡打籃球，他每天都打。"},{"w":"love","p":"v.","d":"","c":"喜愛；愛","s":"Q: Do your parents enjoy cooking? — A: Yes, they do. They love cooking.","t":"你爸媽喜歡煮飯嗎？ — 是的，他們很愛煮飯。"},{"w":"hate (hates)","p":"v.","d":"","c":"討厭","s":"Q: Does your cat enjoy water? — A: No, it doesn't. It hates water.","t":"你的貓喜歡水嗎？ — 不，牠討厭水。"},{"w":"mind","p":"v.","d":"","c":"介意","s":"Q: Do you mind if I sit here? — A: No, I don't. Please sit down.","t":"你介意我坐這裡嗎？ — 不介意，請坐。"},{"w":"bow","p":"v.","d":"","c":"鞠躬；敬禮","s":"Q: What do people in Japan do when they meet? — A: They bow to each other.","t":"日本人見面時做什麼？ — 他們互相鞠躬。"},{"w":"collect (collects)","p":"v.","d":"","c":"收集","s":"Q: What does Uncle Jack do in his free time? — A: He collects stamps.","t":"傑克叔叔空閒時做什麼？ — 他收集郵票。"},{"w":"feed (feeds)","p":"v.","d":"","c":"餵","s":"Q: What does your sister do every morning? — A: She feeds the fish.","t":"你姊姊每天早上做什麼？ — 她餵魚。"},{"w":"look (looking)","p":"v.","d":"","c":"看（著）","s":"Q: What are the students doing? — A: They are looking at the blackboard.","t":"學生們在做什麼？ — 他們正在看黑板。"},{"w":"watch (watching)","p":"v.","d":"","c":"觀看；注視","s":"Q: What is Grandpa doing now? — A: He is watching TV in the living room.","t":"爺爺現在在做什麼？ — 他正在客廳看電視。"},{"w":"listen (listening)","p":"v.","d":"","c":"聽","s":"Q: What is Amy doing in her room? — A: She is listening to music.","t":"艾美在她房間做什麼？ — 她正在聽音樂。"},{"w":"carry (carrying)","p":"v.","d":"","c":"搬；攜帶","s":"Q: What is Dad doing? — A: He is carrying a big box into the house.","t":"爸爸在做什麼？ — 他正把一個大箱子搬進屋裡。"},{"w":"catch (catching)","p":"v.","d":"","c":"接住；抓","s":"Q: What is your dog doing in the park? — A: It is catching a ball.","t":"你的狗在公園做什麼？ — 牠正在接球。"},{"w":"clap (clapping)","p":"v.","d":"","c":"拍手","s":"Q: What are the fans doing? — A: They are clapping their hands for the team.","t":"球迷們在做什麼？ — 他們正在為球隊拍手。"},{"w":"brush (brushing)","p":"v.","d":"","c":"刷","s":"Q: What is your brother doing in the bathroom? — A: He is brushing his teeth.","t":"你弟弟在浴室做什麼？ — 他正在刷牙。"},{"w":"cut (cutting)","p":"v.","d":"","c":"切；剪","s":"Q: What is Mom doing in the kitchen? — A: She is cutting vegetables.","t":"媽媽在廚房做什麼？ — 她正在切菜。"},{"w":"fry (frying)","p":"v.","d":"","c":"油炸；煎","s":"Q: What is your uncle doing at the night market? — A: He is frying chicken.","t":"你叔叔在夜市做什麼？ — 他正在炸雞。"},{"w":"dig (digging)","p":"v.","d":"","c":"挖","s":"Q: What are the children doing on the beach? — A: They are digging in the sand.","t":"孩子們在海灘上做什麼？ — 他們正在挖沙。"},{"w":"cry (crying)","p":"v.","d":"","c":"哭","s":"Q: What is the baby doing? — A: She is crying. She is hungry.","t":"寶寶在做什麼？ — 她在哭，她餓了。"},{"w":"fight (fighting)","p":"v.","d":"","c":"打架；爭吵","s":"Q: What are those two boys doing? — A: They are fighting. Let's tell the teacher.","t":"那兩個男孩在做什麼？ — 他們在打架，我們去告訴老師吧。"},{"w":"see (saw)","p":"v.","d":"","c":"看見","s":"Q: What did you do at the zoo yesterday? — A: I saw a big elephant.","t":"你昨天在動物園做了什麼？ — 我看到一隻大象。"},{"w":"hear (heard)","p":"v.","d":"","c":"聽見","s":"Q: Why did you get up last night? — A: I heard a strange noise outside.","t":"你昨晚為什麼起床？ — 我聽到外面有奇怪的聲音。"},{"w":"notice (noticed)","p":"v.","d":"","c":"注意到","s":"Q: Did Amy look different yesterday? — A: Yes, she did. I noticed her new glasses.","t":"艾美昨天看起來不一樣嗎？ — 是的，我注意到她的新眼鏡。"},{"w":"forget (forgot)","p":"v.","d":"","c":"忘記","s":"Q: Why did Tom buy lunch at school yesterday? — A: He forgot his lunch box at home.","t":"湯姆昨天為什麼在學校買午餐？ — 他把便當忘在家裡了。"},{"w":"go (went)","p":"v.","d":"","c":"去","s":"Q: What did you do last Sunday? — A: I went to the beach with my family.","t":"你上星期日做了什麼？ — 我和家人去了海邊。"},{"w":"come (came)","p":"v.","d":"","c":"來","s":"Q: Did Uncle Jack visit you yesterday? — A: Yes, he did. He came to our house for dinner.","t":"傑克叔叔昨天有來看你們嗎？ — 有，他來我們家吃晚餐。"},{"w":"bring (brought)","p":"v.","d":"","c":"帶來","s":"Q: Did you have food for the picnic yesterday? — A: Yes, I did. I brought some sandwiches.","t":"你昨天野餐有帶食物嗎？ — 有，我帶了一些三明治。"},{"w":"break (broke)","p":"v.","d":"","c":"打破","s":"Q: What did Tom do yesterday? — A: He broke the window with his ball.","t":"湯姆昨天做了什麼？ — 他用球打破了窗戶。"},{"w":"drop (dropped)","p":"v.","d":"","c":"（使）掉落","s":"Q: What happened to your phone? — A: I dropped it on the floor yesterday.","t":"你的手機怎麼了？ — 我昨天把它摔到地上。"},{"w":"finish (finished)","p":"v.","d":"","c":"完成","s":"Q: Did Ben do his homework last night? — A: Yes, he did. He finished it at nine.","t":"班昨晚有寫功課嗎？ — 有，他九點寫完了。"},{"w":"end (ended)","p":"v.","d":"","c":"結束","s":"Q: Was the movie long last night? — A: Yes. It ended at eleven o'clock.","t":"昨晚的電影很長嗎？ — 是的，它十一點才結束。"},{"w":"check","p":"v.","d":"","c":"檢查","s":"Q: What will Dad do before the trip tomorrow? — A: He will check the car.","t":"爸爸明天旅行前會做什麼？ — 他會檢查車子。"},{"w":"correct","p":"v.","d":"","c":"改正","s":"Q: What will you do with your mistakes? — A: I will correct them.","t":"你會怎麼處理你的錯誤？ — 我會改正它們。"},{"w":"choose","p":"v.","d":"","c":"選擇；挑選","s":"Q: Which cake will you have, chocolate or strawberry? — A: I will choose the chocolate one.","t":"你要哪一個蛋糕，巧克力還是草莓？ — 我會選巧克力的。"},{"w":"cover","p":"v.","d":"","c":"覆蓋；蓋住","s":"Q: It will rain tomorrow. What will you do with your bike? — A: I will cover it.","t":"明天會下雨，你會怎麼處理你的腳踏車？ — 我會把它蓋起來。"},{"w":"surprise","p":"v.","d":"","c":"使驚訝；給…驚喜","s":"Q: What will you do for Mom's birthday tomorrow? — A: We will surprise her with a big cake.","t":"明天媽媽生日你們會做什麼？ — 我們會用一個大蛋糕給她驚喜。"},{"w":"guess","p":"v.","d":"","c":"猜","s":"Q: Can you guess my age? — A: Yes. I think you are thirteen.","t":"你能猜出我的年齡嗎？ — 能，我想你十三歲。"},{"w":"define","p":"v.","d":"","c":"解釋；給…下定義","s":"Q: Can you define this word in English? — A: Yes. \"Glad\" means \"happy.\"","t":"你能用英文解釋這個字嗎？ — 可以，glad 的意思是 happy（高興的）。"},{"w":"count","p":"v.","d":"","c":"數；計算","s":"Q: Can your little sister count to one hundred? — A: Yes, she can. She is very smart.","t":"你妹妹能數到一百嗎？ — 能，她很聰明。"},{"w":"copy","p":"v.","d":"","c":"抄寫；複製","s":"Q: I was sick yesterday. Can I copy your notes? — A: Sure. Here you are.","t":"我昨天生病了，我可以抄你的筆記嗎？ — 當然，給你。"},{"w":"close","p":"v.","d":"","c":"關上","s":"Q: It's cold. Can you close the window, please? — A: Sure.","t":"好冷，你可以關上窗戶嗎？ — 好的。"},{"w":"enter","p":"v.","d":"","c":"進入","s":"Q: Can I come in? — A: Yes, but please knock before you enter the room.","t":"我可以進來嗎？ — 可以，但進房間前請先敲門。"},{"w":"follow","p":"v.","d":"","c":"跟隨；遵循","s":"Q: Can you show me the way to the library? — A: Sure. Follow me.","t":"你可以帶我去圖書館嗎？ — 當然，跟我來。"},{"w":"blow","p":"v.","d":"","c":"吹","s":"Q: Can I eat the cake now? — A: Not yet. Make a wish and blow out the candles first.","t":"我現在可以吃蛋糕了嗎？ — 還不行，先許願然後吹熄蠟燭。"},{"w":"cheat","p":"v.","d":"","c":"作弊；欺騙","s":"Q: Can I look at your answers? — A: No! Don't cheat on the test.","t":"我可以看你的答案嗎？ — 不行！考試不要作弊。"},{"w":"worry","p":"v.","d":"","c":"擔心","s":"Q: Can you help me? I can't find my dog. — A: Sure. Don't worry. We can find it.","t":"你可以幫我嗎？我找不到我的狗。 — 當然，別擔心，我們找得到牠。"}]},{"unit":36,"theme":"Other Verbs (Part 2) 其他動詞（中）（第35中區）","cards":[{"w":"rise (rises)","p":"v.","d":"","c":"升起；上升","s":"Q: Where does the sun come up every morning? — A: It rises in the east.","t":"太陽每天早上從哪裡出來？ — 它從東方升起。"},{"w":"grow","p":"v.","d":"","c":"種植；生長","s":"Q: Do your grandparents have a farm? — A: Yes, they do. They grow rice and vegetables.","t":"你的祖父母有農場嗎？ — 有，他們種稻米和蔬菜。"},{"w":"plant","p":"v.","d":"","c":"種植；栽種","s":"Q: What do the students do on Arbor Day? — A: They plant trees.","t":"學生們在植樹節做什麼？ — 他們種樹。"},{"w":"make (makes)","p":"v.","d":"","c":"製作；做","s":"Q: What does your aunt do on weekends? — A: She makes cakes and cookies.","t":"你阿姨週末做什麼？ — 她做蛋糕和餅乾。"},{"w":"use","p":"v.","d":"","c":"使用","s":"Q: What do you use to cut paper? — A: I use scissors.","t":"你用什麼剪紙？ — 我用剪刀。"},{"w":"help (helps)","p":"v.","d":"","c":"幫忙","s":"Q: How does Ben help his mom at home? — A: He helps her wash the dishes.","t":"班在家怎麼幫媽媽？ — 他幫她洗碗。"},{"w":"walk","p":"v.","d":"","c":"走路","s":"Q: How do you and your sister go to school? — A: We walk to school. It's near.","t":"你和你妹妹怎麼上學？ — 我們走路上學，學校很近。"},{"w":"leave (leaves)","p":"v.","d":"","c":"離開；出發","s":"Q: When does your dad leave for work? — A: He leaves home at seven.","t":"你爸爸什麼時候去上班？ — 他七點離開家。"},{"w":"park (parks)","p":"v.","d":"","c":"停（車）","s":"Q: Where does your uncle put his car at night? — A: He parks it in front of his house.","t":"你叔叔晚上把車放在哪裡？ — 他把車停在他家前面。"},{"w":"open","p":"v.","d":"","c":"打開；開門（營業）","s":"Q: What time do the stores on this street open? — A: They open at ten in the morning.","t":"這條街的商店幾點開門？ — 它們早上十點開門。"},{"w":"meet","p":"v.","d":"","c":"和…見面；遇見","s":"Q: Where do you and your friends meet after school? — A: We meet at the park.","t":"你和朋友放學後在哪裡碰面？ — 我們在公園碰面。"},{"w":"call (calls)","p":"v.","d":"","c":"打電話（給）","s":"Q: Does Lisa talk to her grandma every day? — A: Yes, she does. She calls her every evening.","t":"麗莎每天都和奶奶說話嗎？ — 是的，她每天晚上打電話給她。"},{"w":"miss (misses)","p":"v.","d":"","c":"想念；錯過","s":"Q: Does Grandpa often talk about his hometown? — A: Yes, he does. He misses it very much.","t":"爺爺常常談起他的家鄉嗎？ — 是的，他非常想念那裡。"},{"w":"belong (belongs)","p":"v.","d":"","c":"屬於","s":"Q: Does this pen belong to you? — A: No, it doesn't. It belongs to Amy.","t":"這支筆是你的嗎？ — 不是，它是艾美的。"},{"w":"agree","p":"v.","d":"","c":"同意","s":"Q: Tom says the movie is great. Do you agree with him? — A: Yes, I do. I like it, too.","t":"湯姆說這部電影很棒，你同意他嗎？ — 同意，我也喜歡。"},{"w":"allow","p":"v.","d":"","c":"允許","s":"Q: Do your parents allow you to play games at night? — A: No, they don't. I have to go to bed at ten.","t":"你爸媽允許你晚上玩遊戲嗎？ — 不，他們不允許，我十點就得睡覺。"},{"w":"run (running)","p":"v.","d":"","c":"跑","s":"Q: What is your dog doing in the yard? — A: It is running after a ball.","t":"你的狗在院子裡做什麼？ — 牠正在追著一顆球跑。"},{"w":"jump (jumping)","p":"v.","d":"","c":"跳","s":"Q: What are the kids doing in the bedroom? — A: They are jumping on the bed.","t":"孩子們在臥室做什麼？ — 他們正在床上跳。"},{"w":"stand (standing)","p":"v.","d":"","c":"站；站立","s":"Q: What are the students doing at the bus stop? — A: They are standing in line.","t":"學生們在公車站做什麼？ — 他們正在排隊站著。"},{"w":"kick (kicking)","p":"v.","d":"","c":"踢","s":"Q: What is Tom doing on the playground? — A: He is kicking a ball.","t":"湯姆在操場上做什麼？ — 他正在踢球。"},{"w":"hit (hitting)","p":"v.","d":"","c":"打；擊","s":"Q: What is the baseball player doing? — A: He is hitting the ball with a bat.","t":"那位棒球員在做什麼？ — 他正在用球棒擊球。"},{"w":"pull (pulling)","p":"v.","d":"","c":"拉","s":"Q: What are the two teams doing? — A: They are pulling a long rope.","t":"兩隊在做什麼？ — 他們正在拉一條長繩子。"},{"w":"push (pushing)","p":"v.","d":"","c":"推","s":"Q: What is Dad doing? — A: He is pushing his bike up the hill.","t":"爸爸在做什麼？ — 他正把腳踏車推上山坡。"},{"w":"hold (holding)","p":"v.","d":"","c":"抱著；拿著","s":"Q: What is Aunt May doing? — A: She is holding her baby.","t":"梅阿姨在做什麼？ — 她正抱著她的寶寶。"},{"w":"hang (hanging)","p":"v.","d":"","c":"掛；懸掛","s":"Q: What is Mom doing on the balcony? — A: She is hanging the clothes.","t":"媽媽在陽台做什麼？ — 她正在晾衣服。"},{"w":"mop (mopping)","p":"v.","d":"","c":"拖（地）","s":"Q: What is Grandma doing in the kitchen? — A: She is mopping the floor.","t":"奶奶在廚房做什麼？ — 她正在拖地。"},{"w":"knock (knocking)","p":"v.","d":"","c":"敲","s":"Q: What is that man doing? — A: He is knocking on the door.","t":"那個男人在做什麼？ — 他正在敲門。"},{"w":"shake (shaking)","p":"v.","d":"","c":"搖動；握（手）","s":"Q: What are the two players doing after the game? — A: They are shaking hands.","t":"比賽後兩位選手在做什麼？ — 他們正在握手。"},{"w":"wave (waving)","p":"v.","d":"","c":"揮手","s":"Q: What is Lisa doing at the school gate? — A: She is waving goodbye to her friends.","t":"麗莎在校門口做什麼？ — 她正在向朋友揮手道別。"},{"w":"kiss (kissing)","p":"v.","d":"","c":"親吻","s":"Q: What is the mother doing? — A: She is kissing her baby good night.","t":"那位媽媽在做什麼？ — 她正在親吻寶寶道晚安。"},{"w":"laugh (laughing)","p":"v.","d":"","c":"笑","s":"Q: Why are the students so noisy? — A: They are laughing at a funny joke.","t":"學生們為什麼那麼吵？ — 他們正在聽一個好笑的笑話大笑。"},{"w":"take (took)","p":"v.","d":"","c":"帶；拿","s":"Q: What did you do last Sunday? — A: I took my dog to the park.","t":"你上星期日做了什麼？ — 我帶我的狗去公園。"},{"w":"put (put)","p":"v.","d":"","c":"放","s":"Q: Where did you put my book? — A: I put it on your desk.","t":"你把我的書放在哪裡？ — 我把它放在你的書桌上。"},{"w":"throw (threw)","p":"v.","d":"","c":"丟；扔","s":"Q: What did Tom do with the ball? — A: He threw it to his dog.","t":"湯姆把球怎麼了？ — 他把球丟給他的狗。"},{"w":"roll (rolled)","p":"v.","d":"","c":"滾動","s":"Q: What happened to your ball? — A: It rolled down the hill.","t":"你的球怎麼了？ — 它滾下山坡了。"},{"w":"pick (picked)","p":"v.","d":"","c":"摘；撿","s":"Q: What did you do on the farm yesterday? — A: We picked strawberries.","t":"你們昨天在農場做了什麼？ — 我們摘了草莓。"},{"w":"pack (packed)","p":"v.","d":"","c":"打包；收拾（行李）","s":"Q: Did you get ready for the trip last night? — A: Yes, I did. I packed my bag.","t":"你昨晚有為旅行做好準備嗎？ — 有，我打包好我的包包了。"},{"w":"move (moved)","p":"v.","d":"","c":"搬家；移動","s":"Q: Did Amy's family move last year? — A: Yes, they did. They moved to Taipei.","t":"艾美家去年搬家了嗎？ — 是的，他們搬到台北了。"},{"w":"tell (told)","p":"v.","d":"","c":"告訴；講","s":"Q: What did Grandma do last night? — A: She told us a story.","t":"奶奶昨晚做了什麼？ — 她講了一個故事給我們聽。"},{"w":"begin (began)","p":"v.","d":"","c":"開始","s":"Q: When did the movie begin last night? — A: It began at seven.","t":"昨晚的電影幾點開始？ — 它七點開始。"},{"w":"appear (appeared)","p":"v.","d":"","c":"出現","s":"Q: Did you see a rainbow yesterday? — A: Yes, I did. It appeared after the rain.","t":"你昨天有看到彩虹嗎？ — 有，它在雨後出現。"},{"w":"hunt (hunted)","p":"v.","d":"","c":"打獵","s":"Q: What did people do for food long ago? — A: They hunted animals.","t":"很久以前人們怎麼取得食物？ — 他們打獵。"},{"w":"attack (attacked)","p":"v.","d":"","c":"攻擊","s":"Q: What happened to your cat yesterday? — A: A big dog attacked it, but it's OK now.","t":"你的貓昨天怎麼了？ — 一隻大狗攻擊牠，但牠現在沒事了。"},{"w":"kill (killed)","p":"v.","d":"","c":"殺死","s":"Q: What did Dad do in the kitchen last night? — A: He killed a big bug.","t":"爸爸昨晚在廚房做了什麼？ — 他打死了一隻大蟲。"},{"w":"become","p":"v.","d":"","c":"成為；變成","s":"Q: Will your brother be a doctor? — A: Yes, he will. He will become a doctor next year.","t":"你哥哥會成為醫生嗎？ — 會，他明年會成為醫生。"},{"w":"rest","p":"v.","d":"","c":"休息","s":"Q: What will you do after the long walk? — A: I will rest at home.","t":"走了很長的路之後你會做什麼？ — 我會在家休息。"},{"w":"list","p":"v.","d":"","c":"列出；列清單","s":"Q: What will you do before you go shopping? — A: I will list the things I need.","t":"你去買東西之前會做什麼？ — 我會把需要的東西列出來。"},{"w":"sign","p":"v.","d":"","c":"簽（名）","s":"Q: Will your mom look at your test? — A: Yes, she will. She will sign her name on it.","t":"你媽媽會看你的考卷嗎？ — 會，她會在上面簽名。"},{"w":"paste","p":"v.","d":"","c":"黏貼","s":"Q: What will you do with these photos? — A: I will paste them in my notebook.","t":"你會怎麼處理這些照片？ — 我會把它們貼在筆記本裡。"},{"w":"hand","p":"v.","d":"","c":"傳遞；拿給","s":"Q: Can you hand me the salt, please? — A: Sure. Here you are.","t":"你可以把鹽遞給我嗎？ — 當然，給你。"},{"w":"type","p":"v.","d":"","c":"打字","s":"Q: Can you type fast on the computer? — A: Yes, I can. I use it every day.","t":"你在電腦上打字很快嗎？ — 是的，我每天都用電腦。"},{"w":"hurry","p":"v.","d":"","c":"趕快；匆忙","s":"Q: Can I finish my breakfast first? — A: No. Hurry up! The bus is coming.","t":"我可以先吃完早餐嗎？ — 不行，快點！公車要來了。"},{"w":"touch","p":"v.","d":"","c":"碰；觸摸","s":"Q: Can I hold the pot? — A: No! Don't touch it. It's very hot.","t":"我可以拿那個鍋子嗎？ — 不行！別碰它，它很燙。"},{"w":"shout","p":"v.","d":"","c":"大叫；喊叫","s":"Q: Can we play here? — A: Yes, but don't shout. The baby is sleeping.","t":"我們可以在這裡玩嗎？ — 可以，但不要大叫，寶寶在睡覺。"},{"w":"smoke","p":"v.","d":"","c":"抽菸","s":"Q: Can my uncle smoke in the restaurant? — A: No. Please don't smoke here.","t":"我叔叔可以在餐廳裡抽菸嗎？ — 不行，請不要在這裡抽菸。"}]},{"unit":37,"theme":"Other Verbs (Part 3) 其他動詞（下）（第35下區）","cards":[{"w":"care (cares)","p":"v.","d":"","c":"關心；在乎","s":"Q: Does Lisa care about her friends? — A: Yes, she does. She cares about them a lot.","t":"麗莎關心她的朋友嗎？ — 是的，她非常關心他們。"},{"w":"enjoy","p":"v.","d":"","c":"喜愛；享受","s":"Q: What do you and your friends do on weekends? — A: We enjoy playing basketball.","t":"你和朋友週末做什麼？ — 我們喜歡打籃球。"},{"w":"own (owns)","p":"v.","d":"","c":"擁有","s":"Q: Does your uncle have a farm? — A: Yes, he does. He owns a big farm in the country.","t":"你叔叔有農場嗎？ — 有，他在鄉下擁有一座大農場。"},{"w":"pray (prays)","p":"v.","d":"","c":"祈禱；拜拜","s":"Q: What does Grandma do at the temple? — A: She prays for our family.","t":"奶奶在廟裡做什麼？ — 她為我們家祈福。"},{"w":"sleep","p":"v.","d":"","c":"睡覺","s":"Q: When do you go to bed? — A: At ten. I sleep for eight hours.","t":"你幾點上床？ — 十點，我睡八個小時。"},{"w":"stay","p":"v.","d":"","c":"停留；待","s":"Q: What do you do on rainy days? — A: I stay at home and read.","t":"你下雨天做什麼？ — 我待在家看書。"},{"w":"visit (visits)","p":"v.","d":"","c":"拜訪；參觀","s":"Q: What does Ben do on Sundays? — A: He visits his grandparents.","t":"班星期日做什麼？ — 他去探望祖父母。"},{"w":"wake (wakes)","p":"v.","d":"","c":"醒來","s":"Q: When does your brother get up? — A: He wakes up at six every day.","t":"你哥哥幾點起床？ — 他每天六點醒來。"},{"w":"mean (means)","p":"v.","d":"","c":"意思是","s":"Q: Do you know the word \"glad\"? — A: Yes, I do. It means \"happy.\"","t":"你知道 glad 這個字嗎？ — 知道，它的意思是「高興」。"},{"w":"sell","p":"v.","d":"","c":"賣","s":"Q: What do the people at the market do? — A: They sell fruit and vegetables.","t":"市場裡的人做什麼？ — 他們賣水果和蔬菜。"},{"w":"keep (keeps)","p":"v.","d":"","c":"保存；保持","s":"Q: Where does Mom put the milk? — A: She keeps it in the fridge.","t":"媽媽把牛奶放在哪裡？ — 她把它保存在冰箱裡。"},{"w":"lead (leads)","p":"v.","d":"","c":"帶領；引導","s":"Q: What does the team leader do on the trip? — A: He leads the way.","t":"旅行時隊長做什麼？ — 他帶路。"},{"w":"share","p":"v.","d":"","c":"分享","s":"Q: What do you do with your cookies? — A: I share them with my friends.","t":"你怎麼處理你的餅乾？ — 我和朋友分享。"},{"w":"save","p":"v.","d":"","c":"存（錢）；救","s":"Q: Do you and your sister spend all your money? — A: No, we don't. We save it to buy a bike.","t":"你和妹妹會把錢都花光嗎？ — 不會，我們存錢買腳踏車。"},{"w":"start (starts)","p":"v.","d":"","c":"開始","s":"Q: When does your first class begin? — A: It starts at eight.","t":"你的第一堂課幾點開始？ — 它八點開始。"},{"w":"date (dates)","p":"v.","d":"","c":"和…約會","s":"Q: Does your big sister have a boyfriend? — A: Yes, she does. She dates Tom. They go to the movies on Saturdays.","t":"你姊姊有男朋友嗎？ — 有，她和湯姆約會，他們星期六去看電影。"},{"w":"expect","p":"v.","d":"","c":"期待；預期","s":"Q: Do you think you can do well on the test? — A: Yes, I do. I expect to get a good grade.","t":"你覺得你考試會考好嗎？ — 會，我期待拿到好成績。"},{"w":"sit (sitting)","p":"v.","d":"","c":"坐","s":"Q: What is Grandpa doing in the park? — A: He is sitting on a bench.","t":"爺爺在公園做什麼？ — 他正坐在長椅上。"},{"w":"lie (lying)","p":"v.","d":"","c":"躺","s":"Q: What is the cat doing? — A: It is lying in the sun.","t":"那隻貓在做什麼？ — 牠正躺在陽光下。"},{"w":"hide (hiding)","p":"v.","d":"","c":"躲藏；隱藏","s":"Q: What are the kids doing behind the door? — A: They are hiding from their mom.","t":"孩子們在門後做什麼？ — 他們正在躲媽媽。"},{"w":"hop (hopping)","p":"v.","d":"","c":"跳；單腳跳","s":"Q: What is the rabbit doing in the garden? — A: It is hopping around.","t":"兔子在花園裡做什麼？ — 牠正在跳來跳去。"},{"w":"wait (waiting)","p":"v.","d":"","c":"等待","s":"Q: What are you doing at the bus stop? — A: I'm waiting for the bus.","t":"你在公車站做什麼？ — 我正在等公車。"},{"w":"prepare (preparing)","p":"v.","d":"","c":"準備","s":"Q: What is Mom doing in the kitchen? — A: She is preparing dinner.","t":"媽媽在廚房做什麼？ — 她正在準備晚餐。"},{"w":"plan (planning)","p":"v.","d":"","c":"計畫","s":"Q: What are your parents doing? — A: They are planning a trip to Japan.","t":"你爸媽在做什麼？ — 他們正在計畫去日本旅行。"},{"w":"fill (filling)","p":"v.","d":"","c":"裝滿","s":"Q: What is Dad doing with the bottle? — A: He is filling it with water.","t":"爸爸在用瓶子做什麼？ — 他正在把它裝滿水。"},{"w":"show (showing)","p":"v.","d":"","c":"給…看；展示","s":"Q: What is Amy doing? — A: She is showing her new bike to her friends.","t":"艾美在做什麼？ — 她正在給朋友看她的新腳踏車。"},{"w":"upload (uploading)","p":"v.","d":"","c":"上傳","s":"Q: What is your sister doing on the computer? — A: She is uploading her photos to the Internet.","t":"你妹妹在電腦上做什麼？ — 她正在把照片上傳到網路。"},{"w":"download (downloading)","p":"v.","d":"","c":"下載","s":"Q: What is Ben doing with his cellphone? — A: He is downloading a new game.","t":"班在用手機做什麼？ — 他正在下載一個新遊戲。"},{"w":"find (found)","p":"v.","d":"","c":"找到","s":"Q: Where was your key? — A: I found it under the bed.","t":"你的鑰匙在哪裡？ — 我在床底下找到它。"},{"w":"get (got)","p":"v.","d":"","c":"得到；收到","s":"Q: What was your birthday present? — A: I got a new watch.","t":"你的生日禮物是什麼？ — 我收到一支新手錶。"},{"w":"give (gave)","p":"v.","d":"","c":"給","s":"Q: What did Tom do on Mother's Day? — A: He gave his mom a card.","t":"湯姆在母親節做了什麼？ — 他給媽媽一張卡片。"},{"w":"send (sent)","p":"v.","d":"","c":"寄；送","s":"Q: What did you do at the post office yesterday? — A: I sent a letter to my grandma.","t":"你昨天在郵局做了什麼？ — 我寄了一封信給奶奶。"},{"w":"invite (invited)","p":"v.","d":"","c":"邀請","s":"Q: Who did Lisa ask to her party last week? — A: She invited all her classmates.","t":"麗莎上週請誰去她的派對？ — 她邀請了全班同學。"},{"w":"join (joined)","p":"v.","d":"","c":"加入","s":"Q: Did Ben become a club member last year? — A: Yes, he did. He joined the music club.","t":"班去年有成為社團成員嗎？ — 有，他加入了音樂社。"},{"w":"reach (reached)","p":"v.","d":"","c":"到達；伸手拿到","s":"Q: When did you get to the top of the mountain? — A: We reached the top at noon.","t":"你們什麼時候到山頂的？ — 我們中午到達山頂。"},{"w":"fall (fell)","p":"v.","d":"","c":"跌倒；落下","s":"Q: Why did you go to the nurse's office yesterday? — A: I fell down on the playground.","t":"你昨天為什麼去保健室？ — 我在操場上跌倒了。"},{"w":"hurt (hurt)","p":"v.","d":"","c":"弄傷；受傷","s":"Q: What's wrong with your knee? — A: I hurt it in PE class yesterday.","t":"你的膝蓋怎麼了？ — 我昨天上體育課時弄傷了它。"},{"w":"happen (happened)","p":"v.","d":"","c":"發生","s":"Q: What happened to your bike last night? — A: A car hit it.","t":"你的腳踏車昨晚發生了什麼事？ — 被一輛車撞了。"},{"w":"die (died)","p":"v.","d":"","c":"死","s":"Q: Do you still have your fish? — A: No, I don't. It died last week.","t":"你還有養那條魚嗎？ — 沒有，牠上週死了。"},{"w":"disappear (disappeared)","p":"v.","d":"","c":"消失","s":"Q: Where is the cake on the table? — A: I don't know. It disappeared this morning!","t":"桌上的蛋糕在哪裡？ — 我不知道，它今天早上不見了！"},{"w":"lay (laid)","p":"v.","d":"","c":"下（蛋）；放置","s":"Q: What did the hen do this morning? — A: It laid two eggs.","t":"那隻母雞今天早上做了什麼？ — 牠下了兩顆蛋。"},{"w":"lie (lied)","p":"v.","d":"","c":"說謊","s":"Q: Why is Mom angry with Tom? — A: Because he lied to her yesterday.","t":"媽媽為什麼生湯姆的氣？ — 因為他昨天對她說謊。"},{"w":"decide","p":"v.","d":"","c":"決定","s":"Q: Will you buy the red bag or the blue bag? — A: I don't know. I will decide later.","t":"你會買紅色還是藍色的包包？ — 我不知道，我等一下再決定。"},{"w":"deal","p":"v.","d":"","c":"處理（deal with）","s":"Q: Who will help with this problem? — A: Don't worry. I will deal with it.","t":"誰會幫忙處理這個問題？ — 別擔心，我會處理。"},{"w":"explain","p":"v.","d":"","c":"解釋","s":"Q: Will the teacher talk about the new words tomorrow? — A: Yes, she will. She will explain them to us.","t":"老師明天會講新單字嗎？ — 會，她會跟我們解釋。"},{"w":"treat","p":"v.","d":"","c":"請客；對待","s":"Q: What will you do for your mom on her birthday? — A: I will treat her to dinner.","t":"媽媽生日那天你會為她做什麼？ — 我會請她吃晚餐。"},{"w":"raise","p":"v.","d":"","c":"舉起；養育","s":"Q: What will you do if you know the answer? — A: I will raise my hand.","t":"如果你知道答案你會做什麼？ — 我會舉手。"},{"w":"please","p":"v.","d":"","c":"使高興；取悅","s":"Q: Can you please everyone? — A: No, I can't. That's too hard.","t":"你能讓每個人都高興嗎？ — 不行，那太難了。"},{"w":"thank","p":"v.","d":"","c":"感謝","s":"Q: What do you say when someone helps you? — A: Thank you very much.","t":"有人幫你時你會說什麼？ — 非常謝謝你。"},{"w":"welcome","p":"v.","d":"","c":"歡迎","s":"Q: What does the teacher say to the new students? — A: She says, \"welcome to our school!\"","t":"老師對新生說什麼？ — 她說：「歡迎來到我們學校！」"},{"w":"excuse","p":"v.","d":"","c":"原諒（Excuse me.）","s":"Q: How do you ask a stranger for help? — A: Excuse me. Can you help me?","t":"你怎麼向陌生人求助？ — 不好意思，你可以幫我嗎？"},{"w":"cheer up","p":"phr.","d":"","c":"打起精神；振作","s":"Q: My dog is sick. I'm so sad. — A: Cheer up! It will be OK.","t":"我的狗生病了，我好難過。 — 打起精神！會沒事的。"},{"w":"nod","p":"v.","d":"","c":"點頭","s":"Q: Can you say \"yes\" without words? — A: Yes, I can. I can nod my head.","t":"你可以不說話表示「是」嗎？ — 可以，我可以點頭。"},{"w":"stop","p":"v.","d":"","c":"停止；停","s":"Q: The light is red. Can we cross the street? — A: No. Stop! Wait for the green light.","t":"紅燈了，我們可以過馬路嗎？ — 不行，停！等綠燈。"},{"w":"try","p":"v.","d":"","c":"嘗試；試","s":"Q: Can I have some of your cake? — A: Sure. Try it. It's yummy.","t":"我可以吃一點你的蛋糕嗎？ — 當然，試試看，很好吃。"},{"w":"let","p":"v.","d":"","c":"讓","s":"Q: Mom, can you help me with this heavy box? — A: Sure. Let me carry it for you.","t":"媽，你可以幫我搬這個重箱子嗎？ — 當然，讓我幫你搬。"}]},{"unit":38,"theme":"Other Adjectives 其他形容詞（第36區）","cards":[{"w":"bright","p":"adj.","d":"","c":"明亮的","s":"Q: How do the new classrooms look? — A: They look bright. They have big windows.","t":"新教室看起來怎麼樣？ — 看起來很明亮，它們有大窗戶。"},{"w":"dark","p":"adj.","d":"","c":"黑暗的","s":"Q: How do the classrooms look at night? — A: They look dark. All the lights are off.","t":"教室晚上看起來怎麼樣？ — 看起來很暗，燈都關了。"},{"w":"dirty","p":"adj.","d":"","c":"骯髒的","s":"Q: How do your shoes look after the soccer game? — A: They look dirty. There is mud on them.","t":"足球賽後你的鞋子看起來怎樣？ — 看起來很髒，上面有泥巴。"},{"w":"tidy","p":"adj.","d":"","c":"整潔的","s":"Q: How does Amy's desk look? — A: It looks tidy. Her books are in a row.","t":"艾美的書桌看起來怎樣？ — 看起來很整齊，她的書排成一排。"},{"w":"dead","p":"adj.","d":"","c":"死的","s":"Q: How do the flowers in the vase look? — A: They look dead. Nobody gave them water.","t":"花瓶裡的花看起來怎樣？ — 看起來枯死了，沒有人給它們澆水。"},{"w":"sharp","p":"adj.","d":"","c":"銳利的","s":"Q: How does the new knife look? — A: It looks sharp. Be careful!","t":"這把新刀看起來怎樣？ — 看起來很鋒利，小心！"},{"w":"thick","p":"adj.","d":"","c":"厚的","s":"Q: How does the dictionary look? — A: It looks very thick. It has 2,000 pages.","t":"那本字典看起來怎樣？ — 看起來很厚，它有兩千頁。"},{"w":"fresh","p":"adj.","d":"","c":"新鮮的","s":"Q: How do the vegetables at the market look? — A: They look fresh. The farmers picked them this morning.","t":"市場的蔬菜看起來怎樣？ — 看起來很新鮮，農夫今天早上採的。"},{"w":"terrible","p":"adj.","d":"","c":"很糟的","s":"Q: How does the old milk smell? — A: It smells terrible. Don't drink it!","t":"那瓶過期的牛奶聞起來怎樣？ — 聞起來很糟，別喝！"},{"w":"great","p":"adj.","d":"","c":"很棒的","s":"Q: How do the cookies taste? — A: They taste great! I want another one.","t":"這些餅乾吃起來怎樣？ — 很好吃！我還想再吃一塊。"},{"w":"fine","p":"adj.","d":"","c":"很好的","s":"Q: How do you feel today? — A: I feel fine, thank you.","t":"你今天覺得怎樣？ — 我覺得很好，謝謝。"},{"w":"loud","p":"adj.","d":"","c":"大聲的","s":"Q: How does the music next door sound? — A: It sounds very loud. I can't sleep.","t":"隔壁的音樂聽起來怎樣？ — 聽起來很大聲，我睡不著。"},{"w":"noisy","p":"adj.","d":"","c":"吵鬧的","s":"Q: How do the kids in the classroom sound? — A: They sound noisy. They are talking and laughing.","t":"教室裡的孩子們聽起來怎樣？ — 聽起來很吵，他們在說笑。"},{"w":"quiet","p":"adj.","d":"","c":"安靜的","s":"Q: How does the library sound? — A: It sounds quiet. Everyone is reading.","t":"圖書館聽起來怎樣？ — 聽起來很安靜，大家都在看書。"},{"w":"strange","p":"adj.","d":"","c":"奇怪的","s":"Q: How does the car sound today? — A: It sounds strange. Dad should check it.","t":"車子今天聽起來怎樣？ — 聽起來怪怪的，爸爸應該檢查一下。"},{"w":"wonderful","p":"adj.","d":"","c":"極好的","s":"Q: How does Lisa's singing sound? — A: It sounds wonderful! She sings like a star.","t":"麗莎的歌聲聽起來怎樣？ — 聽起來好極了！她唱得像明星一樣。"},{"w":"easy","p":"adj.","d":"","c":"容易的","s":"Q: Is the English test easy or hard? — A: It's easy. I can answer all the questions.","t":"英文考試簡單還是難？ — 很簡單，我每一題都會答。"},{"w":"simple","p":"adj.","d":"","c":"簡單的","s":"Q: Is the game simple or difficult? — A: It's simple. Even my little brother can play it.","t":"這個遊戲簡單還是困難？ — 很簡單，連我弟弟都會玩。"},{"w":"hard","p":"adj.","d":"","c":"困難的；硬的","s":"Q: Is the bread soft or hard? — A: It's hard. It's three days old.","t":"這麵包是軟的還是硬的？ — 是硬的，它放三天了。"},{"w":"correct","p":"adj.","d":"","c":"正確的","s":"Q: Is my answer correct or wrong? — A: It's correct. Good job!","t":"我的答案是對的還是錯的？ — 是正確的，做得好！"},{"w":"right","p":"adj.","d":"","c":"對的","s":"Q: Is it right or wrong to help old people? — A: It's right. We should help them.","t":"幫助老人是對的還是錯的？ — 是對的，我們應該幫助他們。"},{"w":"wrong","p":"adj.","d":"","c":"錯誤的","s":"Q: Is \"Tom have a dog\" right or wrong? — A: It's wrong. We say \"Tom has a dog.\"","t":"「Tom have a dog」是對的還是錯的？ — 是錯的，要說「Tom has a dog」。"},{"w":"true","p":"adj.","d":"","c":"真實的","s":"Q: Is the story true or not? — A: It's true. It happened to my grandpa.","t":"這個故事是真的嗎？ — 是真的，發生在我爺爺身上。"},{"w":"real","p":"adj.","d":"","c":"真正的","s":"Q: Is that a real flower or a paper flower? — A: It's a real flower. It smells sweet.","t":"那是真花還是紙花？ — 是真花，聞起來很香。"},{"w":"safe","p":"adj.","d":"","c":"安全的","s":"Q: Is it safe or dangerous to swim in this river? — A: It's safe. The water isn't deep.","t":"在這條河游泳安全還是危險？ — 很安全，水不深。"},{"w":"free","p":"adj.","d":"","c":"免費的","s":"Q: Is the ticket free or expensive? — A: It's free. You don't have to pay.","t":"票是免費的還是很貴？ — 是免費的，你不用付錢。"},{"w":"same","p":"adj.","d":"","c":"相同的","s":"Q: Are you and Ben in the same class or different classes? — A: We are in the same class.","t":"你和班同班還是不同班？ — 我們同一班。"},{"w":"different","p":"adj.","d":"","c":"不同的","s":"Q: Are the two pictures the same or different? — A: They are different. One cat is black, and the other is white.","t":"這兩張圖一樣還是不一樣？ — 不一樣，一隻貓是黑的，另一隻是白的。"},{"w":"common","p":"adj.","d":"","c":"常見的","s":"Q: Is \"Chen\" a common name or a special name in Taiwan? — A: It's a common name. Many people have it.","t":"「陳」在臺灣是常見還是特別的姓？ — 是常見的姓，很多人姓陳。"},{"w":"public","p":"adj.","d":"","c":"公立的","s":"Q: Does your sister go to a public school or a private school? — A: She goes to a public school.","t":"你妹妹讀公立還是私立學校？ — 她讀公立學校。"},{"w":"foreign","p":"adj.","d":"","c":"外國的","s":"Q: Is Mr. Smith a Taiwanese teacher or a foreign teacher? — A: He is a foreign teacher. He comes from Canada.","t":"史密斯先生是臺灣老師還是外國老師？ — 他是外籍老師，他來自加拿大。"},{"w":"lucky","p":"adj.","d":"","c":"幸運的","s":"Q: I won the first prize! — A: How lucky you are!","t":"我贏得頭獎了！ — 你真幸運！"},{"w":"helpful","p":"adj.","d":"","c":"有幫助的","s":"Q: Tom always helps the old lady carry her bags. — A: How helpful he is!","t":"湯姆總是幫那位老太太提袋子。 — 他真熱心助人！"},{"w":"useful","p":"adj.","d":"","c":"有用的","s":"Q: This dictionary has pictures and easy sentences. — A: How useful it is!","t":"這本字典有圖片和簡單的句子。 — 它真有用！"},{"w":"convenient","p":"adj.","d":"","c":"方便的","s":"Q: There is a supermarket next to my home. — A: How convenient! You can buy food any time.","t":"我家隔壁有一家超市。 — 真方便！你隨時都能買食物。"},{"w":"excellent","p":"adj.","d":"","c":"極好的","s":"Q: Amy got 100 on the math test. — A: What an excellent student she is!","t":"艾美數學考了一百分。 — 她真是個優秀的學生！"},{"w":"serious","p":"adj.","d":"","c":"嚴重的","s":"Q: The typhoon broke many trees and houses. — A: How serious it is!","t":"颱風弄壞了很多樹和房子。 — 真嚴重！"},{"w":"magic","p":"adj.","d":"","c":"魔術的","s":"Q: The man turns a piece of paper into a bird. — A: What a cool magic trick!","t":"那個人把一張紙變成一隻鳥。 — 好酷的魔術！"},{"w":"pop","p":"adj.","d":"","c":"流行的","s":"Q: Listen! Everyone is singing this new song. — A: What a great pop song!","t":"聽！大家都在唱這首新歌。 — 好棒的流行歌！"},{"w":"modern","p":"adj.","d":"","c":"現代的","s":"Q: Look at the new train station. — A: What a modern building!","t":"看那個新火車站。 — 好現代化的建築！"},{"w":"difficult","p":"adj.","d":"","c":"困難的","s":"Q: Which subject do you think is more difficult, math or English? — A: Math is more difficult than English for me.","t":"你覺得數學和英文哪一科比較難？ — 對我來說數學比英文難。"},{"w":"dangerous","p":"adj.","d":"","c":"危險的","s":"Q: Which animal does Ben think is more dangerous, a lion or a cat? — A: He thinks a lion is more dangerous than a cat.","t":"班覺得獅子和貓哪一個比較危險？ — 他覺得獅子比貓危險。"},{"w":"interesting","p":"adj.","d":"","c":"有趣的","s":"Q: Which does Lisa think is more interesting, comic books or movies? — A: She thinks comic books are more interesting than movies.","t":"麗莎覺得漫畫和電影哪個比較有趣？ — 她覺得漫畫比電影有趣。"},{"w":"important","p":"adj.","d":"","c":"重要的","s":"Q: What do you think is the most important thing in life? — A: I think health is the most important thing.","t":"你覺得人生中最重要的是什麼？ — 我覺得健康是最重要的。"},{"w":"popular","p":"adj.","d":"","c":"受歡迎的","s":"Q: Which sport is the most popular in your class? — A: Basketball is the most popular of all.","t":"你們班最受歡迎的運動是什麼？ — 籃球是所有運動中最受歡迎的。"},{"w":"special","p":"adj.","d":"","c":"特別的","s":"Q: Which day is the most special to you? — A: My birthday is the most special day of the year.","t":"對你來說哪一天最特別？ — 我的生日是一年中最特別的一天。"},{"w":"new (newer)","p":"adj.","d":"","c":"新的","s":"Q: Whose bike is newer, yours or Tom's? — A: Tom's bike is newer than mine.","t":"誰的腳踏車比較新，你的還是湯姆的？ — 湯姆的腳踏車比我的新。"},{"w":"latest","p":"adj.","d":"","c":"最新的","s":"Q: Does your brother have an old cellphone? — A: No, he doesn't. He has the latest one. It came out last week.","t":"你哥哥的手機是舊的嗎？ — 不是，他有最新的那款，上週才推出。"},{"w":"able","p":"adj.","d":"","c":"能夠…的","s":"Q: Is your baby brother able to walk? — A: Yes, he is. He is able to walk now.","t":"你的小弟弟會走路了嗎？ — 會，他現在會走路了。"},{"w":"afraid","p":"adj.","d":"","c":"害怕的","s":"Q: Does Lisa like snakes? — A: No, she doesn't. She is afraid of them.","t":"麗莎喜歡蛇嗎？ — 不喜歡，她怕蛇。"},{"w":"scared","p":"adj.","d":"","c":"害怕的","s":"Q: Do you like the dark? — A: No, I don't. I'm scared of the dark.","t":"你喜歡黑暗嗎？ — 不喜歡，我怕黑。"},{"w":"glad","p":"adj.","d":"","c":"高興的","s":"Q: How do you feel about your new school? — A: I'm glad to be here. Everyone is friendly.","t":"你覺得新學校怎麼樣？ — 我很高興來這裡，大家都很友善。"},{"w":"sorry","p":"adj.","d":"","c":"抱歉的","s":"Q: What does Tom say when he is late? — A: He says, \"I'm sorry I'm late.\"","t":"湯姆遲到時會說什麼？ — 他說：「抱歉我遲到了。」"},{"w":"sure","p":"adj.","d":"","c":"確定的","s":"Q: Does Ben know the answer? — A: Yes, he does. He is sure it's \"C.\"","t":"班知道答案嗎？ — 知道，他確定是 C。"},{"w":"surprised","p":"adj.","d":"","c":"感到驚訝的","s":"Q: How do your parents feel about your test? — A: They are surprised. It's my first 100!","t":"你爸媽對你的考試有什麼感覺？ — 他們很驚訝，這是我第一次考一百分！"},{"w":"ready","p":"adj.","d":"","c":"準備好的","s":"Q: Do the students have their books and pencils? — A: Yes, they do. They are ready for class.","t":"學生們都帶書和鉛筆了嗎？ — 有，他們準備好上課了。"},{"w":"OK","p":"adj.","d":"","c":"沒問題的","s":"Q: Does your leg still hurt? — A: No, it doesn't. I'm OK now.","t":"你的腿還痛嗎？ — 不痛了，我現在沒事了。"},{"w":"possible","p":"adj.","d":"","c":"可能的","s":"Q: Is it possible to walk to the zoo from here? — A: Yes, it's possible, but it takes an hour.","t":"從這裡走路到動物園可能嗎？ — 可以，但要走一個小時。"},{"w":"favorite","p":"adj.","d":"","c":"最喜愛的","s":"Q: What fruit do you like best? — A: Strawberries. They are my favorite fruit.","t":"你最喜歡什麼水果？ — 草莓，它們是我最愛的水果。"},{"w":"own","p":"adj.","d":"","c":"自己的","s":"Q: Do you and your brother share a room? — A: No, we don't. I have my own room.","t":"你和你哥哥共用一間房間嗎？ — 沒有，我有自己的房間。"},{"w":"only","p":"adj.","d":"","c":"唯一的","s":"Q: Does Amy have any brothers or sisters? — A: No, she doesn't. She is an only child.","t":"艾美有兄弟姊妹嗎？ — 沒有，她是獨生女。"},{"w":"other","p":"adj.","d":"","c":"其他的","s":"Q: Do all the students go home after school? — A: No, they don't. Some go home, and the other students stay for clubs.","t":"所有學生放學都回家嗎？ — 不是，有些回家，其他學生留下來參加社團。"},{"w":"else","p":"adj.","d":"","c":"別的","s":"Q: I want a hamburger. Do you want anything else? — A: Yes. I want some fries, too.","t":"我要一個漢堡。你還要別的東西嗎？ — 要，我也想要一些薯條。"},{"w":"enough","p":"adj.","d":"","c":"足夠的","s":"Q: Does Ben have enough money for the ticket? — A: No, he doesn't. He needs ten more dollars.","t":"班有足夠的錢買票嗎？ — 沒有，他還需要十元。"},{"w":"main","p":"adj.","d":"","c":"主要的","s":"Q: Where do your parents wait for you after school? — A: They wait at the main gate of the school.","t":"放學後你爸媽在哪裡等你？ — 他們在學校大門等。"},{"w":"national","p":"adj.","d":"","c":"國家的","s":"Q: Why don't we go to school on October 10? — A: Because it's a national holiday.","t":"為什麼我們十月十日不用上學？ — 因為那天是國定假日。"},{"w":"American","p":"adj.","d":"","c":"美國的","s":"Q: What kind of food does Tom like? — A: He likes American food, like hamburgers and hot dogs.","t":"湯姆喜歡哪種食物？ — 他喜歡美國食物，像漢堡和熱狗。"},{"w":"present","p":"adj.","d":"","c":"出席的","s":"Q: Does the teacher check who is here every morning? — A: Yes, she does. Today all thirty students are present.","t":"老師每天早上都會點名嗎？ — 會，今天三十個學生全部出席。"},{"w":"dear","p":"adj.","d":"","c":"親愛的","s":"Q: How does Lisa start her letter to her grandma? — A: She writes, \"dear Grandma, …\"","t":"麗莎寫信給奶奶時怎麼開頭？ — 她寫：「親愛的奶奶，……」"}]},{"unit":39,"theme":"Other Adverbs 其他副詞（第37區）","cards":[{"w":"always","p":"adv.","d":"","c":"總是","s":"Q: How often does Amy walk to school? — A: She always walks to school. She lives near it.","t":"艾美多常走路上學？ — 她總是走路上學，她住在學校附近。"},{"w":"usually","p":"adv.","d":"","c":"通常","s":"Q: How often do you get up at seven? — A: I usually get up at seven.","t":"你多常七點起床？ — 我通常七點起床。"},{"w":"often","p":"adv.","d":"","c":"時常","s":"Q: How often do your grandparents visit you? — A: They often visit us. They come every weekend.","t":"你的祖父母多常來看你？ — 他們常常來看我們，每個週末都來。"},{"w":"sometimes","p":"adv.","d":"","c":"有時候","s":"Q: How often do you and your friends play basketball? — A: We sometimes play basketball after school.","t":"你和朋友多常打籃球？ — 我們有時候放學後打籃球。"},{"w":"seldom","p":"adv.","d":"","c":"很少","s":"Q: How often do you eat fast food? — A: I seldom eat it. I eat it once a month.","t":"你多常吃速食？ — 我很少吃，一個月吃一次。"},{"w":"never","p":"adv.","d":"","c":"從不","s":"Q: How often do your parents drink coffee? — A: They never drink coffee. They drink tea.","t":"你爸媽多常喝咖啡？ — 他們從不喝咖啡，他們喝茶。"},{"w":"ever","p":"adv.","d":"","c":"曾經；有時","s":"Q: Does Lisa ever cook dinner? — A: Yes, she does. She cooks on Sundays.","t":"麗莎有時會煮晚餐嗎？ — 會，她星期天會煮。"},{"w":"twice","p":"adv.","d":"","c":"兩次","s":"Q: How often do you brush your teeth? — A: I brush my teeth twice a day.","t":"你多常刷牙？ — 我一天刷兩次牙。"},{"w":"badly","p":"adv.","d":"","c":"差勁地","s":"Q: How does Ben sing? — A: He sings badly, but he enjoys singing.","t":"班唱歌唱得怎麼樣？ — 他唱得很差，但他很喜歡唱歌。"},{"w":"together","p":"adv.","d":"","c":"一起","s":"Q: How do you and your brother go to school? — A: We walk to school together.","t":"你和你弟弟怎麼上學？ — 我們一起走路上學。"},{"w":"again","p":"adv.","d":"","c":"再一次","s":"Q: What do you say when you can't hear the teacher? — A: I say, \"Can you say it again, please?\"","t":"你聽不清楚老師說話時會說什麼？ — 我會說：「可以請您再說一次嗎？」"},{"w":"abroad","p":"adv.","d":"","c":"在國外","s":"Q: Where does your cousin study? — A: She studies abroad. She is in Canada now.","t":"你的表姊在哪裡讀書？ — 她在國外讀書，現在在加拿大。"},{"w":"away","p":"adv.","d":"","c":"離開；不在","s":"Q: Is your dad at home this week? — A: No, he isn't. He is away on a trip.","t":"你爸爸這週在家嗎？ — 不在，他出門旅行了。"},{"w":"ahead","p":"adv.","d":"","c":"向前；在前方","s":"Q: How do I get to the train station? — A: Go straight ahead. It's on your left.","t":"我要怎麼去火車站？ — 往前直走，就在你的左邊。"},{"w":"somewhere","p":"adv.","d":"","c":"某處","s":"Q: Where does Mom keep the cookies? — A: She keeps them somewhere in the kitchen. Let's look for them!","t":"媽媽把餅乾放在哪裡？ — 她放在廚房的某個地方，我們去找吧！"},{"w":"also","p":"adv.","d":"","c":"也","s":"Q: What does your mother do? — A: She is a nurse. She also teaches English at night.","t":"你媽媽做什麼工作？ — 她是護士，晚上也教英文。"},{"w":"too","p":"adv.","d":"","c":"也","s":"Q: I like dogs. Do you like dogs? — A: Yes, I do. I like dogs, too.","t":"我喜歡狗，你喜歡狗嗎？ — 喜歡，我也喜歡狗。"},{"w":"either","p":"adv.","d":"","c":"也（不）","s":"Q: Ben doesn't like tea. Does his sister like tea? — A: No, she doesn't. She doesn't like tea, either.","t":"班不喜歡茶，他妹妹喜歡茶嗎？ — 不喜歡，她也不喜歡茶。"},{"w":"still","p":"adv.","d":"","c":"仍然","s":"Q: Does your grandpa work? He is seventy. — A: Yes, he does. He still works on his farm.","t":"你爺爺還在工作嗎？他七十歲了。 — 是的，他仍然在他的農場工作。"},{"w":"yet","p":"adv.","d":"","c":"還（沒）","s":"Q: Does your little brother go to school? — A: No, he doesn't. He doesn't go to school yet. He is four.","t":"你弟弟上學了嗎？ — 還沒，他還沒上學，他四歲。"},{"w":"just","p":"adv.","d":"","c":"只是；只","s":"Q: Do you want a big lunch? — A: No, I don't. I just want a sandwich.","t":"你午餐想吃很多嗎？ — 不，我只想要一個三明治。"},{"w":"very","p":"adv.","d":"","c":"非常","s":"Q: How do the cookies taste? — A: They taste very good. Can I have more?","t":"這些餅乾吃起來怎樣？ — 非常好吃，我可以再吃一些嗎？"},{"w":"so","p":"adv.","d":"","c":"如此地；好","s":"Q: Do you like the new puppy? — A: Yes, I do. It's so cute!","t":"你喜歡這隻新小狗嗎？ — 喜歡，牠好可愛！"},{"w":"quite","p":"adv.","d":"","c":"相當","s":"Q: Is the math test hard? — A: No, it isn't. It's quite easy.","t":"數學考試難嗎？ — 不難，相當簡單。"},{"w":"really","p":"adv.","d":"","c":"真地","s":"Q: Do your parents like the new house? — A: Yes, they do. They really like the big garden.","t":"你爸媽喜歡新房子嗎？ — 喜歡，他們真的很喜歡那個大花園。"},{"w":"almost","p":"adv.","d":"","c":"幾乎；差不多","s":"Q: Does the movie start soon? — A: Yes, it does. It's almost seven o'clock.","t":"電影快開始了嗎？ — 是的，差不多七點了。"},{"w":"even","p":"adv.","d":"","c":"甚至；更","s":"Q: Does Tom run fast? — A: Yes, he does. He runs even faster than his big brother.","t":"湯姆跑得快嗎？ — 快，他甚至跑得比他哥哥還快。"},{"w":"only","p":"adv.","d":"","c":"只有；僅","s":"Q: How many pens do you have? — A: I only have one pen. Can I borrow one?","t":"你有幾支筆？ — 我只有一支筆，可以借我一支嗎？"},{"w":"least","p":"adv.","d":"","c":"最不","s":"Q: Which bag do you want to buy? — A: I want the least expensive one. It's $100.","t":"你想買哪一個包包？ — 我要最便宜的那個，一百元。"},{"w":"maybe","p":"adv.","d":"","c":"也許","s":"Q: Does Amy know the answer? — A: Maybe she does. Let's ask her.","t":"艾美知道答案嗎？ — 也許她知道，我們問她吧。"},{"w":"perhaps","p":"adv.","d":"","c":"或許","s":"Q: What do you want to do this weekend? — A: Perhaps we can go to the zoo.","t":"你這個週末想做什麼？ — 或許我們可以去動物園。"},{"w":"probably","p":"adv.","d":"","c":"很可能","s":"Q: Do we need an umbrella today? — A: Yes, we do. It will probably rain this afternoon.","t":"我們今天需要帶傘嗎？ — 需要，今天下午很可能會下雨。"},{"w":"actually","p":"adv.","d":"","c":"事實上","s":"Q: Does Mr. Smith come from America? — A: No, he doesn't. Actually, he comes from Canada.","t":"史密斯先生來自美國嗎？ — 不是，事實上，他來自加拿大。"},{"w":"then","p":"adv.","d":"","c":"然後；那時","s":"Q: What do you do after school? — A: I do my homework first, and then I play games.","t":"你放學後做什麼？ — 我先寫功課，然後玩遊戲。"},{"w":"finally","p":"adv.","d":"","c":"終於；最後","s":"Q: How long does Tom wait for the bus? — A: He waits for thirty minutes, and the bus finally comes.","t":"湯姆等公車等多久？ — 他等了三十分鐘，公車終於來了。"},{"w":"yes (yeah)","p":"adv.","d":"","c":"是；對","s":"Q: Do you like apples? — A: Yes, I do. They are sweet.","t":"你喜歡蘋果嗎？ — 是的，我喜歡，它們很甜。"},{"w":"no","p":"adv.","d":"","c":"不；沒有","s":"Q: Does Lisa have a pet? — A: No, she doesn't. Her mom doesn't like animals.","t":"麗莎有養寵物嗎？ — 沒有，她媽媽不喜歡動物。"},{"w":"not","p":"adv.","d":"","c":"不（否定）","s":"Q: Does Ben like math? — A: No, he does not. He likes English.","t":"班喜歡數學嗎？ — 不，他不喜歡，他喜歡英文。"},{"w":"OK","p":"adv.","d":"","c":"好；可以","s":"Q: Can I sit here? — A: OK. Sit down, please.","t":"我可以坐這裡嗎？ — 好，請坐。"}]}];
